import subprocess, re, glob
partials=set()
for f in glob.glob("/tmp/tmpl_*.txt")+glob.glob("/tmp/datafiles/*"):
    try: txt=open(f,errors='ignore').read()
    except: continue
    for m in re.findall(r'\$([a-zA-Z0-9_./-]+)\(\)\$',txt):
        partials.add(m)
print(sorted(partials))
def run(a):
    return subprocess.run(['/tmp/executable']+a,capture_output=True)
for p in sorted(partials):
    for cand in [f"templates/{p}", p]:
        r=run([f"--print-default-data-file={cand}"])
        if r.returncode==0:
            print("OK",cand,len(r.stdout))
            open("/tmp/datafiles/"+cand.replace("/","__"),"wb").write(r.stdout)
            break
    else:
        print("FAIL",p)
PY"}

