    idx=spec.find(".lua")
    if idx!=-1 and (idx+4==len(spec) or spec[idx+4] in '+-'):
        is_custom=True
        base_raw=spec[:idx+4]
        rest=spec[idx+4:]
    else:
        # split first + or - at position >=1
        m=re.search(r'[+-]', spec[1:])
        if m:
            pos=1+m.start()
            base_raw=spec[:pos]
            rest=spec[pos:]
        else:
            base_raw=spec
            rest=""
    # extensions parse
    extensions=[]
    if rest:
        # rest pattern ([+-][^+-]*)+ . trailing whitespace in last ext stripped (space tab cr) (?) 
        i=0
        while i < len(rest):
            if rest[i] not in '+-':
                # Should not happen
                break
            sign=rest[i]; i+=1
            start=i
            while i < len(rest) and rest[i] not in '+-':
                i+=1
            name=rest[start:i]
