from .util import read_resource
from .errors import PandocError

def _read_meta_text(name):
    data=read_resource(f"_meta/{name}")
    return data.decode() if data else ""
INPUT_FORMATS=_read_meta_text("input_formats.txt").splitlines()
OUTPUT_FORMATS=_read_meta_text("output_formats.txt").splitlines()
HIGHLIGHT_STYLES=_read_meta_text("highlight_styles.txt").splitlines()
HIGHLIGHT_LANGS=_read_meta_text("highlight_languages.txt").splitlines()

# Extensions defaults per format from --list-extensions captured
_EXT_DEFAULTS={}
_EXT_SUPPORTED={}
def _load_extensions():
    # we can't list files in zip easily; use all known format names
    names=[]
    for n in INPUT_FORMATS+OUTPUT_FORMATS:
        if n not in names: names.append(n)
    for fmt in names:
        data=read_resource(f"_meta/extensions/{fmt}.txt")
        if data is None:
            # for e.g. markdown variants maybe files exist for all; defaults empty
            _EXT_DEFAULTS[fmt]={}
            _EXT_SUPPORTED[fmt]=set()
            continue
        defaults={}
        supported=set()
        for line in data.decode().splitlines():
            if not line: continue
            sign=line[0]; name=line[1:].strip()
            if name:
                supported.add(name)
                defaults[name]=(sign=='+')
        _EXT_DEFAULTS[fmt]=defaults
        _EXT_SUPPORTED[fmt]=supported
_load_extensions()
# Use ext_table probed for precise supported per reader/writer (if available)
try:
    _ext_table=json.loads(_read_meta_text("ext_table.json") or "{}")
except Exception:
    _ext_table={}
READER_SUPPORTED=_ext_table.get("reader",{}) if isinstance(_ext_table,dict) else {}
WRITER_SUPPORTED=_ext_table.get("writer",{}) if isinstance(_ext_table,dict) else {}

def list_extensions_text(fmt):
    # fmt may be None -> markdown
    if fmt is None:
        fmt="markdown"
    # Format lookup is case-sensitive for --list-extensions (observed)
    names=INPUT_FORMATS+OUTPUT_FORMATS
    if fmt not in names:
        raise PandocError(f"{fmt} is not a recognized reader or writer format\n",6)
    data=read_resource(f"_meta/extensions/{fmt}.txt")
    if data is None:
        # construct from defaults (?) empty
        return ""
    return data.decode()

def parse_format_spec(spec, direction):
    """direction 'reader' or 'writer' . Returns (base_format_lowercase_or_custom_path, extensions_dict_or_None_for_custom, is_custom_lua, raw_extensions_list)
    Raise PandocError codes 20/21/22/23 as pandoc.
    For custom lua, extensions are ignored? pandoc checks? If file not found in reader selection, lua error - caller handles. Extensions after .lua probably ignored in parse (maybe also validated as ?) Probe with existing custom file later.
    """
    orig=spec
    if spec=="" :
        raise PandocError(f'Error parsing format "": (line 1, column 1):\nunexpected end of input\n',20)
    if spec[0] in '+-':
        raise PandocError(f"Error parsing format \"{spec}\": (line 1, column 1):\nunexpected '{spec[0]}'\n",20)
    # Locate .lua custom boundary
    is_custom=False
    base_raw=None
    rest=""
    # find .lua that is followed by end or +/-
    idx=spec.find(".lua")
    if idx!=-1 and (idx+4==len(spec) or spec[idx+4] in '+-'):
        is_custom=True
        base_raw=spec[:idx+4]
        rest=spec[idx+4:]
    else:
        # split first + or - at position >=1
        m=re.search(r'[+-]', spec[1:])
        if m:
            pos=1+m.start()
            base_raw=spec[:pos]
            rest=spec[pos:]
        else:
            base_raw=spec
            rest=""
    # extensions parse
    extensions=[]
    if rest:
        # rest pattern ([+-][^+-]*)+ . trailing whitespace in last ext stripped (space tab cr) (?) 
        i=0
        while i < len(rest):
            if rest[i] not in '+-':
                # Should not happen
                break
            sign=rest[i]; i+=1
            start=i
            while i < len(rest) and rest[i] not in '+-':
