            raise PandocError("Unknown output format pdfTo create a pdf using pandoc, use -t latex|beamer|context|ms|html5|typst\nand specify an output file with .pdf extension (-o filename.pdf).\n",22)
    # Supported set
    if direction=="reader" and base in READER_SUPPORTED:
        supported=set(READER_SUPPORTED[base])
    elif direction=="writer" and base in WRITER_SUPPORTED:
        supported=set(WRITER_SUPPORTED[base])
    else:
        supported=_EXT_SUPPORTED.get(base,set())
