    for s in supported:
        if s not in exts: exts[s]=False
    for sign,name in extensions:
        lname=name.lower()
        if lname not in supported:
            raise PandocError(f"The extension {lname} is not supported for {base}.\nUse --list-extensions={base} to list supported extensions.\n",23)
        exts[lname]=(sign=='+')
    return (base, exts, False, extensions)

def default_extensions(fmt):
    return dict(_EXT_DEFAULTS.get(fmt,{}))
