    DESC_BY_CANON[canon]=d

def bool_display(d):
    longs=[x[0] for x in d['longs']]
    shorts=[x[0] for x in d['shorts']]
    if shorts:
        return f"--{longs[0]}/-{shorts[0]}"
    if len(longs)>1:
        return f"--{longs[0]}/--{longs[1]}"
    return f"--{longs[0]}"

def parse_bool_opt(value, d):
    if value is None:
        return True
    if isinstance(value,bool):
        return value
    s=str(value)
    if s.lower()=="true":
        return True
    if s.lower()=="false":
        return False
    raise PandocError(f"Argument of {bool_display(d)} must be either true or false\n",6)

def parse_haskell_int(s):
    if isinstance(s,int) and not isinstance(s,bool):
        return s
    if s is None: return None
    text=str(s).strip()
    # Haskell Read for Int: optional minus, decimal or 0x/0o ; spaces surrounding allowed
    m=re.fullmatch(r'(-?)(0[xX][0-9a-fA-F]+|0[oO][0-7]+|\d+)', text)
    if not m:
        return None
    sign=-1 if m.group(1)=='-' else 1
    num=m.group(2)
    if num.lower().startswith('0x'):
        return sign*int(num,16)
    if num.lower().startswith('0o'):
        return sign*int(num,8)
    return sign*int(num,10)

