def split_key_value(s, default_value=True):
    # For -M / -V : separator is first ':' or '=' ? Manual says either. What if value contains ':' before '='? Eg -M title:foo=bar , value foo=bar. -V key=val:with:colons. We use earliest occurrence of ':' or '='.
    # But keys may contain ??? Dots okay.
    # There is nuance: For --metadata, help says KEY[:VALUE] but manual says KEY[=VAL] / KEY[:VAL] both. Tests show -M title=Hello works and -M title:Hello both.
    if s is None:
        return "", default_value
    idxs=[i for i,ch in enumerate(s) if ch in ':='] 
    # hmm if key itself? just first
    if not idxs:
        return s, default_value
    i=idxs[0]
    return s[:i], s[i+1:]

