# ---------- attributes ----------
def parse_attr_string(s):
    # s inside { }
    s=s.strip()
    ident=""; classes=[]; kvs=[]
    i=0
    tokens=[]
    # tokenize respecting quotes
    while i < len(s):
        while i < len(s) and s[i].isspace(): i+=1
