                if c=='\\' and i+1<len(s): i+=2; continue
                if c==in_q: in_q=None; i+=1; continue
                i+=1; continue
            else:
                if c in '"\'':
                    in_q=c; i+=1; continue
                if c.isspace(): break
                i+=1
        tokens.append(s[start:i])
    for tok in tokens:
        if tok.startswith('#') and len(tok)>1:
            ident=tok[1:]
        elif tok.startswith('.') and len(tok)>1:
            classes.append(tok[1:])
        elif tok=="-":
            classes.append("unnumbered")
        elif '=' in tok:
            k,v=tok.split('=',1)
            # unquote v
            if len(v)>=2 and ((v[0]=='"' and v[-1]=='"') or (v[0]=="'" and v[-1]=="'")):
