                v=re.sub(r'\\(.)',r'\1',v)
            kvs.append([k,v])
        else:
            # bare class name
            if tok:
                classes.append(tok)
    return [ident,classes,kvs]

def parse_braced_attr(text, pos):
    # text[pos]=='{' ; returns (attr, endpos) or (raw_attr_formatstring,...) check caller
    # Find matching } respecting quotes/escapes (no nested braces usually)
    i=pos+1; in_q=None
    while i < len(text):
        c=text[i]
        if c=='\\' and i+1<len(text): i+=2; continue
        if in_q:
            if c==in_q: in_q=None
        else:
            if c in '"\'': in_q=c
            elif c=='}':
                inner=text[pos+1:i]
                return inner, i+1
            elif c=='\n':
