    # Pandoc: if classes include smallcaps, wrap SmallCaps; if underline, wrap Underline. Outer span if remaining attr non-empty.
    # Order based observed single. For both, guessing smallcaps inside underline? Not crucial.
    has_sc = 'smallcaps' in classes
    has_u = 'underline' in classes
    if has_sc:
        classes=[c for c in classes if c!='smallcaps']
