            if self.ctx.ext("tex_math_single_backslash",False):
                end=text.find(r'\)', pos+2)
                if end!=-1:
                    self.append_node(I("Math",[I("InlineMath"), text[pos+2:end]])); self.pos=end+2; return True
            # fall through to raw tex?
        if nxt=='[' and self.ctx.ext("tex_math_single_backslash",False):
            end=text.find(r'\]', pos+2)
            if end!=-1:
                self.append_node(I("Math",[I("DisplayMath"), text[pos+2:end]])); self.pos=end+2; return True
        if nxt==' ':
            # escaped space -> nonbreaking space in current Str
            self.buf+='\u00a0'; self.pos+=2; return True
        # If double backslash math? At first \ next \ is punctuation escapable -> would become \, not math. tex_math_double_backslash means literally "\\(x\\)" (two chars backslash in md source)
        if nxt=='\\' and self.ctx.ext("tex_math_double_backslash",False):
            # check \\( or \\[
            if pos+2<n and text[pos+2] in '([':
                is_disp=text[pos+2]=='['
                closer=r'\\]' if is_disp else r'\\)'
                end=text.find(closer, pos+3)
                if end!=-1:
                    typ="DisplayMath" if is_disp else "InlineMath"
                    self.append_node(I("Math",[I(typ), text[pos+3:end]])); self.pos=end+len(closer); return True
        # escapable characters
        if nxt:
            all_sym=self.ctx.ext("all_symbols_escapable",False)
            escapable_ascii_punct = nxt in "!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~"
            if escapable_ascii_punct or (all_sym and unicodedata.category(nxt).startswith(('P','S'))):
                self.buf+=nxt; self.pos+=2; return True
            # footnote etc? 
            if nxt.isalpha():
                # raw tex if enabled for reader format
                # For formats like latex reader handled elsewhere; for markdown raw_tex ext
                if self.ctx.ext("raw_tex",False):
                    raw,end = parse_raw_tex_command(text,pos)
                    if raw is not None:
                        self.append_node(I("RawInline",[I("Format","tex"),raw])); self.pos=end; return True
                # else treat backslash as literal
                self.buf+='\\'; self.pos+=1; return True
            else:
                self.buf+='\\'; self.pos+=1; return True
        self.buf+='\\'; self.pos+=1; return True
    def handle_code(self):
        text=self.text; start=self.pos
        # count backticks
        i=start
        while i<self.n and text[i]=='`': i+=1
        run=i-start
        # find closing run exactly run length, not part of longer
        pos=i
        closing=-1; closing_end=-1
        while pos<self.n:
            idx=text.find('`'*run, pos)
            if idx==-1: break
            end=idx+run
            # if longer run, skip whole longer
            if end<self.n and text[end]=='`':
                # skip entire longer run
                j=end
                while j<self.n and text[j]=='`': j+=1
                pos=j; continue
            # if preceded by backtick part of longer? idx is start of a run because find starts anywhere, if text[idx-1]==` then this is subset; but pos advancement ensures...
            if idx>0 and text[idx-1]=='`':
                pos=idx+1; continue
            closing=idx; closing_end=end; break
        if closing==-1:
            self.buf+='`'*run; self.pos=i; return True
        content=text[i:closing]
        # normalize per CommonMark: line endings -> space, strip one leading/trailing space if both and not all spaces
        content_disp=content.replace('\n',' ')
        if len(content_disp)>=2 and content_disp[0]==' ' and content_disp[-1]==' ' and content_disp.strip()!='':
            content_disp=content_disp[1:-1]
        self.pos=closing_end
        attr=empty_attr()
        raw_format=None
        # optional attributes
        if self.pos<self.n and text[self.pos]=='{' and (self.ctx.ext("inline_code_attributes",False) or self.ctx.ext("raw_attribute",False) or self.ctx.ext("fenced_code_attributes",False)):
            inner,end=parse_braced_attr(text,self.pos)
            if inner is not None:
                inner_s=inner.strip()
                if inner_s.startswith('=') and self.ctx.ext("raw_attribute",False):
                    raw_format=inner_s[1:].strip()
                    self.pos=end
                elif self.ctx.ext("inline_code_attributes",False):
                    attr=parse_attr_string(inner); self.pos=end
        if raw_format is not None:
            # raw inline content is original content (not stripped?) Pandoc for `a`{=html} raw "a" . For code with spaces normalization likely use content as in code?
            self.append_node(I("RawInline",[I("Format",raw_format),content_disp]))
        else:
            self.append_node(I("Code",[attr,content_disp]))
        return True
    def handle_angle(self):
        text=self.text
        # autolink
        m=re.match(r'<([A-Za-z][A-Za-z0-9+.-]{1,31}:[^<>\s]*)>', text[self.pos:])
        if m:
            uri=m.group(1)
            self.append_node(I("Link",[["",["uri"],[]], [I("Str",uri)], [uri,""]]))
            self.pos+=len(m.group(0)); return True
        m=re.match(r'<([A-Za-z0-9.!#$%&\'*+\/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)*)>', text[self.pos:])
        if m:
            email=m.group(1)
            self.append_node(I("Link",[["",["email"],[]], [I("Str",email)], ["mailto:"+email,""]]))
            self.pos+=len(m.group(0)); return True
        if self.ctx.ext("raw_html",False):
            raw,end=parse_raw_html_inline(text,self.pos)
            if raw is not None:
                self.append_node(I("RawInline",[I("Format","html"),raw])); self.pos=end; return True
        # literal<
        # angle_brackets_escapable irrelevant
        self.buf+='<'; self.pos+=1; return True
    def handle_entity(self):
        text=self.text
        m=re.match(r'&(#x[0-9a-fA-F]+|#[0-9]+|[A-Za-z][A-Za-z0-9]+);', text[self.pos:])
        if not m:
            # maybe without semicolon for known ? Pandoc only with?
            self.buf+='&'; self.pos+=1; return True
        ent=m.group(0)
        decoded=html.unescape(ent)
        if decoded==ent:
            # unknown entity -> keep as text? Pandoc parses &copy etc; unknown &foo; may remain? Let's append literally
            self.buf+=ent; self.pos+=len(ent); return True
        # If decoded is space? nbsp etc append to buffer
        self.buf+=decoded; self.pos+=len(ent); return True
    # Links and images
    def handle_link_or_image(self,is_image=False):
        start=self.pos
        bracket_start=start+1 if is_image else start
        # caller only for image, link handled in handle_bracket
        res=self.try_parse_link_at(bracket_start,is_image)
        if res is None:
            return False
        node,end=res
        self.append_node(node); self.pos=end; return True
    def handle_bracket(self):
        # Footnote ref
        text=self.text
        if text.startswith("[^",self.pos) and self.ctx.ext("footnotes",False):
            end=text.find("]",self.pos+2)
            if end!=-1:
                label=text[self.pos+2:end].strip()
                if label in self.ctx.footnotes:
                    blocks=copy.deepcopy(self.ctx.footnotes[label])
                    # convert placeholders in footnote blocks
                    blocks=convert_placeholders_in_blocks(blocks,self.ctx)
                    self.append_node(I("Note",blocks)); self.pos=end+1; return True
                # if no definition, fall through as text? Let it try link (won't) then append '['
        # Wikilinks [[...]]
        if (self.ctx.ext("wikilinks_title_after_pipe",False) or self.ctx.ext("wikilinks_title_before_pipe",False)) and text.startswith("[[",self.pos):
            end=text.find("]]",self.pos+2)
            if end!=-1:
                inner=text[self.pos+2:end]
                if '|' in inner:
                    a,b=inner.split('|',1)
                    if self.ctx.ext("wikilinks_title_after_pipe",False):
                        url,title=a,b
                    else:
                        title,url=a,b
                else:
                    url=title=inner
                inlines=parse_inlines(title,self.ctx,allow_links=False) if False else InlineParser(self.ctx,title,allow_links=False).parse()
                # wikilink class
                self.append_node(I("Link",[["",["wikilink"],[]],inlines,[url,""]])); self.pos=end+2; return True
        # Citation bracket if content appears citation and no link reflabel? We attempt after link try? Pandoc precedence citations over links for bracketed citations.
        # try link
        res=self.try_parse_link_at(self.pos,False)
        if res is not None:
            node,end=res; self.append_node(node); self.pos=end; return True
        # bracketed span: find matching ] and then {attr}
        if self.ctx.ext("bracketed_spans",False):
            match=find_matching_bracket(text,self.pos)
            if match!=-1 and match+1<self.n and text[match+1]=='{':
                inner,end=parse_braced_attr(text,match+1)
                if inner is not None and not inner.strip().startswith('='):
                    attr=parse_attr_string(inner)
                    content=text[self.pos+1:match]
                    inlines=InlineParser(self.ctx,content,allow_links=self.allow_links).parse()
                    node=apply_span_attr(inlines,attr)
                    self.append_node(node); self.pos=end; return True
        # Citation bracket
        if self.ctx.ext("citations",False):
            cres=self.try_parse_bracket_citation(self.pos)
            if cres is not None:
                node,end=cres; self.append_node(node); self.pos=end; return True
        # no match: literal [
        self.buf+='['; self.pos+=1; return True
    def try_parse_link_at(self, bracket_pos, is_image):
        text=self.text
        if not self.allow_links and not is_image:
            return None
        match=find_matching_bracket(text,bracket_pos)
        if match==-1: return None
        content=text[bracket_pos+1:match]
        after=match+1
        url=None; title=""
        attr=empty_attr()
        endpos=None
        kind=None
        # inline link ( ... )
        if after<self.n and text[after]=='(':
            parsed=parse_link_destination(text,after)
            if parsed is not None:
                url,title,endpos=parsed; kind="inline"
        if kind is None:
            # full / collapsed reference: [label] (allow up to  ... no spaces?? CommonMark allows up to one space/softbreak between ]
            # pandoc spaced_reference_links extension allows space between two bracket components
            p=after
            # skip spaces if spaced_reference_links enabled or maybe single space? shortcut ref definitions...
            if self.ctx.ext("spaced_reference_links",False):
                while p<self.n and text[p] in ' \t\n': p+=1
            if p<self.n and text[p]=='[':
                match2=find_matching_bracket(text,p)
                if match2!=-1:
                    label_raw=text[p+1:match2]
                    if label_raw=="":
                        label_norm=normalize_ref_label_from_text(content,self.ctx)
                    else:
                        label_norm=normalize_ref_label(label_raw)
                    if label_norm in self.ctx.refs:
                        url,title=self.ctx.refs[label_norm]; endpos=match2+1; kind="ref"
                    else:
                        # If full reference but not found, it's literal (not shortcut)
                        return None
            # shortcut
            if kind is None and self.ctx.ext("shortcut_reference_links",True):
                label_norm=normalize_ref_label_from_text(content,self.ctx)
                if label_norm in self.ctx.refs:
                    url,title=self.ctx.refs[label_norm]; endpos=after; kind="shortcut"
                elif not is_image and self.ctx.ext("implicit_header_references",False):
                    # implicit header ref: content text matching header
                    hid=lookup_implicit_header(content,self.ctx)
                    if hid is not None:
                        url="#"+hid; title=""; endpos=after; kind="implicit"
                elif not is_image and self.ctx.ext("implicit_figures",False) and False:
                    pass
        if kind is None:
            return None
        # optional link attributes immediately after
        if endpos is not None and endpos<self.n and text[endpos]=='{' and self.ctx.ext("link_attributes",False):
            inner,end2=parse_braced_attr(text,endpos)
            if inner is not None:
                attr=parse_attr_string(inner); endpos=end2
        # parse content inlines no nested links (images allowed inside link)
        inlines=InlineParser(self.ctx,content,allow_links=False).parse()
        # For empty: still []
        node_type="Image" if is_image else "Link"
        return (I(node_type,[attr,inlines,[url,title]]), endpos)
    def handle_caret(self):
        text=self.text
        # inline note ^[ ... ]
        if self.ctx.ext("inline_notes",False) and self.peek(1)=='[':
            match=find_matching_bracket(text,self.pos+1)
            if match!=-1:
                content=text[self.pos+2:match]
                # Note blocks: parse content as blocks if contains blank lines else Para of inlines
                if "\n\n" in content:
                    blocks=parse_blocks_from_string(content,self.ctx)
                else:
                    inlines=InlineParser(self.ctx,content).parse()
                    blocks=[B("Para",inlines)]
                self.append_node(I("Note",blocks)); self.pos=match+1; return True
        if self.ctx.ext("superscript",False):
            # direct scan for closing ^
            end=text.find('^',self.pos+1)
            if end!=-1:
                content=text[self.pos+1:end]
                if '\n' not in content and not re.search(r'(?<!\\) ',content):
                    # content may be empty (^^) => Superscript []
                    inlines=InlineParser(self.ctx,content).parse() if content else []
                    self.append_node(I("Superscript",inlines)); self.pos=end+1; return True
        self.buf+='^'; self.pos+=1; return True
    def handle_tilde(self):
        text=self.text
        # strikeout ~~
        if text.startswith("~~",self.pos) and self.ctx.ext("strikeout",False):
            # char after not space/newline?
            after=text[self.pos+2] if self.pos+2<self.n else ""
            if after not in (' ','\t','\n',''):
                end=text.find("~~",self.pos+2)
                if end!=-1:
                    # char before closing not space
                    if end>self.pos+2 and text[end-1] not in ' \t\n':
                        content=text[self.pos+2:end]
                        inlines=InlineParser(self.ctx,content).parse()
                        self.append_node(I("Strikeout",inlines)); self.pos=end+2; return True
        if self.ctx.ext("subscript",False):
            end=text.find('~',self.pos+1)
            if end!=-1:
                content=text[self.pos+1:end]
                if '\n' not in content and not re.search(r'(?<!\\) ',content):
                    # If we are at ~~ and strike failed due space after, content is empty (second ~) => Subscript []
                    inlines=InlineParser(self.ctx,content).parse() if content else []
                    self.append_node(I("Subscript",inlines)); self.pos=end+1; return True
        self.buf+='~'; self.pos+=1; return True
    def handle_delim(self,c):
        text=self.text; start=self.pos
        i=start
        while i<self.n and text[i]==c: i+=1
        run=i-start
        before=text[start-1] if start>0 else (self.prev_char or "\n")
        after=text[i] if i<self.n else (self.next_char or "\n")
        can_open,can_close=flanking(c,before,after,self.ctx)
        self.flush_buf()
        self.out.append({"t":"__Delim","c":[c,run,can_open,can_close]})
        self.pos=i; return True
    def handle_dollar(self):
        if not self.ctx.ext("tex_math_dollars",False):
            self.buf+='$'; self.pos+=1; return True
        text=self.text
        # display $$
        if text.startswith("$$",self.pos):
            end=text.find("$$",self.pos+2)
            if end!=-1:
                content=text[self.pos+2:end]
                # display math content can span? Nonempty? Conditions loose
                if content.strip()!="":
                    self.append_node(I("Math",[I("DisplayMath"),content])); self.pos=end+2; return True
            self.buf+="$$"; self.pos+=2; return True
        # inline $
        if self.pos+1<self.n and text[self.pos+1] not in ' \t\n':
            # find next $, conditions: before closing not space, after closing not digit (for pandoc)
            pos=self.pos+1
            while True:
                end=text.find('$',pos)
                if end==-1: break
                if end>self.pos+1 and text[end-1] not in ' \t\n' and not (end+1<self.n and text[end+1].isdigit()):
                    content=text[self.pos+1:end]
                    if '\n\n' not in content:
                        self.append_node(I("Math",[I("InlineMath"),content])); self.pos=end+1; return True
                pos=end+1
        self.buf+='$'; self.pos+=1; return True
    def handle_mark(self):
        text=self.text
        if text.startswith("==",self.pos):
            end=text.find("==",self.pos+2)
            if end!=-1 and end>self.pos+2:
                inlines=InlineParser(self.ctx,text[self.pos+2:end]).parse()
                # mark extension produces Span with class mark? Test with markdown+mark later; assume Span mark (writers turn into <mark>)
                self.append_node(I("Span",[["",["mark"],[]],inlines])); self.pos=end+2; return True
        self.buf+='='; self.pos+=1; return True
    def handle_citation_at(self):
        # At sign followed by citation key, maybe followed by [suffix] etc. Also groups multiple citations separated by spaces/bracket to merge like pandoc ?
        res=try_parse_citation_group_at(self.text,self.pos,self.ctx)
        if res is None:
            self.buf+='@'; self.pos+=1; return True
        node,end=res; self.append_node(node); self.pos=end; return True
    def try_parse_bracket_citation(self,pos):
        # Bracket at pos, content up to matching ]
        match=find_matching_bracket(self.text,pos)
        if match==-1: return None
        content=self.text[pos+1:match]
        # must contain @
        if '@' not in content: return None
        cites=parse_citation_items(content,self.ctx)
        if cites is None: return None
        # display inlines are source text including brackets converted to inlines plainly (citation rendered by writer fallback). Pandoc builds display by parsing original text but treats @ etc as Str. For simplicity parse original bracket text with citations disabled? We can construct by tokenizing words with spaces.
        disp=simple_text_inlines(self.text[pos:match+1])
        return (I("Cite",[cites,disp]), match+1)
    def handle_double_quote(self):
        text=self.text; start=self.pos
        before=text[start-1] if start>0 else (self.prev_char or ' ')
        after=text[start+1] if start+1<self.n else ' '
        # opening conditions: before is space/punct/start, after not space
        if not (before.isspace() or before in '([{\'"' or unicodedata.category(before).startswith('P')) or after.isspace():
            # treat as closing curly in text (right double quote)
            self.buf+='”'; self.pos+=1; return True
        end=text.find('"',start+1)
        if end==-1:
            self.buf+='“'; self.pos+=1; return True
        # closing conditions: before end not space, after end not alphanumeric? quotes can be followed by punct/space/end
        if text[end-1].isspace():
            self.buf+='“'; self.pos+=1; return True
        # parse inner
        content=text[start+1:end]
        inlines=InlineParser(self.ctx,content,allow_links=self.allow_links).parse()
        self.append_node(I("Quoted",[I("DoubleQuote"),inlines])); self.pos=end+1; return True
    def handle_single_quote(self):
        text=self.text; start=self.pos
        before=text[start-1] if start>0 else (self.prev_char or ' ')
        after=text[start+1] if start+1<self.n else ' '
        # apostrophe cases: between letters/digits, or before letter with before space and word like 'tis -> right single quote (based on example). SingleQuote parse if before is boundary (space/punct) and after not space, and there is closing followed by non-letter.
        # If before is alphanumeric, it's apostrophe
        if before.isalnum():
            self.buf+='’'; self.pos+=1; return True
        if after.isspace() or after=='':
            self.buf+='’'; self.pos+=1; return True
        # look for closing '
        pos=start+1
        while True:
            end=text.find("'",pos)
            if end==-1:
                self.buf+='’'; self.pos+=1; return True
            after_close=text[end+1] if end+1<self.n else ''
            before_close=text[end-1] if end>0 else ''
            # closing ' should not be followed by letter (that would be apostrophe inside quoted word) unless word ends then?
            if not after_close.isalnum() and not before_close.isspace():
                content=text[start+1:end]
                # Heuristic: if content is a known contraction starting e.g. tis, and (?) No closing exists in sentence, above will fail if no close. If content has no space and end is far? Basic quotes usually maybe same word? Accept.
                inlines=InlineParser(self.ctx,content,allow_links=self.allow_links).parse()
                self.append_node(I("Quoted",[I("SingleQuote"),inlines])); self.pos=end+1; return True
            pos=end+1
    def handle_emoji(self):
        m=re.match(r':([A-Za-z0-9_+\-]+):',self.text[self.pos:])
        if m and m.group(1) in EMOJI_MAP:
            self.buf+=EMOJI_MAP[m.group(1)]; self.pos+=len(m.group(0)); return True
        return False
    def handle_dash(self):
        text=self.text
        # old_dashes: -- = em, - in number ranges = en? not default
        if self.ctx.ext("old_dashes",False):
            if text.startswith("--",self.pos):
                self.buf+='—'; self.pos+=2; return True
            return False
        if text.startswith("---",self.pos):
            self.buf+='—'; self.pos+=3; return True
        if text.startswith("--",self.pos):
            self.buf+='–'; self.pos+=2; return True
        return False

def flanking(c,before,after,ctx):
    # Unicode categories
    def is_ws(ch): return ch=='' or ch.isspace()
    def is_punct(ch): return ch!='' and unicodedata.category(ch).startswith(('P','S'))
    # Treat start/end sentinel \n as ws
    left_flanking = (not is_ws(after)) and (not is_punct(after) or is_ws(before) or is_punct(before))
    right_flanking = (not is_ws(before)) and (not is_punct(before) or is_ws(after) or is_punct(after))
    if c=='*':
        return left_flanking, right_flanking
    else: # _
        if ctx.ext("intraword_underscores",True):
            can_open = left_flanking and (not right_flanking or is_punct(before))
            can_close = right_flanking and (not left_flanking or is_punct(after))
            return can_open,can_close
        else:
            return left_flanking,right_flanking

def process_emphasis(items,ctx):
    # items may contain __Delim nodes
    # Use iterative list algorithm scanning closers
    # Make copy list
    items=list(items)
    # Helper to convert delim node to Str
    def delim_to_str(d):
        return I("Str", d["c"][0]*d["c"][1]) if d["c"][1]>0 else None
    # Find indices of delims
    idx=0
    # We'll implement process by scanning for closers left-to-right, each time trying match. When a closer matches, revisit from same position (closer might remain).
    # To avoid infinite loops, ensure progress.
    pos=0
    while pos < len(items):
        if items[pos].get("t")!="__Delim":
            pos+=1; continue
        closer=items[pos]
        c,count,can_open,can_close=closer["c"]
        if not can_close or count==0:
            pos+=1; continue
        # find nearest opener before pos with same char and can_open
        opener_idx=None
        for j in range(pos-1,-1,-1):
            if items[j].get("t")=="__Delim":
                oc,ocount,oopen,oclose=items[j]["c"]
                if oc!=c or not oopen or ocount==0: continue
                # rule of three if both can open and close
                if (can_open and oclose) or (oclose and can_open):
                    pass
                if (oopen and oclose) or (can_open and can_close):
                    # CommonMark condition more precisely: if both delimiter runs can open and close, not match if sum %3==0 unless both %3==0
                    if (ocount+count)%3==0 and not (ocount%3==0 and count%3==0):
                        continue
                opener_idx=j; break
        if opener_idx is None:
            pos+=1; continue
        opener=items[opener_idx]
        ocount=opener["c"][1]
        use=2 if (ocount>=2 and count>=2) else 1
        # content between, converting delims inside to Str
        content=[]
        for it in items[opener_idx+1:pos]:
            if it.get("t")=="__Delim":
                s=delim_to_str(it)
                if s: content.append(s)
            else:
                content.append(it)
