# Fenced div
def try_parse_fenced_div(lines,i,ctx):
    if not ctx.ext("fenced_divs",False): return None
    line=lines[i]
    m=re.match(r'^ {0,3}(:{3,})[ \t]*(.*)$',line)
    if not m: return None
    fence=m.group(1); info=m.group(2).strip()
    if info=="":
        # closing fence at block level without opening - not a start
        return None
    # info either {attr} or single class word
    # find closing line with at least as many colons and no other content
    n=len(lines); j=i+1; found=-1
    # Need handle nested divs: count openings with fence length <=? Simpler use recursive find matching by scanning and tracking depth based on plain closing fences
    depth=1
    while j<n:
        mm=re.match(r'^ {0,3}(:{3,})[ \t]*(.*)$',lines[j])
        if mm:
            if mm.group(2).strip()=="":
                if len(mm.group(1))>=len(fence):
                    depth-=1
                    if depth==0: found=j; break
                else:
                    # shorter closing could close inner if depth> (?) ignore
                    depth=max(0,depth-1)
                    if depth==0: found=j; break
            else:
                depth+=1
        j+=1
    if found==-1:
        return None
    if info.startswith('{') and info.endswith('}'):
        attr=parse_attr_string(info[1:-1])
    else:
        # single word class; maybe info contains spaces? `::: warning` etc
        # If info has spaces and not braced, pandoc only allows a single word? If multiple, not a div? Treat first as class and remainder? 
        attr=["",info.split(),[]]
    inner=parse_blocks(lines[i+1:found],ctx,top_level=False)
    return (B("Div",[attr,inner]),found+1)

