BULLET_RE=re.compile(r'^( {0,3})([-+*])([ \t]+)(.*)$')
ORDERED_RE=re.compile(r'^( {0,3})(\d{1,9}|[A-Za-z]|[ivxlcdmIVXLCDM]+|#|@)([.)])([ \t]+)(.*)$')
