def parse_list_marker(line,ctx):
    # returns dict or None
    # Example list (@) and (@label)
    m=re.match(r'^( {0,3})\(@([A-Za-z0-9_\-]*)\)([ \t]+)(.*)$',line)
    if m and ctx.ext("example_lists",False):
        return {"type":"ordered","style":"Example","delim":"TwoParens","start":None,"label":m.group(2),"indent":len(m.group(1)),"marker_width": len(line)-len(m.group(4))-len(m.group(3)) if False else (len(m.group(1))+len(m.group(2))+3), "content_col": len(m.group(1))+len(m.group(2))+3+len(m.group(3)), "rest":m.group(4),"marker_text":m.group(0)}
    m=BULLET_RE.match(line)
    if m:
        # Don't treat * * * thematic break as list: if rest after marker is thematic etc and whole line is hr, caller checks order. At block start, parse_blocks calls list before hr - for '* * *' marker '*' rest '* *' could be mis. Detect if line is thematic break, not list.
        if is_thematic_break(line): return None
        # Bullet marker can be + - *
        return {"type":"bullet","bullet_char":m.group(2),"indent":len(m.group(1)),"content_col":len(m.group(1))+1+len(m.group(3)), "rest":m.group(4)}
    # Ordered paren both
    m=ORDERED_PAREN_RE.match(line)
    if m and list_style_allowed(m.group(2),ctx):
        style,start=ordered_style(m.group(2))
        return {"type":"ordered","style":style,"delim":"TwoParens","start":start,"indent":len(m.group(1)),"content_col":len(m.group(1))+len(m.group(2))+2+len(m.group(3)),"rest":m.group(4)}
    m=ORDERED_RE.match(line)
    if m and list_style_allowed(m.group(2),ctx):
        style,start=ordered_style(m.group(2))
        delim="Period" if m.group(3)=='.' else "OneParen"
        # #.
        if m.group(2)=='#' :
            style="DefaultStyle"; delim="DefaultDelim"; start=1
        return {"type":"ordered","style":style,"delim":delim,"start":start,"indent":len(m.group(1)),"content_col":len(m.group(1))+len(m.group(2))+1+len(m.group(4)),"rest":m.group(5)}
    return None

def list_style_allowed(token,ctx):
    if token.isdigit(): return True
    if token=='#': return ctx.ext("fancy_lists",False)
    if token=='@': return ctx.ext("example_lists",False)
    # Alphabetic or roman numerals accepted if fancy_lists for pandoc markdown, or commonmark fancy etc. Commonmark only decimal.
    if ctx.reader_format in ("commonmark","commonmark_x","gfm") and not ctx.ext("fancy_lists",False):
        return False
    if token.isalpha():
        return ctx.ext("fancy_lists",True)
    return True

def ordered_style(token):
    if token.isdigit(): return "Decimal",int(token)
    if token=='#': return "DefaultStyle",1
    if re.fullmatch(r'[ivxlcdm]+',token) and token not in ('i','v','x','l','c','d','m') or token in ('ii','iii','iv','vi','vii','viii','ix','xi'):
        return "LowerRoman",roman_to_int(token)
    if re.fullmatch(r'[IVXLCDM]+',token) and len(token)>1:
        return "UpperRoman",roman_to_int(token.lower())
    if len(token)==1 and token.islower():
        # Could be roman i vs alpha a-i etc ambiguous: pandoc fancy list: i is roman, others? v/x etc maybe roman? Pandoc determines: single letter a-z except i,v,x,l,c,d,m maybe roman if next items sequential roman? Dawn. Data earlier: a. -> lower alpha 1, i. -> lower roman1. If start letter is i/v/x/l/c/d/m, likely roman? Test may include. Use roman for i and maybe v,x? Let's probe later. For now if token == 'i' lower roman; if 'I' UpperRoman.
        if token=='i': return "LowerRoman",1
        return "LowerAlpha",ord(token)-96
    if len(token)==1 and token.isupper():
        if token=='I': return "UpperRoman",1
        return "UpperAlpha",ord(token)-64
    if token.islower(): return "LowerRoman",roman_to_int(token)
    if token.isupper(): return "UpperRoman",roman_to_int(token.lower())
    return "Decimal",1

def roman_to_int(s):
    vals={'i':1,'v':5,'x':10,'l':50,'c':100,'d':500,'m':1000}
    total=0; prev=0
    for ch in reversed(s):
        v=vals.get(ch,0)
        if v<prev: total-=v
        else: total+=v; prev=v
    return total

def is_list_start(line,ctx):
