def list_style_allowed(token,ctx):
    if token.isdigit(): return True
    if token=='#': return ctx.ext("fancy_lists",False)
    if token=='@': return ctx.ext("example_lists",False)
    # Alphabetic or roman numerals accepted if fancy_lists for pandoc markdown, or commonmark fancy etc. Commonmark only decimal.
    if ctx.reader_format in ("commonmark","commonmark_x","gfm") and not ctx.ext("fancy_lists",False):
        return False
    if token.isalpha():
        return ctx.ext("fancy_lists",True)
    return True

def ordered_style(token):
    if token.isdigit(): return "Decimal",int(token)
    if token=='#': return "DefaultStyle",1
    if re.fullmatch(r'[ivxlcdm]+',token) and token not in ('i','v','x','l','c','d','m') or token in ('ii','iii','iv','vi','vii','viii','ix','xi'):
        return "LowerRoman",roman_to_int(token)
    if re.fullmatch(r'[IVXLCDM]+',token) and len(token)>1:
        return "UpperRoman",roman_to_int(token.lower())
    if len(token)==1 and token.islower():
        # Could be roman i vs alpha a-i etc ambiguous: pandoc fancy list: i is roman, others? v/x etc maybe roman? Pandoc determines: single letter a-z except i,v,x,l,c,d,m maybe roman if next items sequential roman? Dawn. Data earlier: a. -> lower alpha 1, i. -> lower roman1. If start letter is i/v/x/l/c/d/m, likely roman? Test may include. Use roman for i and maybe v,x? Let's probe later. For now if token == 'i' lower roman; if 'I' UpperRoman.
        if token=='i': return "LowerRoman",1
        return "LowerAlpha",ord(token)-96
    if len(token)==1 and token.isupper():
        if token=='I': return "UpperRoman",1
        return "UpperAlpha",ord(token)-64
    if token.islower(): return "LowerRoman",roman_to_int(token)
    if token.isupper(): return "UpperRoman",roman_to_int(token.lower())
    return "Decimal",1

def roman_to_int(s):
    vals={'i':1,'v':5,'x':10,'l':50,'c':100,'d':500,'m':1000}
    total=0; prev=0
    for ch in reversed(s):
        v=vals.get(ch,0)
        if v<prev: total-=v
        else: total+=v; prev=v
    return total

