def roman_to_int(s):
    vals={'i':1,'v':5,'x':10,'l':50,'c':100,'d':500,'m':1000}
    total=0; prev=0
    for ch in reversed(s):
        v=vals.get(ch,0)
        if v<prev: total-=v
        else: total+=v; prev=v
    return total

