# Metadata conversion
def yaml_to_metavalue(val,ctx):
    if isinstance(val,dict):
        return {"t":"MetaMap","c":{str(k):yaml_to_metavalue(v,ctx) for k,v in val.items() if not str(k).endswith('_')}}
    if isinstance(val,list):
        return {"t":"MetaList","c":[yaml_to_metavalue(v,ctx) for v in val]}
    if isinstance(val,bool):
        return {"t":"MetaBool","c":val}
    if val is None:
        return {"t":"MetaString","c":""}
    # numeric/date/string as text
    s=str(val)
    if "\n" in s.strip("\n") or s.endswith("\n") and "\n" in s.rstrip("\n"):
        # Parse as markdown blocks; if exactly one Para and no blank lines, Pandoc may still produce MetaBlocks for block scalars with multiple paras only. Determine: scalar from block style includes newline at end; our Yaml parser loses style. Heuristic: if contains a blank line -> MetaBlocks, else parse as inlines (with SoftBreak joins line). But earlier block scalar with two paras -> MetaBlocks. Folded scalars produce one para with \n end - probably MetaInlines? test later
        if "\n\n" in s:
            blocks=parse_blocks_from_string(s,ctx)
            blocks=convert_placeholders_in_blocks(blocks,ctx)
            return {"t":"MetaBlocks","c":blocks}
    if s.strip()=="":
        return {"t":"MetaString","c":""}
    inlines=InlineParser(ctx,s).parse()
    # trim spaces at ends
    while inlines and inlines[0].get("t") in ("Space","SoftBreak"): inlines.pop(0)
    while inlines and inlines[-1].get("t") in ("Space","SoftBreak"): inlines.pop()
    return {"t":"MetaInlines","c":inlines}

