    if t in ("Link","Image"): return Con(t,[attr_v(c[0]),ListV([inline_v(i) for i in c[1]]),target_v(c[2])])
    if t=="Note": return Con("Note",[ListV([block_v(b) for b in c])])
    if t=="Span": return Con("Span",[attr_v(c[0]),ListV([inline_v(i) for i in c[1]])])
    return AtomV(t)

def caption_v(cap):
    # cap = [short or None, blocks]
    if cap is None: cap=[None,[]]
    if cap[0] is None: short=AtomV("Nothing")
    else: short=Con("Just",[ListV([inline_v(i) for i in cap[0]])])
    return Con("Caption",[short,ListV([block_v(b) for b in cap[1]])])

def cell_v(cell):
    attr,align,rs,cs,blocks=cell
    return Con("Cell",[attr_v(attr),AtomV(align["t"]),Con("RowSpan",[NumV(rs)]),Con("ColSpan",[NumV(cs)]),ListV([block_v(b) for b in blocks])])
def row_v(row):
    return Con("Row",[attr_v(row[0]),ListV([cell_v(c) for c in row[1]])])

def block_v(b):
    t=b.get("t"); c=b.get("c")
    if t in ("Plain","Para"): return Con(t,[ListV([inline_v(i) for i in c])])
    if t=="LineBlock": return Con("LineBlock",[ListV([ListV([inline_v(i) for i in line]) for line in c])])
    if t=="CodeBlock": return Con("CodeBlock",[attr_v(c[0]),StrV(c[1])])
    if t=="RawBlock": return Con("RawBlock",[Con("Format",[StrV(c[0]["c"])]),StrV(c[1])])
    if t=="BlockQuote": return Con("BlockQuote",[ListV([block_v(x) for x in c])])
    if t=="OrderedList":
        lattr=c[0]; items=c[1]
        return Con("OrderedList",[TupleV([NumV(lattr[0]),AtomV(lattr[1]["t"]),AtomV(lattr[2]["t"])]),ListV([ListV([block_v(x) for x in item]) for item in items])])
    if t=="BulletList": return Con("BulletList",[ListV([ListV([block_v(x) for x in item]) for item in c])])
    if t=="DefinitionList":
        items=[]
        for term,defs in c:
            items.append(TupleV([ListV([inline_v(i) for i in term]),ListV([ListV([block_v(x) for x in d]) for d in defs])]))
        return Con("DefinitionList",[ListV(items)])
    if t=="Header": return Con("Header",[NumV(c[0]),attr_v(c[1]),ListV([inline_v(i) for i in c[2]])])
    if t=="HorizontalRule": return AtomV("HorizontalRule")
    if t=="Table":
        attr,caption,specs,head,bodies,foot=c
        spec_vs=[]
        for align,cw in specs:
            if cw["t"]=="ColWidthDefault": cwv=AtomV("ColWidthDefault")
            else: cwv=Con("ColWidth",[NumV(float(cw["c"]))])
            spec_vs.append(TupleV([AtomV(align["t"]),cwv]))
        head_v=Con("TableHead",[attr_v(head[0]),ListV([row_v(r) for r in head[1]])])
        body_vs=[]
        for battr,rhc,inter,rows in bodies:
            body_vs.append(Con("TableBody",[attr_v(battr),Con("RowHeadColumns",[NumV(rhc)]),ListV([row_v(r) for r in inter]),ListV([row_v(r) for r in rows])]))
        foot_v=Con("TableFoot",[attr_v(foot[0]),ListV([row_v(r) for r in foot[1]])])
        return Con("Table",[attr_v(attr),caption_v(caption),ListV(spec_vs),head_v,ListV(body_vs),foot_v])
    if t=="Figure":
        return Con("Figure",[attr_v(c[0]),caption_v(c[1]),ListV([block_v(x) for x in c[2]])])
    if t=="Div":
        return Con("Div",[attr_v(c[0]),ListV([block_v(x) for x in c[1]])])
    return AtomV(t)

def meta_v(mv):
    t=mv.get("t"); c=mv.get("c")
    if t=="MetaMap": return Con("MetaMap",[AppV("fromList",[ListV([TupleV([StrV(k),meta_v(c[k])]) for k in sorted(c.keys())])])]) if False else None
    # Haskell Show of MetaMap: MetaMap (fromList [(...)])? MetaMap field is a Map, show Map displays "fromList [...]" . Our Rec Meta unMeta is Map with fromList. For nested MetaMap value, Show likely "MetaMap (fromList [...])" and as argument to MetaMap constructor would need parens around application. Our app arg renderer parenthesizes AppV.
    if t=="MetaList": return Con("MetaList",[ListV([meta_v(x) for x in c])])
    if t=="MetaBool": return Con("MetaBool",[AtomV("True" if c else "False")])
    if t=="MetaString": return Con("MetaString",[StrV(c)])
    if t=="MetaInlines": return Con("MetaInlines",[ListV([inline_v(i) for i in c])])
    if t=="MetaBlocks": return Con("MetaBlocks",[ListV([block_v(b) for b in c])])
    return AtomV(t)

def write_native(doc,opts=None,exts=None,standalone=False):
    columns=opts.columns if opts else 72
    blocks_v=ListV([block_v(b) for b in doc.get("blocks",[])])
    if standalone:
        meta=doc.get("meta",{})
        pairs=[]
        for k in sorted(meta.keys()):
            mv=meta[k]
            if mv.get("t")=="MetaMap":
                # special build because meta_v returns None placeholder above; construct now
                mmv=Con("MetaMap",[AppV("fromList",[ListV([TupleV([StrV(kk),meta_v_fixed(vv)]) for kk,vv in sorted(mv["c"].items())])])])
                pairs.append(TupleV([StrV(k),mmv]))
            else:
                pairs.append(TupleV([StrV(k),meta_v_fixed(mv)]))
        meta_map=AppV("fromList",[ListV(pairs)])
        meta_rec=Rec("Meta",[("unMeta",meta_map)])
        whole=Con("Pandoc",[meta_rec,blocks_v])
        lines=render_value(whole,start_col=0,line_indent=0,columns=columns)
    else:
        lines=render_value(blocks_v,start_col=0,line_indent=0,columns=columns)
    return "\n".join(lines)+"\n"

def meta_v_fixed(mv):
    if mv.get("t")=="MetaMap":
        return Con("MetaMap",[AppV("fromList",[ListV([TupleV([StrV(k),meta_v_fixed(v)]) for k,v in sorted(mv["c"].items())])])])
    return meta_v(mv)

