import json, re, math
from ..ast import stringify

# JSON
def json_escape_str(s):
    return json.dumps(s,ensure_ascii=False)
def dump_json_value(v,in_meta_map=False):
    if v is None: return "null"
    if v is True: return "true"
    if v is False: return "false"
    if isinstance(v,(int,float)) and not isinstance(v,bool):
        # JSON numbers: Haskell aeson for Double in ColWidth etc. Python json gives repr; floats expected maybe 0.0555.. In JSON output earlier colwidth not in JSON (ColWidth has c float) probe later. Use json.dumps float.
        return json.dumps(v)
    if isinstance(v,str): return json_escape_str(v)
    if isinstance(v,list): return "["+",".join(dump_json_value(x) for x in v)+"]"
    if isinstance(v,dict):
        if "t" in v:
            # MetaMap c is dict sorted in nested
            if v.get("t")=="MetaMap" and isinstance(v.get("c"),dict):
                c="{"+",".join(json_escape_str(k)+":"+dump_json_value(v["c"][k]) for k in sorted(v["c"].keys()))+"}"
                return "{\"t\":\"MetaMap\",\"c\":"+c+"}"
            if "c" in v:
                return "{\"t\":"+json_escape_str(v["t"])+",\"c\":"+dump_json_value(v["c"])+"}"
            else:
                return "{\"t\":"+json_escape_str(v["t"])+"}"
        else:
            keys=sorted(v.keys()) if in_meta_map else list(v.keys())
            return "{"+",".join(json_escape_str(k)+":"+dump_json_value(v[k]) for k in keys)+"}"
    return json.dumps(v)

def write_json(doc, opts=None, exts=None, standalone=False):
    meta=doc.get("meta",{})
    meta_str="{"+",".join(json_escape_str(k)+":"+dump_json_value(meta[k]) for k in sorted(meta.keys()))+"}"
    s='{"pandoc-api-version":[1,23,1,2],"meta":'+meta_str+',"blocks":'+dump_json_value(doc.get("blocks",[]))+'}'
    if not standalone:
        s+="\n"
    return s

# Haskell values
class V:
    pass
class Con(V):
    def __init__(self,name,args=None): self.name=name; self.args=args or []
class Rec(V):
    def __init__(self,name,fields): self.name=name; self.fields=fields # list (fieldname, V)
class ListV(V):
    def __init__(self,items): self.items=items
class TupleV(V):
    def __init__(self,items): self.items=items
class StrV(V):
    def __init__(self,s): self.s=s
class AtomV(V):
    def __init__(self,s): self.s=s
class NumV(V):
    def __init__(self,n): self.n=n
class AppV(V):
    def __init__(self,name,args): self.name=name; self.args=args

def haskell_string(s):
    out='"'
    for idx,ch in enumerate(s):
        o=ord(ch)
        if ch=='"': out+='\\"'
        elif ch=='\\': out+='\\\\'
        elif ch=='\n': out+='\\n'
        elif ch=='\t': out+='\\t'
        elif ch=='\r': out+='\\r'
        elif ch=='\a': out+='\\a'
        elif ch=='\b': out+='\\b'
        elif ch=='\f': out+='\\f'
        elif ch=='\v': out+='\\v'
        elif o<32 or o==127:
            # Haskell ASCII mnemonics for some: \NUL etc maybe decimal. Use decimal escape and terminator if next digit
            out+=f'\\{o}'
            if idx+1<len(s) and s[idx+1].isdigit(): out+='\\&'
        elif o>126:
            out+=f'\\{o}'
            if idx+1<len(s) and s[idx+1].isdigit(): out+='\\&'
        else:
            out+=ch
    out+='"'
    return out

def haskell_double(x):
    if x==0:
        return "0.0"
    # Use Python repr shortest then format in Haskell generic style
    # Get decimal mantissa/exponent using repr in scientific format with 15? repr gives shortest digits (like Haskell Grisu)
    s=repr(float(x)).lower()
    # Convert to digits and decimal exponent (value = 0.digits *10^exp or d.ddd*10^exp)
    # Use Python's decimal normalized from repr via format 'e'
    mant_s,exp_s=format(float(x),'.15e').split('e')
    # But shortest repr might have fewer digits; parse repr better
    from decimal import Decimal
    d=Decimal(s)
    tup=d.as_tuple(); digits=''.join(str(dig) for dig in tup.digits); exp=tup.exponent # value = digits *10^exp, first digit before decimal if normalized?
    sign='-' if tup.sign else ''
    # decimal exponent for scientific d.ddd eE : E = exp + len(digits)-1
    E=exp+len(digits)-1
    # Haskell FFGeneric: use fixed if 0 <= E <=? Actually formatRealFloat FFGeneric chooses exponent format if exponent <0 or >? Observed 0.0555 E=-2 -- scientific, 0.5 maybe fixed 0.5 (E-1). GHC showFloat: if e <0 or e>7 (?) where e is exponent from floatToDigits (value=.digits*10^e). For 0.0555 floatToDigits e=-1? Let's derive from Haskell docs memory: showGFloat uses FFGeneric: "The argument to FFGeneric determines fixed vs exponent based on exponent: fixed if 0<=exp<=7" Where exp is as in floatToDigits (digits before decimal count). For 0.0555 digits=555..., exp=-1 (0.0555=.555*10^-1), so exponent format. For 0.5 exp=0 fixed0.5. For 5.0 exp1 fixed5.0.
    e_float=E+1  # 0.digits *10^e
    if 0 <= e_float <=7:
        # fixed
        if e_float<=0:
            return sign+"0."+("0"*(-e_float))+digits
        if len(digits)<=e_float:
            return sign+digits+("0"*(e_float-len(digits)))+".0"
        return sign+digits[:e_float]+"."+digits[e_float:]
    else:
        # scientific format d.ddd eE, if single digit digits then d.0eE (?) Haskell formatGFloat exponent: first digit, '.', rest or 0
        if len(digits)==1:
            mant=digits+".0"
        else:
            mant=digits[0]+"."+digits[1:]
        return f"{sign}{mant}e{E}"

def flat_value(v, arg_context=False):
    if isinstance(v,AtomV): return v.s
    if isinstance(v,StrV): return haskell_string(v.s)
    if isinstance(v,NumV):
        if isinstance(v.n,float): return haskell_double(v.n)
        return str(v.n)
    if isinstance(v,ListV):
        if not v.items: return "[]"
        return "[ " + " , ".join(flat_value(x) for x in v.items) + " ]"
    if isinstance(v,TupleV):
        return "( " + " , ".join(flat_value(x) for x in v.items) + " )"
    if isinstance(v,Rec):
        if not v.fields: return v.name+" {}"
        fields=" , ".join(f"{k} = {flat_value(val)}" for k,val in v.fields)
        return f"{v.name} {{ {fields} }}"
    if isinstance(v,(Con,AppV)):
        if not v.args: return v.name
        s=v.name+" "+" ".join(flat_value(a,True) if needs_parens(a) else flat_value(a) for a in v.args)
        if arg_context and needs_parens(v):
            # wrapper handled by parent but this arg_context path used in join above with needs_parens check; for safety
            return "("+s+")"
        return s
    return str(v)

def needs_parens(v):
    return isinstance(v,(Con,AppV)) and len(v.args)>0

def ribbon_width(columns):
    return max(10,int(round(columns/1.2))) if columns else 60

def fits(flat_len,start_col,line_indent,columns):
    if columns is None: return True
    w=min(columns-start_col, ribbon_width(columns)-start_col+line_indent)
    return flat_len <= w

def render_value(v,start_col=0,line_indent=0,columns=72, arg_context=False):
    """Return list of lines (strings) where first line has NO leading indent (assumed current cursor at start_col), subsequent lines include full leading spaces."""
    flat=flat_value(v)
    # parentheses wrapping if needed in arg context: render as a Tuple-like paren group whose content is a Con/App.
    if arg_context and needs_parens(v):
        return render_paren(v,start_col,line_indent,columns)
    if isinstance(v,(AtomV,StrV,NumV)):
        return [flat]
    if isinstance(v,ListV):
        return render_listlike(v.items,'[',']',start_col,line_indent,columns)
    if isinstance(v,TupleV):
        return render_listlike(v.items,'(',')',start_col,line_indent,columns)
    if isinstance(v,Rec):
        return render_rec(v,start_col,line_indent,columns)
    if isinstance(v,(Con,AppV)):
        if not v.args: return [flat]
        if fits(len(flat),start_col,line_indent,columns):
            return [flat]
        # vertical: name first, each arg at indent start_col+2
        indent=start_col+2
        lines=[v.name]
        for a in v.args:
            alines=render_value(a,start_col=indent,line_indent=indent,columns=columns,arg_context=True)
            # first line needs indent prefix
            lines.append(" "*indent+alines[0])
            lines.extend(alines[1:])
        return lines
    return [flat]

def render_paren(v,start_col,line_indent,columns):
    flat="("+flat_value(v)+")"
    # If fits within available based paren start
    if fits(len(flat),start_col,line_indent,columns):
        return [flat]
    # Render content starting at start_col+1 (inside paren), then closing paren attached to last line
    inner_lines=render_value(v,start_col=start_col+1,line_indent=line_indent,columns=columns)
    # prefix first line with '(' (inner first line is bare), and closing ) at end last line
    inner_lines[0]="("+inner_lines[0]
    inner_lines[-1]=inner_lines[-1]+")"
    return inner_lines

def render_listlike(items,open_ch,close_ch,start_col,line_indent,columns):
    if not items:
        return [open_ch+close_ch]
    flat=flat_value(ListV(items) if open_ch=='[' else TupleV(items))
    if fits(len(flat),start_col,line_indent,columns):
        return [flat]
    lines=[]
    for idx,item in enumerate(items):
        prefix=(open_ch+" ") if idx==0 else ", "
        ilines=render_value(item,start_col=start_col+2,line_indent=start_col,columns=columns)
        # first line: if it's first item, current line starts at start_col (caller gives no leading); prefix replaces 2 columns
        if idx==0:
            lines.append(prefix+ilines[0])
        else:
            lines.append(" "*start_col+prefix+ilines[0])
        lines.extend(ilines[1:])
    lines.append(" "*start_col+close_ch)
    return lines

def render_rec(v,start_col,line_indent,columns):
    flat=flat_value(v)
    if fits(len(flat),start_col,line_indent,columns):
        return [flat]
    # Treat as Con with brace fields as one arg-ish document.
    # First line = name. Brace block at indent start_col+2.
    brace_col=start_col+2
    # Build field items as values representing assignment strings? Render fields manually.
    # If brace block alone fits on its line at brace_col, could do name newline brace one line; our fields rendering decides.
    field_lines=render_fields(v.fields,brace_col,brace_col,columns)
    lines=[v.name]
    lines.append(" "*brace_col+field_lines[0])
    lines.extend(field_lines[1:])
    return lines

def render_fields(fields,brace_col,line_indent,columns):
    # fields list lines with prefixes "{ " / ", " and closing "}"
    # Flat brace part
    flat_brace="{ "+ " , ".join(f"{k} = {flat_value(val)}" for k,val in fields)+" }"
    if fits(len(flat_brace),brace_col,line_indent,columns):
        return [flat_brace]
    lines=[]
    for idx,(k,val) in enumerate(fields):
        prefix="{ " if idx==0 else ", "
        # Field start column after prefix at brace_col+2
        field_start=brace_col+2
        # Render field assignment as a small sep: label + " = " + value; if whole assignment fits in line based field_start, single line
        assign_flat=f"{k} = {flat_value(val)}"
        if fits(len(assign_flat),field_start,brace_col,columns):
            if idx==0: lines.append(prefix+assign_flat)
            else: lines.append(" "*brace_col+prefix+assign_flat)
            continue
        # break after "field ="
        head=f"{k} ="
        if idx==0: lines.append(prefix+head)
        else: lines.append(" "*brace_col+prefix+head)
        # Value at field_start+2? Meta unMeta: field starts after "{ " at brace_col(4)+2=6, value at 8. That's field_start+2.
        val_indent=field_start+2
        vlines=render_value(val,start_col=val_indent,line_indent=val_indent,columns=columns)
        lines.append(" "*val_indent+vlines[0]); lines.extend(vlines[1:])
    lines.append(" "*brace_col+"}")
    return lines

# Convert AST to Haskell values
def attr_v(attr):
    if attr is None: attr=["",[],[]]
    return TupleV([StrV(attr[0]),ListV([StrV(x) for x in attr[1]]),ListV([TupleV([StrV(k),StrV(v)]) for k,v in attr[2]])])
def target_v(t):
    return TupleV([StrV(t[0]),StrV(t[1])])
def inline_v(x):
    t=x.get("t"); c=x.get("c")
    if t=="Str": return Con("Str",[StrV(c)])
    if t in ("Space","SoftBreak","LineBreak"): return AtomV(t)
    if t in ("Emph","Strong","Underline","Strikeout","Superscript","Subscript","SmallCaps"): return Con(t,[ListV([inline_v(i) for i in c])])
    if t=="Quoted": return Con("Quoted",[AtomV(c[0]["t"]),ListV([inline_v(i) for i in c[1]])])
    if t=="Cite":
        cites=[]
        for cit in c[0]:
            fields=[
                ("citationId",StrV(cit.get("citationId",""))),
                ("citationPrefix",ListV([inline_v(i) for i in cit.get("citationPrefix",[])])),
                ("citationSuffix",ListV([inline_v(i) for i in cit.get("citationSuffix",[])])),
                ("citationMode",AtomV(cit.get("citationMode",{}).get("t","NormalCitation"))),
                ("citationNoteNum",NumV(cit.get("citationNoteNum",1))),
                ("citationHash",NumV(cit.get("citationHash",0))),
            ]
            cites.append(Rec("Citation",fields))
        return Con("Cite",[ListV(cites),ListV([inline_v(i) for i in c[1]])])
    if t=="Code": return Con("Code",[attr_v(c[0]),StrV(c[1])])
    if t=="Math": return Con("Math",[AtomV(c[0]["t"]),StrV(c[1])])
    if t=="RawInline": return Con("RawInline",[Con("Format",[StrV(c[0]["c"])]),StrV(c[1])])
    if t in ("Link","Image"): return Con(t,[attr_v(c[0]),ListV([inline_v(i) for i in c[1]]),target_v(c[2])])
    if t=="Note": return Con("Note",[ListV([block_v(b) for b in c])])
    if t=="Span": return Con("Span",[attr_v(c[0]),ListV([inline_v(i) for i in c[1]])])
    return AtomV(t)

def caption_v(cap):
    # cap = [short or None, blocks]
    if cap is None: cap=[None,[]]
    if cap[0] is None: short=AtomV("Nothing")
    else: short=Con("Just",[ListV([inline_v(i) for i in cap[0]])])
    return Con("Caption",[short,ListV([block_v(b) for b in cap[1]])])

def cell_v(cell):
    attr,align,rs,cs,blocks=cell
    return Con("Cell",[attr_v(attr),AtomV(align["t"]),Con("RowSpan",[NumV(rs)]),Con("ColSpan",[NumV(cs)]),ListV([block_v(b) for b in blocks])])
def row_v(row):
    return Con("Row",[attr_v(row[0]),ListV([cell_v(c) for c in row[1]])])

def block_v(b):
    t=b.get("t"); c=b.get("c")
    if t in ("Plain","Para"): return Con(t,[ListV([inline_v(i) for i in c])])
    if t=="LineBlock": return Con("LineBlock",[ListV([ListV([inline_v(i) for i in line]) for line in c])])
    if t=="CodeBlock": return Con("CodeBlock",[attr_v(c[0]),StrV(c[1])])
    if t=="RawBlock": return Con("RawBlock",[Con("Format",[StrV(c[0]["c"])]),StrV(c[1])])
    if t=="BlockQuote": return Con("BlockQuote",[ListV([block_v(x) for x in c])])
    if t=="OrderedList":
        lattr=c[0]; items=c[1]
        return Con("OrderedList",[TupleV([NumV(lattr[0]),AtomV(lattr[1]["t"]),AtomV(lattr[2]["t"])]),ListV([ListV([block_v(x) for x in item]) for item in items])])
    if t=="BulletList": return Con("BulletList",[ListV([ListV([block_v(x) for x in item]) for item in c])])
    if t=="DefinitionList":
        items=[]
        for term,defs in c:
            items.append(TupleV([ListV([inline_v(i) for i in term]),ListV([ListV([block_v(x) for x in d]) for d in defs])]))
        return Con("DefinitionList",[ListV(items)])
    if t=="Header": return Con("Header",[NumV(c[0]),attr_v(c[1]),ListV([inline_v(i) for i in c[2]])])
    if t=="HorizontalRule": return AtomV("HorizontalRule")
    if t=="Table":
        attr,caption,specs,head,bodies,foot=c
        spec_vs=[]
        for align,cw in specs:
            if cw["t"]=="ColWidthDefault": cwv=AtomV("ColWidthDefault")
            else: cwv=Con("ColWidth",[NumV(float(cw["c"]))])
