# XML writer
def xml_escape(s):
    return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")
def xml_escape_attr(s):
    return xml_escape(s).replace('"',"&quot;")
def attr_to_xml(attr):
    if not attr: return ""
    ident,classes,kvs=attr
    parts=[]
    if ident: parts.append(f'id="{xml_escape_attr(ident)}"')
    if classes: parts.append(f'class="{xml_escape_attr(" ".join(classes))}"')
    for k,v in kvs: parts.append(f'{k}="{xml_escape_attr(v)}"')
    return (" "+" ".join(parts)) if parts else ""

def inlines_to_xml(inlines):
    return "".join(inline_to_xml(x) for x in inlines)
def inline_to_xml(x):
    t=x.get("t"); c=x.get("c")
    if t=="Str": return xml_escape(c)
    if t=="Space": return " "
    if t in ("SoftBreak","LineBreak"): return f"<{t} />"
    if t in ("Emph","Underline","Strong","Strikeout","Superscript","Subscript","SmallCaps"): return f"<{t}>{inlines_to_xml(c)}</{t}>"
    if t=="Quoted": return f'<Quoted quote-type="{c[0]["t"]}">{inlines_to_xml(c[1])}</Quoted>'
    if t=="Code": return f'<Code{attr_to_xml(c[0])}>{xml_escape(c[1])}</Code>'
    if t=="Math": return f'<Math math-type="{c[0]["t"]}">{xml_escape(c[1])}</Math>'
    if t=="RawInline":
        fmt=c[0] if isinstance(c[0],str) else c[0].get("c","")
        return f'<RawInline format="{xml_escape_attr(fmt)}">{xml_escape(c[1])}</RawInline>'
    if t=="Link":
        title=f' title="{xml_escape_attr(c[2][1])}"' if c[2][1] else ""
        return f'<Link{attr_to_xml(c[0])} href="{xml_escape_attr(c[2][0])}"{title}>{inlines_to_xml(c[1])}</Link>'
    if t=="Image":
        title=f' title="{xml_escape_attr(c[2][1])}"' if c[2][1] else ""
        return f'<Image{attr_to_xml(c[0])} src="{xml_escape_attr(c[2][0])}"{title}>{inlines_to_xml(c[1])}</Image>'
    if t=="Span": return f'<Span{attr_to_xml(c[0])}>{inlines_to_xml(c[1])}</Span>'
    if t=="Note":
        inner="".join(block_to_xml(b) for b in c)
        return f'<Note>{inner}</Note>'
    if t=="Cite":
        cites=[]
        for cit in c[0]:
            prefix=f"<prefix>{inlines_to_xml(cit.get('citationPrefix',[]))}</prefix>" if cit.get("citationPrefix") else ""
            suffix=f"<suffix>{inlines_to_xml(cit.get('citationSuffix',[]))}</suffix>" if cit.get("citationSuffix") else ""
            # Order in output: Citation attrs id mode note-num hash, then prefix/suffix even if empty omitted? Example had prefix/suffix because present. Check plain citation likely empty self-closing? We'll output non-self with possibly empty child.
            cites.append(f'<Citation id="{xml_escape_attr(cit.get("citationId",""))}" mode="{cit.get("citationMode",{}).get("t","")}" note-num="{cit.get("citationNoteNum",1)}" hash="{cit.get("citationHash",0)}">{prefix}{suffix}</Citation>')
        inner="\n".join(cites)
        return f'<Cite><citations>\n{inner}\n</citations>{inlines_to_xml(c[1])}</Cite>'
    return ""

def blocks_to_xml(blocks):
    return "".join(block_to_xml(b) for b in blocks)
def block_to_xml(b):
    t=b.get("t"); c=b.get("c")
    if t in ("Plain","Para"):
        return f"<{t}>{inlines_to_xml(c)}</{t}>\n"
    if t=="Header":
        return f'<Header{attr_to_xml(c[1])} level="{c[0]}">{inlines_to_xml(c[2])}</Header>\n'
    if t=="LineBlock":
        lines="".join(f"<line>{inlines_to_xml(line)}</line>" for line in c)
        return f"<LineBlock>\n{lines}</LineBlock>\n"
    if t=="CodeBlock":
        return f'<CodeBlock{attr_to_xml(c[0])}>{xml_escape(c[1])}</CodeBlock>\n'
    if t=="RawBlock":
        fmt=c[0] if isinstance(c[0],str) else c[0].get("c","")
        return f'<RawBlock format="{xml_escape_attr(fmt)}">{xml_escape(c[1])}</RawBlock>'
    if t=="BlockQuote":
        return f"<BlockQuote>\n{blocks_to_xml(c)}</BlockQuote>\n"
    if t=="HorizontalRule":
        return "<HorizontalRule />\n"
    if t=="BulletList":
        items=""
        for item in c: items+=f"<item>\n{blocks_to_xml(item)}</item>\n"
        return f"<BulletList>\n{items}</BulletList>\n"
    if t=="OrderedList":
        lattr,itemslist=c
        items="".join(f"<item>\n{blocks_to_xml(item)}</item>\n" for item in itemslist)
        return f'<OrderedList start="{lattr[0]}" number-style="{lattr[1]["t"]}" number-delim="{lattr[2]["t"]}">\n{items}</OrderedList>\n'
    if t=="DefinitionList":
        # Mimic peculiar formatting
        out="<DefinitionList>\n"
        for term,defs in c:
            out+=f"<item><term>{inlines_to_xml(term)}</term>\n"
            for d in defs:
                out+=f"<def>\n{blocks_to_xml(d)}</def>\n"
            out+="</item>"
        out+="</DefinitionList>\n"
        return out
    if t=="Div":
        return f'<Div{attr_to_xml(c[0])}>\n{blocks_to_xml(c[1])}</Div>\n'
    if t=="Figure":
        cap=caption_to_xml(c[1])
        return f'<Figure{attr_to_xml(c[0])}>\n{cap}{blocks_to_xml(c[2])}</Figure>\n'
    if t=="Table":
        return table_to_xml(b)
    return ""

def caption_to_xml(cap):
    if not cap or (cap[0] is None and not cap[1]):
        return "<Caption />\n"
    out="<Caption>\n"
    if cap[0] is not None:
        out+=f"<ShortCaption>{inlines_to_xml(cap[0])}</ShortCaption>\n"
    out+=blocks_to_xml(cap[1])
    out+="</Caption>\n"
    return out

def row_to_xml(row):
    attr,cells=row
    out=f"<Row{attr_to_xml(attr)}>\n"
    for cell in cells:
        cattr,align,rs,cs,blocks=cell
        extra=""
        if cs!=1: extra+=f' col-span="{cs}"'
        if rs!=1: extra+=f' row-span="{rs}"'
        extra+=f' alignment="{align["t"]}"'
        out+=f"<Cell{attr_to_xml(cattr)}{extra}>\n{blocks_to_xml(blocks)}</Cell>\n"
    out+="</Row>\n"
    return out

def table_to_xml(b):
    c=b["c"]; attr,caption,specs,head,bodies,foot=c
    out=f"<Table{attr_to_xml(attr)}>\n"
    out+=caption_to_xml(caption)
    out+="<colspecs>\n"
    for align,cw in specs:
        width="0" if cw["t"]=="ColWidthDefault" else haskell_double(float(cw["c"]))
        out+=f'<ColSpec alignment="{align["t"]}" col-width="{width}" />\n'
    out+="</colspecs>\n"
    if not head[1] and head[0]==["",[],[]]:
        out+="<TableHead />\n"
    else:
        out+=f"<TableHead{attr_to_xml(head[0])}>\n"+"".join(row_to_xml(r) for r in head[1])+"</TableHead>\n"
    for battr,rhc,inter,rows in bodies:
        out+=f'<TableBody{attr_to_xml(battr)} row-head-columns="{rhc}">\n'
        if not inter and True:
            out+="<header />\n"
        else:
            out+="<header>\n"+"".join(row_to_xml(r) for r in inter)+"</header>\n"
        out+="<body>\n"+"".join(row_to_xml(r) for r in rows)+"</body>\n</TableBody>\n"
    if not foot[1] and foot[0]==["",[],[]]:
        out+="<TableFoot />\n"
    else:
        out+=f"<TableFoot{attr_to_xml(foot[0])}>\n"+"".join(row_to_xml(r) for r in foot[1])+"</TableFoot>\n"
    out+="</Table>\n"
    return out

def metavalue_to_xml(mv):
    t=mv.get("t"); c=mv.get("c")
    if t=="MetaBool":
        return f'<MetaBool value="{"true" if c else "false"}" />\n'
    if t=="MetaString":
        return f"<MetaString>{xml_escape(c)}</MetaString>\n"
    if t=="MetaInlines":
        return f"<MetaInlines>{inlines_to_xml(c)}</MetaInlines>\n"
    if t=="MetaBlocks":
        return f"<MetaBlocks>\n{blocks_to_xml(c)}</MetaBlocks>\n"
    if t=="MetaList":
        inner="".join(metavalue_to_xml(x) for x in c)
        return f"<MetaList>\n{inner}</MetaList>\n"
    if t=="MetaMap":
        inner="".join(f'<entry key="{xml_escape_attr(k)}">\n{metavalue_to_xml(c[k])}</entry>\n' for k in sorted(c.keys()))
        return f"<MetaMap>\n{inner}</MetaMap>\n"
    return ""

def write_xml(doc,opts=None,exts=None,standalone=False):
    meta=doc.get("meta",{})
    if not meta:
        meta_s="<meta />\n"
    else:
        meta_s="<meta>\n"+"".join(f'<entry key="{xml_escape_attr(k)}">\n{metavalue_to_xml(meta[k])}</entry>\n' for k in sorted(meta.keys()))+"</meta>\n"
    blocks=doc.get("blocks",[])
    if blocks:
        blocks_s="<blocks>\n"+blocks_to_xml(blocks)+"</blocks>\n"
    else:
        blocks_s="<blocks />\n"
    s="<?xml version='1.0' ?>\n<Pandoc api-version=\"1,23,1,2\">\n"+meta_s+blocks_s+"</Pandoc>"
    if not standalone:
        s+="\n"
    return s
