# XML writer
def xml_escape(s):
    return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")
def xml_escape_attr(s):
    return xml_escape(s).replace('"',"&quot;")
def attr_to_xml(attr):
    if not attr: return ""
    ident,classes,kvs=attr
    parts=[]
    if ident: parts.append(f'id="{xml_escape_attr(ident)}"')
    if classes: parts.append(f'class="{xml_escape_attr(" ".join(classes))}"')
    for k,v in kvs: parts.append(f'{k}="{xml_escape_attr(v)}"')
    return (" "+" ".join(parts)) if parts else ""

def inlines_to_xml(inlines):
    return "".join(inline_to_xml(x) for x in inlines)
def inline_to_xml(x):
    t=x.get("t"); c=x.get("c")
    if t=="Str": return xml_escape(c)
    if t=="Space": return " "
    if t in ("SoftBreak","LineBreak"): return f"<{t} />"
    if t in ("Emph","Underline","Strong","Strikeout","Superscript","Subscript","SmallCaps"): return f"<{t}>{inlines_to_xml(c)}</{t}>"
    if t=="Quoted": return f'<Quoted quote-type="{c[0]["t"]}">{inlines_to_xml(c[1])}</Quoted>'
    if t=="Code": return f'<Code{attr_to_xml(c[0])}>{xml_escape(c[1])}</Code>'
    if t=="Math": return f'<Math math-type="{c[0]["t"]}">{xml_escape(c[1])}</Math>'
    if t=="RawInline":
        fmt=c[0] if isinstance(c[0],str) else c[0].get("c","")
        return f'<RawInline format="{xml_escape_attr(fmt)}">{xml_escape(c[1])}</RawInline>'
    if t=="Link":
        title=f' title="{xml_escape_attr(c[2][1])}"' if c[2][1] else ""
        return f'<Link{attr_to_xml(c[0])} href="{xml_escape_attr(c[2][0])}"{title}>{inlines_to_xml(c[1])}</Link>'
    if t=="Image":
        title=f' title="{xml_escape_attr(c[2][1])}"' if c[2][1] else ""
        return f'<Image{attr_to_xml(c[0])} src="{xml_escape_attr(c[2][0])}"{title}>{inlines_to_xml(c[1])}</Image>'
    if t=="Span": return f'<Span{attr_to_xml(c[0])}>{inlines_to_xml(c[1])}</Span>'
    if t=="Note":
        inner="".join(block_to_xml(b) for b in c)
        return f'<Note>{inner}</Note>'
    if t=="Cite":
        cites=[]
        for cit in c[0]:
            prefix=f"<prefix>{inlines_to_xml(cit.get('citationPrefix',[]))}</prefix>" if cit.get("citationPrefix") else ""
            suffix=f"<suffix>{inlines_to_xml(cit.get('citationSuffix',[]))}</suffix>" if cit.get("citationSuffix") else ""
            # Order in output: Citation attrs id mode note-num hash, then prefix/suffix even if empty omitted? Example had prefix/suffix because present. Check plain citation likely empty self-closing? We'll output non-self with possibly empty child.
            cites.append(f'<Citation id="{xml_escape_attr(cit.get("citationId",""))}" mode="{cit.get("citationMode",{}).get("t","")}" note-num="{cit.get("citationNoteNum",1)}" hash="{cit.get("citationHash",0)}">{prefix}{suffix}</Citation>')
        inner="\n".join(cites)
        return f'<Cite><citations>\n{inner}\n</citations>{inlines_to_xml(c[1])}</Cite>'
    return ""

def blocks_to_xml(blocks):
    return "".join(block_to_xml(b) for b in blocks)
def block_to_xml(b):
    t=b.get("t"); c=b.get("c")
    if t in ("Plain","Para"):
        return f"<{t}>{inlines_to_xml(c)}</{t}>\n"
    if t=="Header":
        return f'<Header{attr_to_xml(c[1])} level="{c[0]}">{inlines_to_xml(c[2])}</Header>\n'
    if t=="LineBlock":
        lines="".join(f"<line>{inlines_to_xml(line)}</line>" for line in c)
