GREEK={'alpha':'α','beta':'β','gamma':'γ','delta':'δ','epsilon':'ε','zeta':'ζ','eta':'η','theta':'θ','iota':'ι','kappa':'κ','lambda':'λ','mu':'μ','nu':'ν','xi':'ξ','pi':'π','rho':'ρ','sigma':'σ','tau':'τ','upsilon':'υ','phi':'φ','chi':'χ','psi':'ψ','omega':'ω','Gamma':'Γ','Delta':'Δ','Theta':'Θ','Lambda':'Λ','Xi':'Ξ','Pi':'Π','Sigma':'Σ','Phi':'Φ','Psi':'Ψ','Omega':'Ω','infty':'∞','times':'×','cdot':'⋅','pm':'±','leq':'≤','geq':'≥','neq':'≠','sum':'∑','prod':'∏','int':'∫','sqrt':'√'}

def tex_to_html_inlines(tex,writer):
    # Parse very simple TeX: letters become <em>letter</em> concatenated if variable, numbers plain, ^/_ super/sub, \frac{a}{b} as ... texmath renders fractions complex spans. For simple $x$, $x^2$, etc this matches.
    # Texmath HTML plain rendering: identifiers are italicized each (?) <em>x</em>; multi-letter function names (?) sin as roman.
    docs=[]
    i=0
    funcs={"sin","cos","tan","log","ln","exp","lim","min","max","sup","inf","det","dim","ker"}
    while i<len(tex):
        c=tex[i]
        if c.isspace():
            # spaces in math ignored except between symbols maybe renders space node in texmath? $a + b$ output <em>a</em> + <em>b</em> with spaces around +. Our loop will add a breakable space if previous not space?
            # Add BS to preserve token spacing in rendered HTML.
            docs.append(BS()); i+=1; continue
        if c=='\\':
            m=re.match(r'\\([A-Za-z]+)',tex[i:])
            if m:
                name=m.group(1); i+=len(m.group(0))
                if name in ("frac","dfrac","tfrac"):
                    # parse two groups
                    args=[]
                    for _ in range(2):
                        arg,i=parse_tex_group(tex,i)
                        args.append(arg)
                    # texmath HTML for fractions uses a complex span structure; approximate as (a)/(b) may mismatch. Leave a fraction representation:
                    docs.append(Text('<span class="frac"><sup>')); docs.append(tex_to_html_inlines(args[0],writer)); docs.append(Text('</sup>⁄<sub>')); docs.append(tex_to_html_inlines(args[1],writer)); docs.append(Text('</sub></span>'))
                    continue
                if name in GREEK:
                    docs.append(Text(writer.esc(GREEK[name]))); continue
                if name in funcs:
                    docs.append(Text(name)); continue
                if name in ("mathbf","mathrm","mathit","mathbb","mathcal","text"):
                    arg,i=parse_tex_group(tex,i); docs.append(tex_to_html_inlines(arg,writer)); continue
                # unknown command -> render name italic letters?
                docs.append(Text(f"<em>{writer.esc(name)}</em>")); continue
            else:
                # escaped symbol \{ etc
                if i+1<len(tex): docs.append(Text(writer.esc(tex[i+1]))); i+=2; continue
                i+=1; continue
        if c in '^_':
            tag="sup" if c=='^' else "sub"
            i+=1
            arg,i=parse_tex_arg(tex,i)
            docs.append(Text(f"<{tag}>")); docs.append(tex_to_html_inlines(arg,writer)); docs.append(Text(f"</{tag}>")); continue
        if c=='{':
            arg,i=parse_tex_group_at(tex,i); docs.append(tex_to_html_inlines(arg,writer)); continue
        if c.isalpha():
            docs.append(Text(f"<em>{writer.esc(c)}</em>")); i+=1; continue
        # numbers/punct
        docs.append(Text(writer.esc(c))); i+=1
    return Cat(docs)

def parse_tex_group(tex,i):
    while i<len(tex) and tex[i].isspace(): i+=1
    if i<len(tex) and tex[i]=='{': return parse_tex_group_at(tex,i)
    if i<len(tex): return tex[i],i+1
    return "",i
def parse_tex_group_at(tex,i):
    assert tex[i]=='{'; depth=1; j=i+1
    while j<len(tex) and depth:
        if tex[j]=='\\': j+=2; continue
        if tex[j]=='{': depth+=1
        elif tex[j]=='}': depth-=1
        j+=1
    return tex[i+1:j-1],j
def parse_tex_arg(tex,i):
    while i<len(tex) and tex[i].isspace(): i+=1
    if i<len(tex) and tex[i]=='{': return parse_tex_group_at(tex,i)
    if i<len(tex) and tex[i]=='\\':
        m=re.match(r'\\[A-Za-z]+|\\.',tex[i:]); return m.group(0),i+len(m.group(0))
