    return "",i

def tex_to_mathml(tex,disp):
    # Very simple MathML for simple cases: sequences of identifiers/numbers/operators scripts
    # Existing pandoc conversions for $x$ => <math><semantics><mi>x</mi><annotation>x</annotation></semantics></math>
