def tex_expr_mathml(tex):
    out=[]; i=0
    while i<len(tex):
        c=tex[i]
        if c.isspace(): i+=1; continue
        if c in '^_':
            tag="msup" if c=='^' else "msub"; i+=1; arg,i2=parse_tex_arg(tex,i); i=i2
            prev=out.pop() if out else "<mi></mi>"
            out.append(f"<{tag}>{prev}{tex_expr_mathml(arg)}</{tag}>"); continue
        if c=='\\':
            m=re.match(r'\\([A-Za-z]+)',tex[i:])
            if m:
                name=m.group(1); i+=len(m.group(0))
                if name in GREEK: out.append(f"<mi>{html.escape(GREEK[name])}</mi>")
                elif name in ("frac","dfrac"):
                    a,i=parse_tex_group(tex,i); b,i=parse_tex_group(tex,i); out.append(f"<mfrac>{tex_expr_mathml(a)}{tex_expr_mathml(b)}</mfrac>")
                else: out.append(f"<mo>{html.escape(name)}</mo>")
                continue
            i+=2; continue
        if c=='{': arg,i=parse_tex_group_at(tex,i); out.append(tex_expr_mathml(arg)); continue
        if c.isalpha(): out.append(f"<mi>{html.escape(c)}</mi>"); i+=1; continue
        if c.isdigit() or c=='.':
            j=i
            while j<len(tex) and (tex[j].isdigit() or tex[j]=='.'): j+=1
            out.append(f"<mn>{tex[i:j]}</mn>"); i=j; continue
        out.append(f"<mo>{html.escape(c)}</mo>"); i+=1
    return "".join(out)

