    def math_head_snippet(self):
        if not self.opts: return ""
        method,url=self.opts.html_math_method
        if method=="mathjax":
            src=url or "https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-chtml-full.js"
            return f'<script defer=""\n  src="{src}"\n  type="text/javascript"></script>'
        if method=="katex":
            base=url or "https://cdn.jsdelivr.net/npm/katex@latest/dist/"
            if not base.endswith('/'): base+='/'
            # Exact snippet from pandoc (styles) - get from probing later in template context; template inserts $math$ indented by two spaces by template line prefix.
            # Body snippet value starts without leading spaces per line? Template line is "  $math$" alone and nesting indents subsequent lines by 2.
            s=f'<script defer=""\nsrc="{base}katex.min.js"></script>\n'
            s+='<script>document.addEventListener("DOMContentLoaded", function () {\n var mathElements = document.getElementsByClassName("math");\n for (var i = 0; i < mathElements.length; i++) {\n  var texText = mathElements[i].firstChild;\n  if (mathElements[i].tagName == "SPAN") {\n   katex.render(texText.data, mathElements[i], {\n    displayMode: mathElements[i].classList.contains(\'display\'),\n    throwOnError: false,\n    fleqn: false\n   });\n}}});\n</script>\n'
            s+=f'<link rel="stylesheet"\nhref="{base}katex.min.css" />'
            return s
        return ""
    def toc_html(self,doc):
        # Build TOC list HTML string (without trailing newline?). Pandoc TOC in HTML template: <ul> nested with links to headers up to depth
        # We build using heading list in order.
        from .shared import build_toc_tree
        toc_items=build_toc_tree(doc.get("blocks",[]), self.opts.toc_depth if self.opts else 3)
        # Render via helper below
        return render_toc_list(toc_items,self,root=True)
    # Blocks
    def blocks_to_doc(self,blocks):
        docs=[]
        for b in blocks:
            docs.append(self.block_to_doc(b))
        if not docs: return Empty()
        out=docs[0]
        for d in docs[1:]:
            out=Cat([out,Cr(),d])
        return out
    def block_to_doc(self,b):
        t=b.get("t"); c=b.get("c")
        if t=="Plain":
            return self.inlines_to_doc(c)
        if t=="Para":
            if not c and not self.ext("empty_paragraphs",False):
                return Text("<p></p>") if False else Empty()
            return self.tag_doc("p",[],self.inlines_to_doc(c))
        if t=="LineBlock":
            if self.ext("line_blocks",True):
                inner=[]
                for line in c:
                    if line:
                        ld=self.inlines_to_doc(line)
                    elif self.html5:
                        ld=Text("<br />")
                    else:
                        ld=Text("<br />")
                    inner.append(Cat([Text('<div class="line">'),ld,Text('</div>')]))
                body=inner[0] if inner else Empty()
                for d in inner[1:]: body=Cat([body,Cr(),d])
                return Cat([Text('<div class="line-block">'),Cr(),body,Cr(),Text('</div>')])
            else:
                # as para with line breaks
                lines=[]
                for idx,line in enumerate(c):
                    if idx>0: lines.append(Text("<br />")); lines.append(Cr())
                    lines.append(self.inlines_to_doc(line))
                return self.tag_doc("p",[],Cat(lines))
        if t=="CodeBlock":
            return self.codeblock_doc(c[0],c[1])
        if t=="RawBlock":
            fmt=c[0] if isinstance(c[0],str) else c[0].get("c","")
            if fmt in ("html","html5","html4"):
                return Nowrap(Literal(c[1]))
            return Empty()
        if t=="BlockQuote":
            inner=self.blocks_to_doc(c)
            return Cat([Text("<blockquote>"),Cr(),inner,Cr(),Text("</blockquote>")])
        if t=="BulletList":
            return self.bullet_list_doc(c)
        if t=="OrderedList":
            return self.ordered_list_doc(c)
        if t=="DefinitionList":
            return self.definition_list_doc(c)
        if t=="Header":
            return self.header_doc(b)
        if t=="HorizontalRule":
            return Text("<hr />")
        if t=="Table":
            return self.table_doc(b)
        if t=="Figure":
            return self.figure_doc(b)
        if t=="Div":
            return self.div_doc(b)
        return Empty()
    def list_item_doc(self,item_blocks,task=None):
        # Task is transformed item text first block content inlines if task
        if task is not None:
            checked,content_blocks=task
            inner=self.blocks_to_doc(content_blocks)
            check='<input type="checkbox" checked="" />' if checked else '<input type="checkbox" />'
            return Cat([Text("<li><label>"),Text(check),inner,Text("</label></li>")])
        if not item_blocks:
            return Text("<li></li>")
        # If single Plain/Para (?) Pandoc: <li>plain inline</li> for Plain, Para goes as [<li><p>...] maybe newline formatting
        if len(item_blocks)==1:
            return Cat([Text("<li>"),self.block_to_doc(item_blocks[0]),Text("</li>")])
        # Multi blocks: <li>firstblock\n rest ...</li> formatting: blocks_to_doc joins with Cr; if first is Plain/Para, no extra newline after li.
        inner=self.blocks_to_doc(item_blocks)
        # If last block is list etc closed, pandoc puts </li> after a newline for some nested structures. Keep as same line after inner last line.
        return Cat([Text("<li>"),inner,Text("</li>")])
    def bullet_list_doc(self,items):
        # Task list detect
        task_items=[]; all_task=True
        for item in items:
            info=task_item_info(item)
            if info is None: all_task=False; break
            task_items.append(info)
        lis=[]
        if items and all_task:
            for checked,blocks in task_items:
                lis.append(self.list_item_doc(blocks,task=(checked,blocks)))
            body=lis[0]
            for d in lis[1:]: body=Cat([body,Cr(),d])
            return Cat([Text('<ul class="task-list">'),Cr(),body,Cr(),Text("</ul>")])
        for item in items: lis.append(self.list_item_doc(item))
        if not lis: return Text("<ul>\n</ul>")
        body=lis[0]
        for d in lis[1:]: body=Cat([body,Cr(),d])
        return Cat([Text("<ul>"),Cr(),body,Cr(),Text("</ul>")])
    def ordered_list_doc(self,c):
        lattr,items=c
        start,style,delim=lattr[0],lattr[1]["t"],lattr[2]["t"]
        type_map={"Decimal":"1","LowerAlpha":"a","UpperAlpha":"A","LowerRoman":"i","UpperRoman":"I","DefaultStyle":"1","Example":"1"}
        attrs=[]
        # Attributes order in pandoc: type, start, class? Example list has class="example" and type maybe.
        if style=="Example":
            attrs.append('class="example"')
        attrs.append(f'type="{type_map.get(style,"1")}"')
        if start!=1:
            attrs.append(f'start="{start}"')
        # Example lists need counter? HTML writer adds data (?) probe later
        lis=[self.list_item_doc(item) for item in items]
        if not lis: return Text(f"<ol {' '.join(attrs)}>\n</ol>")
        body=lis[0]
        for d in lis[1:]: body=Cat([body,Cr(),d])
        open_doc=self.open_tag_doc("ol",attrs)
        return Cat([open_doc,Cr(),body,Cr(),Text("</ol>")])
    def definition_list_doc(self,c):
        parts=[]
        for term,defs in c:
            parts.append(Cat([Text("<dt>"),self.inlines_to_doc(term),Text("</dt>")]))
            for d in defs:
                inner=self.blocks_to_doc(d)
                parts.append(Cat([Text("<dd>"),inner,Text("</dd>")]))
        if not parts: return Text("<dl>\n</dl>")
        body=parts[0]
        for p in parts[1:]: body=Cat([body,Cr(),p])
        return Cat([Text("<dl>"),Cr(),body,Cr(),Text("</dl>")])
    def header_doc(self,b):
        level,attr,inlines=b["c"]
        lvl=min(6,max(1,level))
        # Numbering
        number=None
        unnumbered=("unnumbered" in attr[1] or "unlisted" in attr[1])
        if self.opts and self.opts.number_sections and not self.slides and not (self.opts and self.opts.section_divs):
            number=self.next_header_number(level,unnumbered)
        elif getattr(b,"_number",None) is not None:
            number=b.get("_number")
        extra=[]
        if number:
            extra.append(f'data-number="{number}"')
        # Header attrs list order with data-number first in numbered example then (?) class/data/id.
        # Pandoc header code creates tag with attributes from attr in order class...? It then prepends data-number maybe.
        attrs=[]
        if extra: attrs.extend(extra)
        attrs.extend(self.attrs_list(attr,order="header"))
        inner=self.inlines_to_doc(inlines)
        if number:
            inner=Cat([Text(f'<span class="header-section-number">{number}</span>'),BS(),inner])
        return self.tag_doc(f"h{lvl}",attrs,inner)
    def next_header_number(self,level,unnumbered=False):
        if unnumbered: return None
        if self._number_counters is None: self._number_counters=[0]*6
        idx=level-1
        self._number_counters[idx]+=1
        for i in range(idx+1,6): self._number_counters[i]= (self.opts.number_offset[i] if self.opts and i < len(self.opts.number_offset) else 0)
        parts=self._number_counters[:level]
        # If a higher level is 0? Still include?
        return ".".join(str(x) for x in parts)
    def codeblock_doc(self,attr,code):
        ident,classes,kvs=attr if attr else ("",[],[])
        kvdict={k.lower():v for k,v in kvs}
        lang=classes[0] if classes else ""
        highlight = False
        style=self.opts.syntax_highlighting if self.opts else "default"
        if lang and style not in ("none","idiomatic") and tokenizer_available(lang):
            highlight=True
        if not highlight:
            if classes:
                # <pre class="..."><code> ; if attr id etc, pandoc may put attrs on pre? probe later
                class_attr=' class="'+self.esc_attr(" ".join(classes))+'"'
                id_attr=f' id="{self.esc_attr(ident)}"' if ident else ""
                # Attribute order for plain code pre probe with id/classes unknown; likely id class kv as data
                other=""
                for k,v in kvs:
                    name=k if is_html_attr_name(k) else "data-"+k
                    other+=f' {name}="{self.esc_attr(v)}"'
                # Re-evaluate order maybe class first as observed <pre class="python">
                return Literal(f'<pre{class_attr}{id_attr}{other}><code>{self.esc_code(code)}</code></pre>')
            else:
                return Literal(f'<pre><code>{self.esc_code(code)}</code></pre>')
        self.has_highlighted_code=True
        self.code_block_num+=1
        cb_id=ident if ident else f"cb{self.code_block_num}"
        number_lines="numberLines" in classes or "number-lines" in classes
        start_from=1
        if "startFrom" in kvdict:
            try: start_from=int(kvdict["startFrom"])
            except: start_from=1
        if "startfrom" in kvdict:
            try: start_from=int(kvdict["startfrom"])
            except: pass
        other_classes=[c for c in classes[1:] if c not in ("numberLines",)]
        pre_classes=["sourceCode"]
        if number_lines: pre_classes.append("numberSource")
        pre_classes.append(lang)
        if number_lines: pre_classes.append("numberLines")
        pre_classes.extend(other_classes)
        div_attrs=[f'class="sourceCode"']
        div_attrs.append(f'id="{self.esc_attr(cb_id)}"')
        # kvs go to div as data-*, preserving camelCase keys as data-startFrom if startFrom, others data-k
        for k,v in kvs:
            div_attrs.append(f'data-{k}="{self.esc_attr(v)}"')
        # Tokens
        lines_tokens=tokenize_code(code,lang)
        html_lines=[]
        for idx,line_toks in enumerate(lines_tokens):
            lno=start_from+idx
            anchor_attrs=f'href="#{cb_id}-{lno}"' + ('' if number_lines else ' aria-hidden="true" tabindex="-1"')
            line_html="".join(
                self.esc_code(tok) if typ is None else f'<span class="{TOKEN_ABBR.get(typ,"")}">{self.esc_code(tok)}</span>' if TOKEN_ABBR.get(typ) else self.esc_code(tok)
                for typ,tok in line_toks
            )
            html_lines.append(f'<span id="{cb_id}-{lno}"><a {anchor_attrs}></a>{line_html}</span>')
        code_inner="\n".join(html_lines)
        code_style=f' style="counter-reset: source-line {start_from-1};"' if (number_lines and start_from!=1) else ""
        # Build as literal with wrapping behavior for tag start: pandoc uses Doc for tags, causing <pre\n class=...> if line exceeds. Our Literal won't wrap; construct with Doc for top tags and literal code lines are in nowrap spans.
        # Use Doc assembly manually:
        div_open=self.open_tag_doc("div",div_attrs)
        pre_open=self.open_tag_doc("pre",[f'class="{self.esc_attr(" ".join(pre_classes))}"'])
        code_open_attrs=[f'class="sourceCode {self.esc_attr(lang)}"']
        if code_style:
            code_open_attrs.append(f'style="counter-reset: source-line {start_from-1};"')
        code_open=self.open_tag_doc("code",code_open_attrs)
        # code_inner lines should not wrap (span lines contain spaces but code spaces non-breakable)
        return Cat([div_open,pre_open,code_open,Nowrap(Literal(code_inner)),Text("</code></pre></div>")])
    # Tables
    def table_doc(self,b):
        attr,caption,specs,head,bodies,foot=b["c"]
        docs=[]
        open_doc=self.open_tag_doc("table",self.attrs_list(attr))
        docs.append(open_doc); docs.append(Cr())
        # caption position above default
        caption_doc=None
        short,capblocks=caption
        # Caption rendered inline from blocks without p tags: if capblocks have Plain/Para, render inlines; multiple blocks maybe render blocks stripped? Use blocks_to_doc but caption content was Plain and our block renders Plain as inlines.
        if capblocks or short:
            if capblocks:
                if len(capblocks)==1 and capblocks[0].get("t") in ("Plain","Para"):
                    cap_inner=self.inlines_to_doc(capblocks[0]["c"])
                else:
                    cap_inner=self.blocks_to_doc(capblocks)
            else:
                cap_inner=self.inlines_to_doc(short)
            caption_doc=Cat([Text("<caption>"),cap_inner,Text("</caption>")])
        caption_below=(self.opts and self.opts.table_caption_position=="below")
        if caption_doc and not caption_below:
            docs.append(caption_doc); docs.append(Cr())
        # colgroup if any width not default
        if any(cw["t"]!="ColWidthDefault" for _al,cw in specs):
            cols=[]
            for _al,cw in specs:
                w=round(float(cw["c"])*100)
                cols.append(Text(f'<col style="width: {w}%" />'))
            cg=cols[0]
            for co in cols[1:]: cg=Cat([cg,Cr(),co])
            docs.append(Cat([Text("<colgroup>"),Cr(),cg,Cr(),Text("</colgroup>")])); docs.append(Cr())
        # header
        if head[1]:
            docs.append(Text("<thead>")); docs.append(Cr())
            for row in head[1]:
                docs.append(self.table_row_doc(row,specs,is_header=True)); docs.append(Cr())
            docs.append(Text("</thead>")); docs.append(Cr())
        # bodies
        for battr,rhc,inter,rows in bodies:
            docs.append(Text("<tbody>")); docs.append(Cr())
            for row in inter:
                docs.append(self.table_row_doc(row,specs,is_header=False,row_head_cols=rhc,intermediate=True)); docs.append(Cr())
            for row in rows:
                docs.append(self.table_row_doc(row,specs,is_header=False,row_head_cols=rhc)); docs.append(Cr())
            docs.append(Text("</tbody>")); docs.append(Cr())
        # foot
        if foot[1]:
            docs.append(Text("<tfoot>")); docs.append(Cr())
            for row in foot[1]:
                docs.append(self.table_row_doc(row,specs,is_header=False)); docs.append(Cr())
            docs.append(Text("</tfoot>")); docs.append(Cr())
        if caption_doc and caption_below:
            docs.append(caption_doc); docs.append(Cr())
        # Remove last Cr before table close
        if docs and docs[-1]==Cr(): docs.pop()
        # But table closing should be on new line: our blocks_to_doc will add? table_doc returns one block; internal structure should end </table> after newline from previous. The Cr before was placed after tbody, so retain it and close.
        # Rebuild sequence: if we popped, add Cr then close if there was any substructure. Actually output ends </tbody>\n</table>. So if popped, need Cr.
        docs.append(Cr()); docs.append(Text("</table>"))
        return Cat(docs)
    def table_row_doc(self,row,specs,is_header=False,row_head_cols=0,intermediate=False):
        rattr,cells=row
        docs=[Text("<tr>"),Cr()]
        for idx,cell in enumerate(cells):
            cattr,align,rs,cs,blocks=cell
            if is_header or idx<row_head_cols:
                tag="th"
            else:
                tag="td"
            cell_attr=self.attrs_list(cattr)
            # rowspan/colspan if >1; alignment style if align not default and not maybe equal spec alignment?
            col_align=specs[idx][0]["t"] if idx<len(specs) else "AlignDefault"
            effective_align=align["t"] if align["t"]!="AlignDefault" else col_align
            style=None
            if effective_align=="AlignLeft": style="text-align: left;"
            elif effective_align=="AlignRight": style="text-align: right;"
            elif effective_align=="AlignCenter": style="text-align: center;"
            attrs=[]
            # Rowspan/colspan attributes order? Pandoc table html likely just appends after attr.
            if cs>1: attrs.append(f'colspan="{cs}"')
            if rs>1: attrs.append(f'rowspan="{rs}"')
            all_attrs=cell_attr+attrs+([f'style="{style}"'] if style else [])
            # Cell content: if single Plain/Para, render inlines; if multiple blocks render blocks
            if len(blocks)==1 and blocks[0].get("t") in ("Plain",):
                content=self.inlines_to_doc(blocks[0]["c"])
                docs.append(self.tag_doc(tag,all_attrs,content))
            elif len(blocks)==1 and blocks[0].get("t")=="Para":
                # In table, Para cell could (?) grid table cells with Para produce <p> or just content? Original pandoc: tables cells blocks rendered with Plain if first? It may keep <p> if multiple / nonempty. Use blocks if more than one (?) Pipe cells are Plain, grid cells convert Para->Plain by parser for simple. If AST has Para, HTML likely uses inlines only for single Para too (not <p>) in td? Investigate later.
                content=self.inlines_to_doc(blocks[0]["c"])
                docs.append(self.tag_doc(tag,all_attrs,content))
            elif not blocks:
                docs.append(self.tag_doc(tag,all_attrs,Empty()))
            else:
                content=self.blocks_to_doc(blocks)
                docs.append(Cat([self.open_tag_doc(tag,all_attrs),Cr(),content,Cr(),Text(f"</{tag}>")]))
            docs.append(Cr())
        docs.append(Text("</tr>"))
        return Cat(docs)
    def figure_doc(self,b):
        attr,caption,blocks=b["c"]
        short,capblocks=caption
        # Determine image move id if single image
        fig_attr=list(attr) if attr else ["",[],[]]
        body_blocks=blocks
        # Caption inline content
        caption_inlines=None
        if capblocks and len(capblocks)==1 and capblocks[0].get("t") in ("Plain","Para"):
            caption_inlines=capblocks[0]["c"]
        aria=""
        # If single Plain with one Image, get alt to compare stringify caption
        alt_text=None; single_image=None
