                    # move id to figure: modify a copy of image attr to remove id
                    fig_attr=[single_image["c"][0][0],fig_attr[1],fig_attr[2]]
                    new_img_attr=["",list(single_image["c"][0][1]),list(single_image["c"][0][2])]
                    single_image={"t":"Image","c":[new_img_attr,single_image["c"][1],single_image["c"][2]]}
                    body_blocks=[{"t":body_blocks[0]["t"],"c":[single_image]}]
        cap_text=stringify(caption_inlines).strip() if caption_inlines else ""
        if alt_text is not None and cap_text and cap_text==alt_text:
