def flatten_inlines_for_string(inlines):
    return stringify(inlines)

def ends_with_period(inlines):
    s=stringify(inlines).rstrip()
    return s.endswith('.') if s else False

def to_ascii_entities(s):
    import html.entities
    out=""
    for ch in s:
        if ord(ch)>127:
            name=html.entities.codepoint2name.get(ord(ch))
            if name: out+=f"&{name};"
            else: out+=f"&#x{ord(ch):x};"
        else: out+=ch
    return out

