            return self.list_doc(items,markers)
        for idx in range(len(items)):
            n=start+idx if self.ext("startnum",True) else idx+1
            if not self.ext("fancy_lists",False) and style not in ("Decimal","DefaultStyle"):
                core=str(idx+1)
            elif style=="LowerAlpha": core=alpha(n)
            elif style=="UpperAlpha": core=alpha(n,True)
            elif style=="LowerRoman": core=roman(n)
            elif style=="UpperRoman": core=roman(n,True)
            else: core=str(n)
            if delim=="OneParen": markers.append(core+")")
            elif delim=="TwoParens": markers.append("("+core+")")
            else: markers.append(core+".")
        return self.list_doc(items,markers)
    def list_doc(self,items,markers):
        if not items: return Empty()
        # Determine loose: if any item first block is Para (not Plain) OR item has multiple blocks and not all blocks except list etc.. Simplified: loose if any block in any item is Para, or any item has >1 blocks where a blankline logically occurs (i.e. first block is Para from original tight conversion would be Plain)
        loose=False
        for item in items:
            for b in item:
                if b.get("t")=="Para": loose=True
        item_docs=[]
        marker_widths=[str_width(m) for m in markers]
        # Content column / indent: Pandoc uses marker width + spaces: for bullet, 2; for ordered, if marker width ... Examples:
        # - "- " (2), "1.  " (4), "10. " (4), "(1) " (4?) , "(@) " but example lists continuation indent 4 (four space rule)
        # Rule from Markdown writer: indent = max marker width + 2 if marker width <3? For 1./2. width2 => 4. For bullet width1 =>2? That is marker+1 not consistent. 
        # It may set spaces after marker based on a target content indent of 4 for ordered lists because ordered list marker + space must align and subcontent indented to first nonspace; for 1. (2 chars) plus two spaces = 4. For 10. (3) plus one =4. For 100. (4)+1=5. Bullet content at 2 because sublist indentation is 2 for bullet.
        # If four_space_rule extension, all indents 4.
        indents=[]
        for m,w in zip(markers,marker_widths):
            if self.ext("four_space_rule",False) or m.startswith("(@"):
                indent=4
                if w>=4: indent=w+1
            elif m in ("-","+","*"):
                indent=2
            else:
                indent=max(w+1,4) if w<4 else w+1
                # For markers with parens (1) width3 => indent 4 (1 space), (10) width4=>5
            indents.append(indent)
        for idx,item in enumerate(items):
            marker=markers[idx]; indent=indents[idx]
            spaces=" "*(indent-str_width(marker))
            inner=self.blocks_to_doc(item)
            # Use Hang: first docs marker+spaces, subsequent lines indented by spaces of indent width
            doc=Cat([Text(marker+spaces),Nest(" "*indent,inner)])
            item_docs.append(doc)
        if loose:
            return join_docs(item_docs,Blank())
        else:
            return join_docs(item_docs,Cr())
    def definition_list_doc(self,c):
        if not self.ext("definition_lists",False) and not self.plain:
            # Render as bullet-ish paragraphs (fallback)
            docs=[]
            for term,defs in c:
                docs.append(self.inlines_to_doc(term))
                for d in defs: docs.append(self.blocks_to_doc(d))
            return join_docs(docs,Blank())
        item_docs=[]
        loose_global=False
        for term,defs in c:
            for d in defs:
                if any(b.get("t")=="Para" for b in d): loose_global=True
        for term,defs in c:
            term_doc=self.inlines_to_doc(term,first=True)
            parts=[term_doc]
            if loose_global:
                # Pandoc's loose definition lists: blank line before each definition? Example in manual, if definition is Para, blank between term and definition and each def becomes Para (indented paragraph) without explicit para marker? We'll produce:
                # Term
                #
                # :   Definition
                #
                for d in defs:
                    inner=self.blocks_to_doc(d)
                    parts.append(Cat([Text(":   "),Nest("    ",inner)]))
                item_docs.append(join_docs(parts,Blank()))
            else:
                for d in defs:
                    inner=self.blocks_to_doc(d)
                    parts.append(Cat([Text(":   "),Nest("    ",inner)]))
                item_docs.append(join_docs(parts,Cr()))
        return join_docs(item_docs,Blank() if loose_global else Blank())
    # Figure/Div
    def figure_doc(self,b):
        attr,caption,blocks=b["c"]
        short,capblocks=caption
        # Simple implicit figure: one Plain with one Image
        if len(blocks)==1 and blocks[0].get("t") in ("Plain","Para") and len(blocks[0]["c"])==1 and blocks[0]["c"][0].get("t")=="Image" and self.ext("implicit_figures",False):
            img=blocks[0]["c"][0]
            # If caption differs from alt, pandoc may set alt to caption text when outputting? Figure AST caption is alt for implicit figures, image alt same. Just render image inline with alt as caption (image alt already)
            # Figure attr id needs transfer to image if link_attributes
            if attr and attr[0]:
                # clone attr add id to image attr
                ia=img["c"][0]; new_img={"t":"Image","c":[[attr[0],list(ia[1])+list(attr[1]),list(ia[2])+list(attr[2])],img["c"][1],img["c"][2]]}
                return self.inlines_to_doc([new_img],first=True)
            return self.inlines_to_doc([img],first=True)
        # Generic Figure: in Markdown writer, if raw_html enabled, output HTML figure using HTML writer? Pandoc may output image (?) For now if figcaption simple and blocks plain image handled. Else render blocks and caption as paragraph.
        docs=[]
        docs.append(self.blocks_to_doc(blocks))
        if capblocks:
            docs.append(self.blocks_to_doc(capblocks))
        return join_docs(docs,Blank())
    def div_doc(self,b):
        attr,blocks=b["c"]
        if self.plain:
            return self.blocks_to_doc(blocks)
        if self.ext("fenced_divs",False):
            ident,classes,kvs=attr
            if ident=="" and len(classes)==1 and not kvs:
                info=" "+classes[0]
            elif ident=="" and not classes and not kvs:
                return self.blocks_to_doc(blocks)
            else:
                parts=[]
                if ident: parts.append("#"+ident)
                for cl in classes: parts.append("."+cl)
                for k,v in kvs: parts.append(f'{k}="{v}"' if needs_quote(v) else f"{k}={v}")
                info=" {"+" ".join(parts)+"}"
            inner=self.blocks_to_doc(blocks)
            # fence length longer than any ::: line in inner rendered (?) simple 3
            return Cat([Text(":::"+info),Cr(),inner,Cr(),Text(":::")])
        elif self.ext("native_divs",False) and self.ext("raw_html",False):
            # HTML div tags as RawBlocks around (with blank lines)
            attrs=""
            ident,classes,kvs=attr
            if ident: attrs+=f' id="{ident}"'
            if classes: attrs+=f' class="{" ".join(classes)}"'
            for k,v in kvs: attrs+=f' {k}="{v}"'
            inner=self.blocks_to_doc(blocks)
            return Cat([Text(f"<div{attrs}>"),Blank(),inner,Blank(),Text("</div>")])
        return self.blocks_to_doc(blocks)
    # Tables
    def table_doc(self,b):
        return markdown_table_doc(self,b)
    # Inline
    def inlines_to_doc(self,inlines,first=False):
        docs=[]
        for idx,x in enumerate(inlines):
            docs.append(self.inline_to_doc(x,first=(first and idx==0)))
        return Cat(docs)
    def inline_to_doc(self,x,first=False):
        t=x.get("t"); c=x.get("c")
        if t=="Str":
            return Text(escape_markdown_str(c,self,first=first))
        if t=="Space": return BS()
        if t=="SoftBreak":
            if self.ext("hard_line_breaks",False):
                return Cat([Text("\\"),Cr()])
            return SoftBreak()
        if t=="LineBreak":
            return Cat([Text("\\"),Cr()])
        if t=="Emph":
            if self.plain: return self.inlines_to_doc(c)
            return Cat([Text("*"),self.inlines_to_doc(c),Text("*")])
        if t=="Strong":
            if self.plain: return self.inlines_to_doc(c)
            return Cat([Text("**"),self.inlines_to_doc(c),Text("**")])
        if t=="Underline":
            if self.plain: return self.inlines_to_doc(c)
            if self.ext("bracketed_spans",False):
                return Cat([Text("["),self.inlines_to_doc(c),Text("]{.underline}")])
            if self.ext("raw_html",False): return Cat([Text('<span class="underline">'),self.inlines_to_doc(c),Text("</span>")])
            return self.inlines_to_doc(c)
        if t=="Strikeout":
            if self.plain: return self.inlines_to_doc(c)
            if self.ext("strikeout",False): return Cat([Text("~~"),self.inlines_to_doc(c),Text("~~")])
            if self.ext("raw_html",False): return Cat([Text("<del>"),self.inlines_to_doc(c),Text("</del>")])
            return self.inlines_to_doc(c)
        if t=="Superscript":
            if self.plain: return Cat([Text("^"),self.inlines_to_doc(c),Text("^")]) if False else self.inlines_to_doc(c)
            if self.ext("superscript",False): return Cat([Text("^"),self.inlines_to_doc(c),Text("^")])
            if self.ext("raw_html",False): return Cat([Text("<sup>"),self.inlines_to_doc(c),Text("</sup>")])
            return self.inlines_to_doc(c)
        if t=="Subscript":
            if self.plain: return self.inlines_to_doc(c)
            if self.ext("subscript",False): return Cat([Text("~"),self.inlines_to_doc(c),Text("~")])
            if self.ext("raw_html",False): return Cat([Text("<sub>"),self.inlines_to_doc(c),Text("</sub>")])
            return self.inlines_to_doc(c)
        if t=="SmallCaps":
            if self.plain: return self.inlines_to_doc(c)
            if self.ext("bracketed_spans",False): return Cat([Text("["),self.inlines_to_doc(c),Text("]{.smallcaps}")])
            if self.ext("raw_html",False): return Cat([Text('<span class="smallcaps">'),self.inlines_to_doc(c),Text("</span>")])
            return self.inlines_to_doc(c)
        if t=="Quoted":
            if self.plain:
                if c[0]["t"]=="DoubleQuote": return Cat([Text("“"),self.inlines_to_doc(c[1]),Text("”")])
                else: return Cat([Text("‘"),self.inlines_to_doc(c[1]),Text("’")])
            if self.ext("smart",False):
                if c[0]["t"]=="DoubleQuote": return Cat([Text('"'),self.inlines_to_doc(c[1]),Text('"')])
                else: return Cat([Text("'"),self.inlines_to_doc(c[1]),Text("'")])
            else:
                if c[0]["t"]=="DoubleQuote": return Cat([Text("“"),self.inlines_to_doc(c[1]),Text("”")])
                else: return Cat([Text("‘"),self.inlines_to_doc(c[1]),Text("’")])
        if t=="Code":
            attr,txt=c
            if self.plain: return Text(txt if not (self.opts and self.opts.ascii) else to_ascii_entities(txt))
            maxrun=0
            for m in re.finditer(r'`+',txt): maxrun=max(maxrun,len(m.group(0)))
            fence="`"*(maxrun+1)
            content=txt
            if content.startswith("`") or content.endswith("`") or (content.startswith(" ") and content.endswith(" ") and content.strip()):
                content=" "+content+" "
            doc=Text(f"{fence}{content}{fence}")
            if attr and (attr[0] or attr[1] or attr[2]) and self.ext("inline_code_attributes",False):
                return Cat([doc,Text(attr_braces(attr))])
            if attr and (attr[1]) and self.commonmark and self.ext("attributes",False):
                return Cat([doc,Text(attr_braces(attr))])
            return doc
        if t=="Math":
            if self.plain:
                # plain writer renders TeX math as italic-ish plain conversion like HTML plain tex math? For early, output tex text stripped of commands simple
                return Text(plain_math(c[1]))
            if self.ext("tex_math_dollars",False) or self.ext("tex_math_gfm",False):
                if c[0]["t"]=="DisplayMath": return Text(f"$${c[1]}$$")
                return Text(f"${c[1]}$")
            if self.ext("tex_math_single_backslash",False):
                return Text((f"\\[{c[1]}\\]" if c[0]["t"]=="DisplayMath" else f"\\({c[1]}\\)"))
            if self.ext("tex_math_double_backslash",False):
                return Text((f"\\\\[{c[1]}\\\\]" if c[0]["t"]=="DisplayMath" else f"\\\\({c[1]}\\\\)"))
            # fallback: raw tex \(...\)
            return Text((f"\\[{c[1]}\\]" if c[0]["t"]=="DisplayMath" else f"\\({c[1]}\\)"))
        if t=="RawInline":
            if self.plain: return Empty()
            fmt=c[0] if isinstance(c[0],str) else c[0].get("c","")
            if fmt in ("markdown","commonmark") or fmt==self.fmt: return Text(c[1])
            if fmt in ("html","html5","html4") and self.ext("raw_html",False): return Text(c[1])
            if fmt in ("tex","latex","context") and self.ext("raw_tex",False): return Text(c[1])
            return Empty()
        if t=="Link":
            return self.link_doc(x,first=first)
        if t=="Image":
            return self.image_doc(x,first=first)
        if t=="Span":
            attr,inls=c
            if self.plain: return self.inlines_to_doc(inls)
            if not attr or (attr[0]=="" and not attr[1] and not attr[2]):
                return self.inlines_to_doc(inls)
            if self.ext("bracketed_spans",False):
                return Cat([Text("["),self.inlines_to_doc(inls),Text(f"]{attr_braces(attr)}")])
            if self.ext("native_spans",False) and self.ext("raw_html",False):
                attrs=html_attrs(attr)
                return Cat([Text(f"<span{attrs}>"),self.inlines_to_doc(inls),Text("</span>")])
            return self.inlines_to_doc(inls)
        if t=="Note":
            return self.note_doc(x)
        if t=="Cite":
            if self.plain or not self.ext("citations",False):
                return self.inlines_to_doc(c[1])
            return citation_doc(self,x)
        return Empty()
    def link_doc(self,x,first=False):
        attr,inls,target=x["c"]; url,title=target
        if self.plain:
            return self.inlines_to_doc(inls)
        # Autolink
        txt=stringify(inls)
        classes=attr[1] if attr else []
        if "uri" in classes and txt==url:
            if self.ext("autolink_bare_uris",False):
                return Text(url)
            return Text(f"<{url}>")
        if "email" in classes and url=="mailto:"+txt:
            return Text(f"<{txt}>")
        if "wikilink" in classes and (self.ext("wikilinks_title_after_pipe",False) or self.ext("wikilinks_title_before_pipe",False)):
            if txt==url:
                return Text(f"[[{url}]]")
            if self.ext("wikilinks_title_after_pipe",False):
                return Cat([Text(f"[[{url}|"),self.inlines_to_doc(inls),Text("]]")])
            else:
                return Cat([Text("[["),self.inlines_to_doc(inls),Text(f"|{url}]]")])
        text_doc=self.inlines_to_doc(inls)
        attr_s=""
        if attr and (attr[0] or attr[1] or attr[2]) and self.ext("link_attributes",False):
            # Exclude uri/email/wikilink special classes from written attrs?
            filtered=[attr[0],[c for c in attr[1] if c not in ("uri","email","wikilink")],attr[2]]
            if filtered[0] or filtered[1] or filtered[2]: attr_s=attr_braces(filtered)
        if self.opts and self.opts.reference_links:
            label=self.get_ref_label(url,title,inls)
            location=self.opts.reference_location
            # For block/section, reference definitions are in footnotes docs handling not yet; use full ref syntax
            return Cat([Text("["),text_doc,Text(f"]{attr_s}"),Text(f"[{label}]")]) if attr_s else Cat([Text("["),text_doc,Text(f"][{label}]")])
        dest=link_destination(url,title)
        return Cat([Text("["),text_doc,Text(f"]{dest}{attr_s}")])
    def image_doc(self,x,first=False):
        attr,alt,target=x["c"]; url,title=target
        if self.plain:
            alt_txt=stringify(alt).strip()
            return Text(f"[{alt_txt}]") if alt_txt else Text("[image]")
        attrs=""
        if attr and (attr[0] or attr[1] or attr[2]) and self.ext("link_attributes",False):
            attrs=attr_braces(attr)
        dest=link_destination(url,title)
        return Cat([Text("!["),self.inlines_to_doc(alt),Text(f"]{dest}{attrs}")])
    def note_doc(self,x):
        if self.plain:
            # Plain notes are footnotes same as markdown? Plain writer footnotes displayed as [^n]? Probe later. Use footnote numbers as markdown with definitions at end too.
            pass
        if self.ext("footnotes",False):
            self.footnotes.append(x["c"]); num=len(self.footnotes)
            pref=self.opts.id_prefix if self.opts else ""
            return Text(f"[^{num}]")
        if self.ext("inline_notes",False):
            # ^[content] if one Para
            blocks=x["c"]
            if len(blocks)==1 and blocks[0].get("t") in ("Para","Plain"):
                return Cat([Text("^["),self.inlines_to_doc(blocks[0]["c"]),Text("]")])
            # fallback footnotes even if ext off?
            self.footnotes.append(x["c"]); return Text(f"[^{len(self.footnotes)}]")
        return Empty()
    def footnote_defs_doc(self,notes,start=1):
        docs=[]
        for idx,blocks in enumerate(notes,start):
            inner=self.blocks_to_doc(blocks)
            docs.append(Cat([Text(f"[^{idx}]: "),Nest("    ",inner)]))
            # footnotes definitions are on new paragraph lines; first block inline follows marker, subsequent blocks indented 4 by Nest
        return join_docs(docs,Blank())
    def get_ref_label(self,url,title,inlines):
        key=(url,title)
        if key in self.ref_label_by_key: return self.ref_label_by_key[key]
        # Pandoc reference labels based on link text string or if duplicate numeric suffix. It uses a label generated from text maybe stripped punctuation.
        base=stringify(inlines).strip()
        if not base: base=url
        label=base; n=1
        # uniqueness compared case-insensitively
        while label.lower() in self.used_ref_labels:
            n+=1; label=f"{base}{n}" if False else f"{base}-{n}"  # guess
        self.used_ref_labels.add(label.lower()); self.ref_label_by_key[key]=label
        self.reference_links_list.append((label,url,title))
        return label
    def reference_defs_doc(self):
        docs=[]
        for label,url,title in self.reference_links_list:
            # Label may need bracket escaping
            line=f"[{label}]: {url_for_ref(url)}"
            if title: line+=f' "{title}"'
            docs.append(Text(line))
        return join_docs(docs,Cr())

def join_docs(docs,sep):
    docs=[d for d in docs if d!=("empty",)]
    if not docs: return Empty()
    out=docs[0]
    for d in docs[1:]: out=Cat([out,sep,d])
    return out

def needs_quote(v):
    return v=="" or any(ch.isspace() for ch in v)
def attr_braces(attr):
    ident,classes,kvs=attr; parts=[]
    if ident: parts.append("#"+ident)
    for cl in classes: parts.append("."+cl)
    for k,v in kvs: parts.append(f'{k}="{v}"' if needs_quote(v) else f"{k}={v}")
    return "{"+" ".join(parts)+"}"
def html_attrs(attr):
    ident,classes,kvs=attr; s=""
    if ident: s+=f' id="{ident}"'
    if classes: s+=f' class="{" ".join(classes)}"'
    for k,v in kvs: s+=f' {k}="{v}"'
    return s
def link_destination(url,title):
    if url=="" and not title: return "()"
    # Check spaces/control/() unbalanced
    use_angle=False
    if any(ch.isspace() for ch in url): use_angle=True
    if url and (url.count('(')!=url.count(')') or url.startswith(')') ): use_angle=True
    dest=f"<{url}>" if use_angle else url
    if title:
        if '"' not in title: dest+=f' "{title}"'
        elif "'" not in title: dest+=f" '{title}'"
        else: dest+=' "'+title.replace('"','\\"')+'"'
    return f"({dest})"
def url_for_ref(url):
    return f"<{url}>" if any(ch.isspace() for ch in url) else url

def escape_markdown_str(s,writer,first=False):
    if writer.opts and writer.opts.ascii and not writer.plain:
        # Markdown writer ascii uses html entities for non-ASCII (via toAscii)
        # But escaping below for smart sequences should apply to ascii chars. Convert first.
        s=to_ascii_entities(s)
    elif writer.opts and writer.opts.ascii and writer.plain:
        s=to_ascii_entities(s)
    out=""
    i=0
    smart=writer.ext("smart",False) and not writer.plain
    while i<len(s):
        ch=s[i]
        # smart sequences
        if smart:
            if s.startswith("---",i) or s.startswith("--",i):
                # escape first dash
                out+="\\--" if s.startswith("--",i) and not s.startswith("---",i) else "\\---"
                i+=3 if s.startswith("---",i) else 2; continue
            if s.startswith("...",i):
                out+="\\..."; i+=3; continue
            if ch=='"' :
                out+='\\"'; i+=1; continue
        if ch=='\u00a0':
            out+="\\ "; i+=1; continue
        if ch=='\\': out+="\\\\"; i+=1; continue
        if ch=='`': out+="\\`"; i+=1; continue
        if ch=='*': out+="\\*"; i+=1; continue
        if ch=='_':
            # intraword: if between alnum and ext, no escape
            before=s[i-1] if i>0 else ""; after=s[i+1] if i+1<len(s) else ""
            if writer.ext("intraword_underscores",True) and before.isalnum() and after.isalnum():
                out+="_"
            else: out+="\\_"
            i+=1; continue
        if ch in '[]': out+="\\"+ch; i+=1; continue
        if ch=='<' :
            after=s[i+1] if i+1<len(s) else ""
            if after.isalpha() or after in '/!?' or re.match(r'[A-Za-z][A-Za-z0-9+.-]*:',s[i+1:]):
                out+="\\<"
            else: out+="<"
            i+=1; continue
        if ch=='!' and i+1<len(s) and s[i+1]=='[': out+="\\!"; i+=1; continue
        if ch=='$' and writer.ext("tex_math_dollars",False): out+="\\$"; i+=1; continue
        if ch=='~' and (writer.ext("subscript",False) or writer.ext("strikeout",False)): out+="\\~"; i+=1; continue
        if ch=='^' and writer.ext("superscript",False): out+="\\^"; i+=1; continue
        if ch=='|' and getattr(writer,'in_table',False) and writer.ext("pipe_tables",False): out+="\\|"; i+=1; continue
        if first and i==0:
            if ch=='#': out+="\\#"; i+=1; continue
            if ch=='>': out+="\\>"; i+=1; continue
            if ch in '-+' and (i+1>=len(s) or s[i+1].isspace()):
                out+="\\"+ch; i+=1; continue
            # ordered list at start of first token? Pandoc escapes . or ) after digits in first token; token may be "1."
            m=re.match(r'(\d+)([.)])',s[i:])
            if m:
                out+=m.group(1)+"\\"+m.group(2); i+=len(m.group(0)); continue
        out+=ch; i+=1
    return out

def plain_math(tex):
    # Strip braces/commands very simply for plain writer
    s=re.sub(r'\\frac\{([^{}]*)\}\{([^{}]*)\}',r'\1/\2',tex)
    s=re.sub(r'\\([A-Za-z]+)',lambda m: {'alpha':'α','beta':'β'}.get(m.group(1),m.group(1)),s)
    return s.replace('{','').replace('}','')

def citation_doc(writer,x):
    cites,disp=x["c"]
    # If only AuthorInText
    docs=[]
    # Pandoc's markdown writer for a Cite uses writeCite which may place all citations in brackets except AuthorInText ones. Implementation based on modes:
    # Iterate: maintain bracket group for Normal/Suppress.
    i=0
    while i<len(cites):
        cit=cites[i]; mode=cit.get("citationMode",{}).get("t")
        if mode=="AuthorInText":
            if docs: docs.append(BS())
            docs.append(Text("@"+cit.get("citationId","")))
            if cit.get("citationSuffix"):
                docs.append(BS()); docs.append(Text("[")); docs.append(writer.inlines_to_doc(cit["citationSuffix"])); docs.append(Text("]"))
            i+=1
        else:
            # collect consecutive normal/suppress
            group=[]
            while i<len(cites) and cites[i].get("citationMode",{}).get("t")!="AuthorInText":
