        lines=[f"{pad}{key}:"]
        for item in c:
            sv=yaml_scalar(item,writer)
            if item.get("t") in ("MetaMap","MetaList"):
                # complex nested in list - simplified indentation
                sub=yaml_lines("-",item,writer,indent+2)
                lines.extend(sub)
            else:
                lines.append(f"{pad}- {sv}")
