    if t=="MetaMap":
        lines=[f"{pad}{key}:"]
        for kk in sorted(c.keys()): lines.extend(yaml_lines(kk,c[kk],writer,indent+2))
        return lines
    sv=yaml_scalar(mv,writer)
    if "\n" in sv.strip("\n"):
        lines=[f"{pad}{key}: |"]
        for line in sv.strip().split("\n"): lines.append(f"{pad}  {line}")
