    return Literal("\n".join(lines))

def grid_table_doc(writer,b,header_rows,body_rows,specs,caption,attr):
    # Calculate cell line widths. Widths are source ColWidths proportional to columns if specified, else max content line width
    all_rows=header_rows+body_rows
    ncol=len(specs)
    # Gather cell lines (blocks rendered plain markdown)
    rows_lines=[]
    for row in all_rows:
        rows_lines.append([cell_text(writer,cell[4]) for cell in row[1]])
    widths=[]
    cols=writer.opts.columns if writer.opts else 72
    for idx in range(ncol):
        if specs[idx][1]["t"]!="ColWidthDefault":
            widths.append(max(3,int(round(float(specs[idx][1]["c"])*cols))-2))
        else:
            maxw=0
            for row in rows_lines:
                if idx<len(row): maxw=max(maxw,max((str_width(x) for x in row[idx]),default=0))
            widths.append(max(3,maxw))
    def sep(char='-',aligns=None):
        parts=[]
        for idx,w in enumerate(widths):
            seg=char*w
            if aligns and char=='=':
                a=aligns[idx]
                if a=="AlignLeft" and False: pass
                # Grid alignments are encoded by colons at boundaries in source; pandoc writer may not output colon syntax in markdown grid - ignore for now
            parts.append(seg)
        return "+"+"+".join(parts)+"+"
    lines=[]; cap=caption_doc_md(writer,caption,attr)
    if cap:
        txt,suffix=cap; lines.append(f": {txt}{suffix}"); lines.append("")
    lines.append(sep('-'))
    header_count=len(header_rows)
    for ridx,row in enumerate(rows_lines):
        maxlines=max((len(c) for c in row),default=1)
        for li in range(maxlines):
            cells=[]
            for idx in range(ncol):
                txt=row[idx][li] if idx<len(row) and li<len(row[idx]) else ""
                # Wrap cell text if longer than width? Grid cells blocks may wrap based widths; cell_text rendered unlimited lines might exceed width - trunc/wrap naive using writer rendering at width? Complex; pad/truncate not ideal.
                cells.append(" "+txt.ljust(widths[idx]-1) if False else txt.ljust(widths[idx]))
                # grid line format "| txt |" where width includes spaces: segment width = widths[idx] characters between pipes; our widths chosen as dash count. If txt short, pad. Use one leading space consumed in width.
            # redo cells padding precisely
            line="|"
            for idx in range(ncol):
                txt=row[idx][li] if idx<len(row) and li<len(row[idx]) else ""
                inner=" "+txt
                inner=inner.ljust(widths[idx])[:widths[idx]]
                line+=inner+"|"
            lines.append(line)
        if ridx==header_count-1 and header_rows:
            lines.append(sep('='))
        else:
            lines.append(sep('-'))
    return Literal("\n".join(lines))

def write_markdown(doc,opts,exts,fmt="markdown"):
    w=MarkdownWriter(opts,exts,fmt)
    return w.write(doc)
