        if self.footnotes and (not self.opts or self.opts.reference_location=="document"):
            docs.append(Blank()); docs.append(self.footnote_defs_doc(self.footnotes, start=1)); self.footnotes=[]
        if self.opts and self.opts.reference_links and self.reference_links_list:
            docs.append(Blank()); docs.append(self.reference_defs_doc())
        s=render(Cat(docs),columns=self.opts.columns if self.opts else 72,wrap=self.opts.wrap if self.opts else "auto")
        extra={}
        # Title block for template
        extra["titleblock"]=self.titleblock(doc)
        if self.opts and self.opts.toc:
            extra["table-of-contents"]=self.toc_markdown(doc)
            extra["toc"]=True
        return s,extra
    def titleblock(self,doc):
        meta=doc.get("meta",{})
        if self.plain:
            lines=[]
            for key in ("title","author","date"):
                if key in meta:
                    # author list each separate line
                    val=meta[key]
                    if val.get("t")=="MetaList":
                        for item in val["c"]: lines.append(meta_plain(item))
                    else:
                        lines.append(meta_plain(val))
            return "\n".join(lines)
        else:
            # YAML metadata rendered if yaml_metadata_block enabled for writer. If standalone handled in main template $titleblock$; in markdown template titleblock is YAML block including title/author etc all meta? Pandoc markdown writer creates title block as YAML if yaml_metadata_block ext enabled, else pandoc title block (% lines) if pandoc_title_block enabled, else mmd title block if.
            if self.ext("yaml_metadata_block",False):
                return meta_to_yaml(meta,self)
            if self.ext("pandoc_title_block",False):
                lines=[]
                for key in ("title","author","date"):
                    if key=="author" and key in meta:
                        val=meta[key]
                        if val.get("t")=="MetaList": auth="; ".join(meta_plain(x) for x in val["c"])
                        else: auth=meta_plain(val)
                        lines.append("% "+auth if auth else "%")
                    elif key in meta:
                        txt=meta_plain(meta[key]); lines.append("% "+txt if txt else "%")
                    else:
                        # Authors/date positional only if later fields exist
                        if any(k in meta for k in ("title","author","date")[ ["title","author","date"].index(key)+1:]): lines.append("%")
                return "\n".join(lines)
            if self.ext("mmd_title_block",False):
                lines=[]
                for k,v in meta.items():
                    lines.append(f"{k}: {meta_plain(v)}")
                return "\n".join(lines)
            return ""
    def toc_markdown(self,doc):
        from .shared import build_toc_tree
        items=build_toc_tree(doc.get("blocks",[]), self.opts.toc_depth if self.opts else 3)
        lines=[]
        def rec(ns,depth):
            for h,ch,num in ns:
                hid=h["c"][1][0]
                text=stringify(h["c"][2]).strip()
                # TOC entry link text should render inline formatting. Use plain stringify for simple; markdown writer renders inlines but here context outside render return string; rendering inline doc with width infinite.
                txt=render(self.inlines_to_doc(h["c"][2]),columns=100000,wrap="none")
                indent="  "*depth
                if self.plain:
                    lines.append(f"{indent}- {txt}")
                else:
                    lines.append(f"{indent}- [{txt}](#{hid}){{#toc-{hid}}}")
                rec(ch,depth+1)
        rec(items,0)
        return "\n".join(lines)
    # Blocks
    def blocks_to_doc(self,blocks,top=False):
        if not blocks: return Empty()
        docs=[]
        for b in blocks:
            before_notes=len(self.footnotes)
            d=self.block_to_doc(b)
            docs.append(d)
            if top and self.opts and self.opts.reference_location=="block" and len(self.footnotes)>before_notes:
                newnotes=self.footnotes[before_notes:]
                # footnotes definitions after block: blank line then defs. But numbering start based on before count.
                docs.append(self.footnote_defs_doc(newnotes,start=before_notes+1))
                # For block location, footnotes are not repeated at end; clear? We kept list for numbering; mark them flushed by using a separate flushed count - easier track footnotes list but when writing end, document case only flushes all. For block mode end doesn't flush.
            if top and self.opts and self.opts.reference_location=="section" and b.get("t")=="Header":
                # This logic would flush before header, not after - complex; handled below by pre-processing? skip.
                pass
        out=docs[0]
        for d in docs[1:]: out=Cat([out,Blank(),d])
        return out
    def block_to_doc(self,b):
        t=b.get("t"); c=b.get("c")
        if t=="Plain":
            return self.inlines_to_doc(c,first=True)
        if t=="Para":
            return self.inlines_to_doc(c,first=True)
        if t=="LineBlock":
            if self.ext("line_blocks",False) and not self.plain:
                docs=[]
                for idx,line in enumerate(c):
                    prefix="| " if line else "|"
                    docs.append(Cat([Text(prefix),self.inlines_to_doc(line,first=True)]))
                return join_docs(docs,Cr())
            else:
                docs=[]
                for idx,line in enumerate(c):
                    if idx>0: docs.append(Cat([Text("\\"),Cr()]))
                    docs.append(self.inlines_to_doc(line,first=True))
                return Cat(docs)
        if t=="CodeBlock": return self.codeblock_doc(c[0],c[1])
        if t=="RawBlock":
            fmt=c[0] if isinstance(c[0],str) else c[0].get("c","")
            if self.plain: return Empty()
            if fmt in ("markdown","commonmark","gfm") or fmt==self.fmt: return Literal(c[1])
            if fmt in ("html","html5","html4") and self.ext("raw_html",False): return Literal(c[1])
            if fmt in ("tex","latex","context") and self.ext("raw_tex",False): return Literal(c[1])
            # Raw blocks for format matching writer variant names: markdown family treats "markdown" only.
            return Empty()
        if t=="BlockQuote":
            inner=self.blocks_to_doc(c)
            # Markdown blockquote blank lines should be ">" alone. Our Prefixed with > will trim blanks (no prefix on blank). Pandoc output earlier with multiple paras? Investigate later; prefix as Nest gives > on content lines.
            # To get ">" on blank lines, custom render by rendering inner to string with same cols-2 then prefix lines literally.
            if not self.plain:
                inner_s=render(inner,columns=(self.opts.columns-2 if self.opts else 70),wrap=self.opts.wrap if self.opts else "auto")
                inner_s=inner_s.rstrip("\n")
                lines=[]
                for line in inner_s.split("\n"):
                    lines.append(("> "+line) if line.strip() else ">")
                return Nowrap(Literal("\n".join(lines)))
            else:
                return Cat([Text("    "),Nest("    ",inner)])
        if t=="BulletList": return self.bullet_list_doc(c)
        if t=="OrderedList": return self.ordered_list_doc(c)
        if t=="DefinitionList": return self.definition_list_doc(c)
        if t=="Header": return self.header_doc(b)
        if t=="HorizontalRule":
            width=self.opts.columns if self.opts else 72
            if self.plain:
                return Text("-"*width)
            return Text("-"*width)
        if t=="Table": return self.table_doc(b)
        if t=="Figure": return self.figure_doc(b)
        if t=="Div": return self.div_doc(b)
        return Empty()
    def header_doc(self,b):
        level,attr,inlines=b["c"]
        if self.plain:
            return self.inlines_to_doc(inlines,first=True)
        attr_s=self.header_attr_str(b)
        use_setext=False
        if self.opts and self.opts.markdown_headings=="setext" and level<=2:
            use_setext=True
        # For commonmark_x etc if headings option default is atx (we set)
        content=self.inlines_to_doc(inlines,first=True)
        if use_setext:
            # Get text width from rendered content with wrap none to make underline length = content length (pandoc writer heading setext underline is one char repeated length of heading line, maybe measured in rendered text)
            txt=render(content,columns=100000,wrap="none")
            line_len=str_width(txt.strip())
            under=("=" if level==1 else "-")*max(1,line_len)
            if attr_s:
                # Setext attr goes on same line after text? Pandoc maybe uses atx if attrs. Skip
                return Cat([Cat([Text("#"*level+" "),content]),Text(" "+attr_s)])
            return Cat([content,Cr(),Text(under)])
        docs=[Text("#"*level+" "),content]
        if attr_s: docs.append(Text(" "+attr_s))
        return Cat(docs)
    def header_attr_str(self,b):
        level,attr,inlines=b["c"]
        if not self.ext("header_attributes",False):
            return ""
        ident,classes,kvs=attr
        # If only id and it is auto-generated, omit. Determine auto ID using writer extension config (which may differ reader) - pandoc writer checks whether id is automatically generated from heading text using the writer's auto identifier algorithm, and whether extension auto_identifiers enabled in *reader?* Actually heading attr in AST loses origin. It compares id to auto id it would generate (with no duplicates) - if matches, omit. If classes/kv present, include id even if auto?
        auto=""
        if ident:
            from ..ast import auto_identifier
            auto=auto_identifier(inlines,self.exts,None,fallback_section=not self.commonmark)
        include_id=ident and not (ident==auto and not classes and not kvs)
        # Special unnumbered shorthand
        if classes==["unnumbered"] and not ident and not kvs:
            return "{-}"
        if not include_id and not classes and not kvs:
            # if id==auto but classes empty, no attrs
            if ident==auto: return ""
            if not ident: return ""
        parts=[]
        if ident: parts.append("#"+ident)
        for cl in classes: parts.append("."+cl)
        for k,v in kvs: parts.append(f'{k}="{v}"' if needs_quote(v) else f"{k}={v}")
        return "{"+" ".join(parts)+"}" if parts else ""
    def codeblock_doc(self,attr,code):
        if self.plain:
            # Plain code block is indented? Pandoc plain code output: each line prefixed 4 spaces? Probe later; use literal lines as is indented 4
            lines=code.split("\n")
            return Literal("\n".join(("    "+line if line.strip() else "") for line in lines))
        ident,classes,kvs=attr if attr else ("",[],[])
        use_fenced=False
        if classes or ident or kvs:
            use_fenced=self.ext("fenced_code_blocks",False) or self.ext("backtick_code_blocks",False) or self.commonmark
        # If code starts with 4-space lines / has blank first etc indented code may be unsafe; then fenced even no attr if line starts with nonspace fences etc
        if not use_fenced:
            # Indented code is fine unless first line blank etc
            return Literal("\n".join(("    "+line if line.strip() else "") for line in code.split("\n")))
        # Choose fence length
        maxrun=0
        for m in re.finditer(r'`+',code): maxrun=max(maxrun,len(m.group(0)))
        fence="`"*max(3,maxrun+1)
        info=""
        if ident or len(classes)!=1 or kvs:
            if self.ext("fenced_code_attributes",False):
                parts=[]
                if ident: parts.append("#"+ident)
                for cl in classes: parts.append("."+cl)
                for k,v in kvs: parts.append(f'{k}="{v}"' if needs_quote(v) else f"{k}={v}")
                info=" {"+" ".join(parts)+"}"
            elif classes:
                info=" "+classes[0]
        elif classes:
            # one class
            if self.commonmark:
                info=" "+classes[0]
            else:
                # pandoc markdown writer uses space + class (?), despite fenced attrs
                info=" "+classes[0]
        return Literal(f"{fence}{info}\n{code}\n{fence}" if code else f"{fence}{info}\n{fence}")
    # Lists
    def bullet_list_doc(self,items):
        markers=["-"]*len(items)
        return self.list_doc(items,markers)
    def ordered_list_doc(self,c):
        lattr,items=c; start,style,delim=lattr[0],lattr[1]["t"],lattr[2]["t"]
        markers=[]
        if style=="Example" and self.ext("example_lists",False):
            markers=["(@)"]*len(items)
            return self.list_doc(items,markers)
        for idx in range(len(items)):
            n=start+idx if self.ext("startnum",True) else idx+1
            if not self.ext("fancy_lists",False) and style not in ("Decimal","DefaultStyle"):
                core=str(idx+1)
            elif style=="LowerAlpha": core=alpha(n)
            elif style=="UpperAlpha": core=alpha(n,True)
            elif style=="LowerRoman": core=roman(n)
            elif style=="UpperRoman": core=roman(n,True)
            else: core=str(n)
            if delim=="OneParen": markers.append(core+")")
            elif delim=="TwoParens": markers.append("("+core+")")
            else: markers.append(core+".")
        return self.list_doc(items,markers)
    def list_doc(self,items,markers):
        if not items: return Empty()
        # Determine loose: if any item first block is Para (not Plain) OR item has multiple blocks and not all blocks except list etc.. Simplified: loose if any block in any item is Para, or any item has >1 blocks where a blankline logically occurs (i.e. first block is Para from original tight conversion would be Plain)
        loose=False
        for item in items:
            for b in item:
                if b.get("t")=="Para": loose=True
        item_docs=[]
        marker_widths=[str_width(m) for m in markers]
        # Content column / indent: Pandoc uses marker width + spaces: for bullet, 2; for ordered, if marker width ... Examples:
        # - "- " (2), "1.  " (4), "10. " (4), "(1) " (4?) , "(@) " but example lists continuation indent 4 (four space rule)
        # Rule from Markdown writer: indent = max marker width + 2 if marker width <3? For 1./2. width2 => 4. For bullet width1 =>2? That is marker+1 not consistent. 
        # It may set spaces after marker based on a target content indent of 4 for ordered lists because ordered list marker + space must align and subcontent indented to first nonspace; for 1. (2 chars) plus two spaces = 4. For 10. (3) plus one =4. For 100. (4)+1=5. Bullet content at 2 because sublist indentation is 2 for bullet.
        # If four_space_rule extension, all indents 4.
        indents=[]
        for m,w in zip(markers,marker_widths):
            if self.ext("four_space_rule",False) or m.startswith("(@"):
                indent=4
                if w>=4: indent=w+1
            elif m in ("-","+","*"):
                indent=2
            else:
                indent=max(w+1,4) if w<4 else w+1
                # For markers with parens (1) width3 => indent 4 (1 space), (10) width4=>5
            indents.append(indent)
        for idx,item in enumerate(items):
            marker=markers[idx]; indent=indents[idx]
            spaces=" "*(indent-str_width(marker))
            inner=self.blocks_to_doc(item)
            # Use Hang: first docs marker+spaces, subsequent lines indented by spaces of indent width
            doc=Cat([Text(marker+spaces),Nest(" "*indent,inner)])
            item_docs.append(doc)
        if loose:
            return join_docs(item_docs,Blank())
        else:
            return join_docs(item_docs,Cr())
    def definition_list_doc(self,c):
        if not self.ext("definition_lists",False) and not self.plain:
            # Render as bullet-ish paragraphs (fallback)
            docs=[]
            for term,defs in c:
                docs.append(self.inlines_to_doc(term))
                for d in defs: docs.append(self.blocks_to_doc(d))
            return join_docs(docs,Blank())
        item_docs=[]
        loose_global=False
        for term,defs in c:
            for d in defs:
                if any(b.get("t")=="Para" for b in d): loose_global=True
        for term,defs in c:
            term_doc=self.inlines_to_doc(term,first=True)
            parts=[term_doc]
            if loose_global:
                # Pandoc's loose definition lists: blank line before each definition? Example in manual, if definition is Para, blank between term and definition and each def becomes Para (indented paragraph) without explicit para marker? We'll produce:
                # Term
                #
                # :   Definition
                #
                for d in defs:
                    inner=self.blocks_to_doc(d)
                    parts.append(Cat([Text(":   "),Nest("    ",inner)]))
                item_docs.append(join_docs(parts,Blank()))
            else:
                for d in defs:
                    inner=self.blocks_to_doc(d)
                    parts.append(Cat([Text(":   "),Nest("    ",inner)]))
                item_docs.append(join_docs(parts,Cr()))
        return join_docs(item_docs,Blank() if loose_global else Blank())
    # Figure/Div
    def figure_doc(self,b):
        attr,caption,blocks=b["c"]
        short,capblocks=caption
        # Simple implicit figure: one Plain with one Image
        if len(blocks)==1 and blocks[0].get("t") in ("Plain","Para") and len(blocks[0]["c"])==1 and blocks[0]["c"][0].get("t")=="Image" and self.ext("implicit_figures",False):
            img=blocks[0]["c"][0]
            # If caption differs from alt, pandoc may set alt to caption text when outputting? Figure AST caption is alt for implicit figures, image alt same. Just render image inline with alt as caption (image alt already)
            # Figure attr id needs transfer to image if link_attributes
            if attr and attr[0]:
                # clone attr add id to image attr
                ia=img["c"][0]; new_img={"t":"Image","c":[[attr[0],list(ia[1])+list(attr[1]),list(ia[2])+list(attr[2])],img["c"][1],img["c"][2]]}
                return self.inlines_to_doc([new_img],first=True)
            return self.inlines_to_doc([img],first=True)
        # Generic Figure: in Markdown writer, if raw_html enabled, output HTML figure using HTML writer? Pandoc may output image (?) For now if figcaption simple and blocks plain image handled. Else render blocks and caption as paragraph.
        docs=[]
        docs.append(self.blocks_to_doc(blocks))
        if capblocks:
            docs.append(self.blocks_to_doc(capblocks))
        return join_docs(docs,Blank())
    def div_doc(self,b):
        attr,blocks=b["c"]
        if self.plain:
            return self.blocks_to_doc(blocks)
        if self.ext("fenced_divs",False):
            ident,classes,kvs=attr
            if ident=="" and len(classes)==1 and not kvs:
                info=" "+classes[0]
            elif ident=="" and not classes and not kvs:
                return self.blocks_to_doc(blocks)
            else:
                parts=[]
                if ident: parts.append("#"+ident)
                for cl in classes: parts.append("."+cl)
                for k,v in kvs: parts.append(f'{k}="{v}"' if needs_quote(v) else f"{k}={v}")
                info=" {"+" ".join(parts)+"}"
            inner=self.blocks_to_doc(blocks)
            # fence length longer than any ::: line in inner rendered (?) simple 3
            return Cat([Text(":::"+info),Cr(),inner,Cr(),Text(":::")])
        elif self.ext("native_divs",False) and self.ext("raw_html",False):
            # HTML div tags as RawBlocks around (with blank lines)
            attrs=""
            ident,classes,kvs=attr
            if ident: attrs+=f' id="{ident}"'
            if classes: attrs+=f' class="{" ".join(classes)}"'
            for k,v in kvs: attrs+=f' {k}="{v}"'
            inner=self.blocks_to_doc(blocks)
            return Cat([Text(f"<div{attrs}>"),Blank(),inner,Blank(),Text("</div>")])
        return self.blocks_to_doc(blocks)
    # Tables
    def table_doc(self,b):
        return markdown_table_doc(self,b)
    # Inline
    def inlines_to_doc(self,inlines,first=False):
        docs=[]
        for idx,x in enumerate(inlines):
            docs.append(self.inline_to_doc(x,first=(first and idx==0)))
        return Cat(docs)
    def inline_to_doc(self,x,first=False):
        t=x.get("t"); c=x.get("c")
        if t=="Str":
            return Text(escape_markdown_str(c,self,first=first))
        if t=="Space": return BS()
        if t=="SoftBreak":
            if self.ext("hard_line_breaks",False):
                return Cat([Text("\\"),Cr()])
            return SoftBreak()
        if t=="LineBreak":
            return Cat([Text("\\"),Cr()])
        if t=="Emph":
            if self.plain: return self.inlines_to_doc(c)
            return Cat([Text("*"),self.inlines_to_doc(c),Text("*")])
        if t=="Strong":
            if self.plain: return self.inlines_to_doc(c)
            return Cat([Text("**"),self.inlines_to_doc(c),Text("**")])
        if t=="Underline":
            if self.plain: return self.inlines_to_doc(c)
            if self.ext("bracketed_spans",False):
                return Cat([Text("["),self.inlines_to_doc(c),Text("]{.underline}")])
            if self.ext("raw_html",False): return Cat([Text('<span class="underline">'),self.inlines_to_doc(c),Text("</span>")])
            return self.inlines_to_doc(c)
        if t=="Strikeout":
            if self.plain: return self.inlines_to_doc(c)
            if self.ext("strikeout",False): return Cat([Text("~~"),self.inlines_to_doc(c),Text("~~")])
            if self.ext("raw_html",False): return Cat([Text("<del>"),self.inlines_to_doc(c),Text("</del>")])
            return self.inlines_to_doc(c)
        if t=="Superscript":
            if self.plain: return Cat([Text("^"),self.inlines_to_doc(c),Text("^")]) if False else self.inlines_to_doc(c)
            if self.ext("superscript",False): return Cat([Text("^"),self.inlines_to_doc(c),Text("^")])
            if self.ext("raw_html",False): return Cat([Text("<sup>"),self.inlines_to_doc(c),Text("</sup>")])
            return self.inlines_to_doc(c)
        if t=="Subscript":
            if self.plain: return self.inlines_to_doc(c)
            if self.ext("subscript",False): return Cat([Text("~"),self.inlines_to_doc(c),Text("~")])
            if self.ext("raw_html",False): return Cat([Text("<sub>"),self.inlines_to_doc(c),Text("</sub>")])
            return self.inlines_to_doc(c)
        if t=="SmallCaps":
            if self.plain: return self.inlines_to_doc(c)
            if self.ext("bracketed_spans",False): return Cat([Text("["),self.inlines_to_doc(c),Text("]{.smallcaps}")])
            if self.ext("raw_html",False): return Cat([Text('<span class="smallcaps">'),self.inlines_to_doc(c),Text("</span>")])
            return self.inlines_to_doc(c)
        if t=="Quoted":
            if self.plain:
                if c[0]["t"]=="DoubleQuote": return Cat([Text("“"),self.inlines_to_doc(c[1]),Text("”")])
                else: return Cat([Text("‘"),self.inlines_to_doc(c[1]),Text("’")])
            if self.ext("smart",False):
                if c[0]["t"]=="DoubleQuote": return Cat([Text('"'),self.inlines_to_doc(c[1]),Text('"')])
                else: return Cat([Text("'"),self.inlines_to_doc(c[1]),Text("'")])
            else:
                if c[0]["t"]=="DoubleQuote": return Cat([Text("“"),self.inlines_to_doc(c[1]),Text("”")])
                else: return Cat([Text("‘"),self.inlines_to_doc(c[1]),Text("’")])
        if t=="Code":
            attr,txt=c
            if self.plain: return Text(txt if not (self.opts and self.opts.ascii) else to_ascii_entities(txt))
            maxrun=0
            for m in re.finditer(r'`+',txt): maxrun=max(maxrun,len(m.group(0)))
            fence="`"*(maxrun+1)
            content=txt
            if content.startswith("`") or content.endswith("`") or (content.startswith(" ") and content.endswith(" ") and content.strip()):
                content=" "+content+" "
            doc=Text(f"{fence}{content}{fence}")
            if attr and (attr[0] or attr[1] or attr[2]) and self.ext("inline_code_attributes",False):
                return Cat([doc,Text(attr_braces(attr))])
            if attr and (attr[1]) and self.commonmark and self.ext("attributes",False):
                return Cat([doc,Text(attr_braces(attr))])
            return doc
        if t=="Math":
            if self.plain:
                # plain writer renders TeX math as italic-ish plain conversion like HTML plain tex math? For early, output tex text stripped of commands simple
                return Text(plain_math(c[1]))
            if self.ext("tex_math_dollars",False) or self.ext("tex_math_gfm",False):
                if c[0]["t"]=="DisplayMath": return Text(f"$${c[1]}$$")
                return Text(f"${c[1]}$")
            if self.ext("tex_math_single_backslash",False):
                return Text((f"\\[{c[1]}\\]" if c[0]["t"]=="DisplayMath" else f"\\({c[1]}\\)"))
            if self.ext("tex_math_double_backslash",False):
                return Text((f"\\\\[{c[1]}\\\\]" if c[0]["t"]=="DisplayMath" else f"\\\\({c[1]}\\\\)"))
            # fallback: raw tex \(...\)
            return Text((f"\\[{c[1]}\\]" if c[0]["t"]=="DisplayMath" else f"\\({c[1]}\\)"))
        if t=="RawInline":
            if self.plain: return Empty()
            fmt=c[0] if isinstance(c[0],str) else c[0].get("c","")
            if fmt in ("markdown","commonmark") or fmt==self.fmt: return Text(c[1])
            if fmt in ("html","html5","html4") and self.ext("raw_html",False): return Text(c[1])
            if fmt in ("tex","latex","context") and self.ext("raw_tex",False): return Text(c[1])
            return Empty()
        if t=="Link":
            return self.link_doc(x,first=first)
        if t=="Image":
            return self.image_doc(x,first=first)
        if t=="Span":
            attr,inls=c
            if self.plain: return self.inlines_to_doc(inls)
            if not attr or (attr[0]=="" and not attr[1] and not attr[2]):
                return self.inlines_to_doc(inls)
            if self.ext("bracketed_spans",False):
                return Cat([Text("["),self.inlines_to_doc(inls),Text(f"]{attr_braces(attr)}")])
            if self.ext("native_spans",False) and self.ext("raw_html",False):
                attrs=html_attrs(attr)
                return Cat([Text(f"<span{attrs}>"),self.inlines_to_doc(inls),Text("</span>")])
            return self.inlines_to_doc(inls)
        if t=="Note":
            return self.note_doc(x)
        if t=="Cite":
            if self.plain or not self.ext("citations",False):
                return self.inlines_to_doc(c[1])
            return citation_doc(self,x)
        return Empty()
    def link_doc(self,x,first=False):
        attr,inls,target=x["c"]; url,title=target
        if self.plain:
            return self.inlines_to_doc(inls)
        # Autolink
        txt=stringify(inls)
        classes=attr[1] if attr else []
        if "uri" in classes and txt==url:
            if self.ext("autolink_bare_uris",False):
                return Text(url)
            return Text(f"<{url}>")
        if "email" in classes and url=="mailto:"+txt:
            return Text(f"<{txt}>")
        if "wikilink" in classes and (self.ext("wikilinks_title_after_pipe",False) or self.ext("wikilinks_title_before_pipe",False)):
            if txt==url:
                return Text(f"[[{url}]]")
            if self.ext("wikilinks_title_after_pipe",False):
                return Cat([Text(f"[[{url}|"),self.inlines_to_doc(inls),Text("]]")])
            else:
                return Cat([Text("[["),self.inlines_to_doc(inls),Text(f"|{url}]]")])
        text_doc=self.inlines_to_doc(inls)
        attr_s=""
        if attr and (attr[0] or attr[1] or attr[2]) and self.ext("link_attributes",False):
            # Exclude uri/email/wikilink special classes from written attrs?
            filtered=[attr[0],[c for c in attr[1] if c not in ("uri","email","wikilink")],attr[2]]
            if filtered[0] or filtered[1] or filtered[2]: attr_s=attr_braces(filtered)
        if self.opts and self.opts.reference_links:
            label=self.get_ref_label(url,title,inls)
            location=self.opts.reference_location
            # For block/section, reference definitions are in footnotes docs handling not yet; use full ref syntax
            return Cat([Text("["),text_doc,Text(f"]{attr_s}"),Text(f"[{label}]")]) if attr_s else Cat([Text("["),text_doc,Text(f"][{label}]")])
        dest=link_destination(url,title)
        return Cat([Text("["),text_doc,Text(f"]{dest}{attr_s}")])
    def image_doc(self,x,first=False):
        attr,alt,target=x["c"]; url,title=target
        if self.plain:
            alt_txt=stringify(alt).strip()
            return Text(f"[{alt_txt}]") if alt_txt else Text("[image]")
        attrs=""
        if attr and (attr[0] or attr[1] or attr[2]) and self.ext("link_attributes",False):
            attrs=attr_braces(attr)
        dest=link_destination(url,title)
        return Cat([Text("!["),self.inlines_to_doc(alt),Text(f"]{dest}{attrs}")])
    def note_doc(self,x):
        if self.plain:
            # Plain notes are footnotes same as markdown? Plain writer footnotes displayed as [^n]? Probe later. Use footnote numbers as markdown with definitions at end too.
            pass
        if self.ext("footnotes",False):
            self.footnotes.append(x["c"]); num=len(self.footnotes)
            pref=self.opts.id_prefix if self.opts else ""
            return Text(f"[^{num}]")
        if self.ext("inline_notes",False):
            # ^[content] if one Para
            blocks=x["c"]
            if len(blocks)==1 and blocks[0].get("t") in ("Para","Plain"):
                return Cat([Text("^["),self.inlines_to_doc(blocks[0]["c"]),Text("]")])
            # fallback footnotes even if ext off?
            self.footnotes.append(x["c"]); return Text(f"[^{len(self.footnotes)}]")
        return Empty()
    def footnote_defs_doc(self,notes,start=1):
        docs=[]
        for idx,blocks in enumerate(notes,start):
            inner=self.blocks_to_doc(blocks)
            docs.append(Cat([Text(f"[^{idx}]: "),Nest("    ",inner)]))
            # footnotes definitions are on new paragraph lines; first block inline follows marker, subsequent blocks indented 4 by Nest
        return join_docs(docs,Blank())
    def get_ref_label(self,url,title,inlines):
        key=(url,title)
        if key in self.ref_label_by_key: return self.ref_label_by_key[key]
        # Pandoc reference labels based on link text string or if duplicate numeric suffix. It uses a label generated from text maybe stripped punctuation.
        base=stringify(inlines).strip()
        if not base: base=url
        label=base; n=1
        # uniqueness compared case-insensitively
        while label.lower() in self.used_ref_labels:
            n+=1; label=f"{base}{n}" if False else f"{base}-{n}"  # guess
        self.used_ref_labels.add(label.lower()); self.ref_label_by_key[key]=label
        self.reference_links_list.append((label,url,title))
        return label
    def reference_defs_doc(self):
        docs=[]
        for label,url,title in self.reference_links_list:
            # Label may need bracket escaping
            line=f"[{label}]: {url_for_ref(url)}"
            if title: line+=f' "{title}"'
            docs.append(Text(line))
        return join_docs(docs,Cr())

def join_docs(docs,sep):
    docs=[d for d in docs if d!=("empty",)]
    if not docs: return Empty()
    out=docs[0]
    for d in docs[1:]: out=Cat([out,sep,d])
    return out

def needs_quote(v):
    return v=="" or any(ch.isspace() for ch in v)
def attr_braces(attr):
    ident,classes,kvs=attr; parts=[]
    if ident: parts.append("#"+ident)
    for cl in classes: parts.append("."+cl)
    for k,v in kvs: parts.append(f'{k}="{v}"' if needs_quote(v) else f"{k}={v}")
    return "{"+" ".join(parts)+"}"
def html_attrs(attr):
    ident,classes,kvs=attr; s=""
    if ident: s+=f' id="{ident}"'
    if classes: s+=f' class="{" ".join(classes)}"'
    for k,v in kvs: s+=f' {k}="{v}"'
    return s
def link_destination(url,title):
    if url=="" and not title: return "()"
    # Check spaces/control/() unbalanced
    use_angle=False
    if any(ch.isspace() for ch in url): use_angle=True
    if url and (url.count('(')!=url.count(')') or url.startswith(')') ): use_angle=True
    dest=f"<{url}>" if use_angle else url
    if title:
        if '"' not in title: dest+=f' "{title}"'
        elif "'" not in title: dest+=f" '{title}'"
        else: dest+=' "'+title.replace('"','\\"')+'"'
    return f"({dest})"
def url_for_ref(url):
    return f"<{url}>" if any(ch.isspace() for ch in url) else url

def escape_markdown_str(s,writer,first=False):
    if writer.opts and writer.opts.ascii and not writer.plain:
        # Markdown writer ascii uses html entities for non-ASCII (via toAscii)
        # But escaping below for smart sequences should apply to ascii chars. Convert first.
        s=to_ascii_entities(s)
    elif writer.opts and writer.opts.ascii and writer.plain:
        s=to_ascii_entities(s)
    out=""
    i=0
    smart=writer.ext("smart",False) and not writer.plain
    while i<len(s):
        ch=s[i]
        # smart sequences
        if smart:
            if s.startswith("---",i) or s.startswith("--",i):
                # escape first dash
                out+="\\--" if s.startswith("--",i) and not s.startswith("---",i) else "\\---"
                i+=3 if s.startswith("---",i) else 2; continue
            if s.startswith("...",i):
                out+="\\..."; i+=3; continue
            if ch=='"' :
                out+='\\"'; i+=1; continue
        if ch=='\u00a0':
            out+="\\ "; i+=1; continue
        if ch=='\\': out+="\\\\"; i+=1; continue
        if ch=='`': out+="\\`"; i+=1; continue
        if ch=='*': out+="\\*"; i+=1; continue
        if ch=='_':
            # intraword: if between alnum and ext, no escape
            before=s[i-1] if i>0 else ""; after=s[i+1] if i+1<len(s) else ""
            if writer.ext("intraword_underscores",True) and before.isalnum() and after.isalnum():
                out+="_"
            else: out+="\\_"
            i+=1; continue
        if ch in '[]': out+="\\"+ch; i+=1; continue
        if ch=='<' :
            after=s[i+1] if i+1<len(s) else ""
            if after.isalpha() or after in '/!?' or re.match(r'[A-Za-z][A-Za-z0-9+.-]*:',s[i+1:]):
                out+="\\<"
            else: out+="<"
            i+=1; continue
        if ch=='!' and i+1<len(s) and s[i+1]=='[': out+="\\!"; i+=1; continue
        if ch=='$' and writer.ext("tex_math_dollars",False): out+="\\$"; i+=1; continue
        if ch=='~' and (writer.ext("subscript",False) or writer.ext("strikeout",False)): out+="\\~"; i+=1; continue
        if ch=='^' and writer.ext("superscript",False): out+="\\^"; i+=1; continue
        if ch=='|' and getattr(writer,'in_table',False) and writer.ext("pipe_tables",False): out+="\\|"; i+=1; continue
        if first and i==0:
            if ch=='#': out+="\\#"; i+=1; continue
            if ch=='>': out+="\\>"; i+=1; continue
            if ch in '-+' and (i+1>=len(s) or s[i+1].isspace()):
                out+="\\"+ch; i+=1; continue
            # ordered list at start of first token? Pandoc escapes . or ) after digits in first token; token may be "1."
            m=re.match(r'(\d+)([.)])',s[i:])
            if m:
                out+=m.group(1)+"\\"+m.group(2); i+=len(m.group(0)); continue
        out+=ch; i+=1
    return out

def plain_math(tex):
    # Strip braces/commands very simply for plain writer
    s=re.sub(r'\\frac\{([^{}]*)\}\{([^{}]*)\}',r'\1/\2',tex)
    s=re.sub(r'\\([A-Za-z]+)',lambda m: {'alpha':'α','beta':'β'}.get(m.group(1),m.group(1)),s)
    return s.replace('{','').replace('}','')

def citation_doc(writer,x):
    cites,disp=x["c"]
    # If only AuthorInText
    docs=[]
    # Pandoc's markdown writer for a Cite uses writeCite which may place all citations in brackets except AuthorInText ones. Implementation based on modes:
    # Iterate: maintain bracket group for Normal/Suppress.
    i=0
    while i<len(cites):
        cit=cites[i]; mode=cit.get("citationMode",{}).get("t")
        if mode=="AuthorInText":
            if docs: docs.append(BS())
            docs.append(Text("@"+cit.get("citationId","")))
            if cit.get("citationSuffix"):
                docs.append(BS()); docs.append(Text("[")); docs.append(writer.inlines_to_doc(cit["citationSuffix"])); docs.append(Text("]"))
            i+=1
        else:
            # collect consecutive normal/suppress
            group=[]
            while i<len(cites) and cites[i].get("citationMode",{}).get("t")!="AuthorInText":
                group.append(cites[i]); i+=1
            if docs: docs.append(BS())
            parts=[]
            for cit in group:
                seg=[]
                if cit.get("citationPrefix"):
                    seg.append(writer.inlines_to_doc(cit["citationPrefix"])); seg.append(BS())
                if cit.get("citationMode",{}).get("t")=="SuppressAuthor": seg.append(Text("-"))
                seg.append(Text("@"+cit.get("citationId","")))
                if cit.get("citationSuffix"):
                    # suffix begins with comma etc (its first token) - no space before if starts punctuation? inlines include Str "," etc; writer may add suffix as parsed. Just append suffix inlines (they include spaces nodes for , p. 5 suffix from parser? Our parse suffix after key: [Str ',', Space, Str 'p. 5'])
                    seg.append(writer.inlines_to_doc(cit["citationSuffix"]))
                parts.append(Cat(seg))
            groupdoc=parts[0]
            for p in parts[1:]: groupdoc=Cat([groupdoc,Text(";"),BS(),p])
            docs.append(Cat([Text("["),groupdoc,Text("]")]))
    return Cat(docs)

def meta_plain(mv):
    t=mv.get("t"); c=mv.get("c")
    if t=="MetaString": return c
    if t=="MetaBool": return "true" if c else "false"
    if t in ("MetaInlines","MetaBlocks"): return stringify(c).strip()
    if t=="MetaList": return ", ".join(meta_plain(x) for x in c)
    if t=="MetaMap": return "; ".join(f"{k}: {meta_plain(v)}" for k,v in c.items())
    return stringify(mv)

def meta_to_yaml(meta,writer):
    # YAML for standalone markdown titleblock: values rendered by converting MetaInlines with markdown writer partial? Pandoc uses a YAML encoding where each metavalue converts to YAML string via markdown rendering without formatting? Observed: title with *emph* in standalone markdown output likely 'title: *Emph* title' or quoted... We'll implement by rendering MetaInlines blocks using a copy writer-ish stringify formatted with markdown inline rendering.
    if not meta: return ""
    lines=["---"]
    for k in sorted(meta.keys()):
        lines.extend(yaml_lines(k,meta[k],writer,indent=0))
    lines.append("---")
    return "\n".join(lines)

def yaml_lines(key,mv,writer,indent=0):
    pad=" "*indent
    t=mv.get("t"); c=mv.get("c")
    if t=="MetaList":
        lines=[f"{pad}{key}:"]
        for item in c:
            sv=yaml_scalar(item,writer)
            if item.get("t") in ("MetaMap","MetaList"):
                # complex nested in list - simplified indentation
                sub=yaml_lines("-",item,writer,indent+2)
                lines.extend(sub)
            else:
                lines.append(f"{pad}- {sv}")
        return lines
    if t=="MetaMap":
        lines=[f"{pad}{key}:"]
        for kk in sorted(c.keys()): lines.extend(yaml_lines(kk,c[kk],writer,indent+2))
        return lines
    sv=yaml_scalar(mv,writer)
    if "\n" in sv.strip("\n"):
        lines=[f"{pad}{key}: |"]
        for line in sv.strip().split("\n"): lines.append(f"{pad}  {line}")
        return lines
    return [f"{pad}{key}: {sv}"]

def yaml_scalar(mv,writer):
    t=mv.get("t"); c=mv.get("c")
    if t=="MetaBool": return "true" if c else "false"
    if t=="MetaString":
        return yaml_quote(c)
    if t=="MetaInlines":
        s=render(writer.inlines_to_doc(c),columns=100000,wrap="none")
        return yaml_quote(s)
    if t=="MetaBlocks":
        s=render(writer.blocks_to_doc(c),columns=100000,wrap="none").rstrip("\n")
        return s
    return yaml_quote(meta_plain(mv))

def yaml_quote(s):
    if s=="": return "''"
    # Quote if contains special YAML chars leading/trailing spaces, : # * etc
    if re.search(r'[:#\[\]{}&*!|>%@`,"\']',s) or s.strip()!=s or s.lower() in ("true","false","null","yes","no") or re.fullmatch(r'-?\d+(\.\d+)?',s):
        # Use single quotes doubling '
        return "'"+s.replace("'","''")+"'"
    return s

# Table rendering for markdown
def markdown_table_doc(writer,b):
    # Imported by method to keep in same file below
    return render_markdown_table(writer,b)

def cell_text(writer,blocks):
    # Return rendered cells as list of lines for simple/pipe/grid
    # For simple/pipe, single Plain/Para rendered inline; for grid, blocks rendered markdown as lines
    if len(blocks)==1 and blocks[0].get("t") in ("Plain","Para"):
        old=writer.in_table; writer.in_table=True
        s=render(writer.inlines_to_doc(blocks[0]["c"]),columns=100000,wrap="none")
        writer.in_table=old
        return [s]
    s=render(writer.blocks_to_doc(blocks),columns=100000,wrap="none").rstrip("\n")
    return s.split("\n") if s else [""]

def render_markdown_table(writer,b):
    attr,caption,specs,head,bodies,foot=b["c"]
    # Gather rows
    header_rows=head[1]
    body_rows=[]
    for battr,rhc,inter,rows in bodies:
        body_rows.extend(inter); body_rows.extend(rows)
    foot_rows=foot[1]
    all_rows=header_rows+body_rows+foot_rows
    # GFM / pipe preference
    can_pipe=all(len(cell[4])<=1 and (not cell[4] or cell[4][0].get("t") in ("Plain","Para")) for row in all_rows for cell in row[1]) and header_rows
    # Determine choice
    # For commonmark/gfm: pipe if ext pipe_tables, else HTML fallback if raw_html ( handled by HTML writer in main? In markdown writer commonmark, table as raw HTML generated by html writer. We'll defer to HTML string conversion when needed.)
    if writer.commonmark:
        if writer.ext("pipe_tables",False) and can_pipe:
            return pipe_table_doc(writer,b,header_rows,body_rows,specs,caption,attr)
        else:
            # HTML table fallback
            from .html import HtmlWriter
            hw=HtmlWriter(writer.opts,writer.exts,"html5")
            s,_=hw.write({"meta":{},"blocks":[b]})
            return Literal(s.rstrip("\n"))
    if writer.plain:
        # plain writer simple table if possible else render rows as text?
        return simple_table_doc(writer,b,header_rows,body_rows,specs,caption,attr,plain=True)
    # Pandoc markdown choice: if simple_tables enabled and cells single line and doesn't require pipe for alignment? Use simple if:
    # - all cells are single line Plain and total widths fit within columns and no ColWidth explicit (or widths small)
    # - header absent or present.
    # If multiline cell text (contains SoftBreak or blocks) -- multiline tables if enabled
    # If cells contain block elements -> grid.
    has_block_cells=any(len(cell[4])>1 or (cell[4] and cell[4][0].get("t") not in ("Plain","Para")) for row in all_rows for cell in row[1])
    if has_block_cells and writer.ext("grid_tables",False):
        return grid_table_doc(writer,b,header_rows,body_rows,specs,caption,attr)
    if can_pipe:
        # Check if a simple table can represent alignments and widths: Pandoc uses simple tables when cell widths are not too wide and no column widths specified (?) For pipe table input, if alignment is AlignRight etc, simple can represent.
        # If table source has explicit ColWidths, multiline (?) use grid/multiline based.
        if writer.ext("simple_tables",False):
            # if total estimated width <= columns
            return simple_table_doc(writer,b,header_rows,body_rows,specs,caption,attr)
        if writer.ext("pipe_tables",False):
            return pipe_table_doc(writer,b,header_rows,body_rows,specs,caption,attr)
    if writer.ext("grid_tables",False):
        return grid_table_doc(writer,b,header_rows,body_rows,specs,caption,attr)
    # fallback: render each row as para lines
    rows=[]
    for row in all_rows:
        rows.append(Text(" ".join(cell_text(writer,cell[4])[0] for cell in row[1])))
    return join_docs(rows,Cr())

def caption_doc_md(writer,caption,attr):
    short,blocks=caption
    if not blocks and not short: return None
    if blocks and len(blocks)==1 and blocks[0].get("t") in ("Plain","Para"):
        txt=render(writer.inlines_to_doc(blocks[0]["c"]),columns=100000,wrap="none")
    elif short:
        txt=render(writer.inlines_to_doc(short),columns=100000,wrap="none")
    else:
        txt=render(writer.blocks_to_doc(blocks),columns=100000,wrap="none").strip()
    suffix=""
    if attr and (attr[0] or attr[1] or attr[2]) and writer.ext("table_attributes",False):
        suffix=" "+attr_braces(attr)
    return f": {txt}{suffix}" if False else txt, suffix  # callers format

def pipe_table_doc(writer,b,header_rows,body_rows,specs,caption,attr):
    # Only first header row used as pipe header (assume one)
    rows_text=[]
    header=[cell_text(writer,cell[4])[0] for cell in header_rows[0][1]] if header_rows else []
    body=[[cell_text(writer,cell[4])[0] for cell in row[1]] for row in body_rows]
    ncol=len(header)
    widths=[]
    for idx in range(ncol):
        widths.append(max(3,str_width(header[idx]),*(str_width(r[idx]) for r in body)) if body else max(3,str_width(header[idx])))
    def fmt_row(cells):
        return "| "+" | ".join( cells[i].ljust(widths[i]) for i in range(ncol))+" |"
    aligns=[spec[0]["t"] for spec in specs]
    delim=[]
    for idx,a in enumerate(aligns):
        if a=="AlignLeft": delim.append(":"+"-"*(widths[idx]-1))
        elif a=="AlignRight": delim.append("-"*(widths[idx]-1)+":")
        elif a=="AlignCenter": delim.append(":"+"-"*(widths[idx]-2)+":")
        else: delim.append("-"*widths[idx])
    lines=[fmt_row(header),fmt_row(delim)]+[fmt_row(r) for r in body]
    # GFM delimiter row in earlier had widths 5 for 1-char cells because width calc considered min 5? fmt gives 3. Original GFM output: "| A   | B   |\n|-----|-----|" cells padded to 3? Let's count: A plus 3 spaces = total cell width 5 inc spaces around? Their row: "| A   |" within pipes = space + A + 3 spaces =5 width field. Delimiter ----- =5. Our fmt: "| A |" width field = A padded to 3 -> "| A   |"? We join with " | " separators: leading "| " + A.ljust3 + " | " -> A +2 spaces from padding + separator preceding space = visual 3 trailing. Delimiter cells padded3.
    # GFM original delimiter ----- (5) suggests their min cell width in delimiter and header text width is calculated including spaces plus maybe 3 dashes minimum from source? CommonMark writer uses width at least 5? We'll test later compare.
    cap=caption_doc_md(writer,caption,attr)
    if cap:
        txt,suffix=cap; lines.append(""); lines.append(f": {txt}{suffix}")
    return Literal("\n".join(lines))

def simple_table_doc(writer,b,header_rows,body_rows,specs,caption,attr,plain=False):
    rows=[]
    header=[]
    if header_rows:
        header=[cell_text(writer,cell[4])[0] for cell in header_rows[0][1]]
    body=[[cell_text(writer,cell[4])[0] for cell in row[1]] for row in body_rows]
    ncol = len(header) if header else (len(body[0]) if body else len(specs))
    # Compute column widths based content max width
    widths=[]
    for idx in range(ncol):
        vals=[]
        if header: vals.append(header[idx])
        vals.extend(r[idx] for r in body)
        widths.append(max((str_width(v) for v in vals),default=0))
    aligns=[spec[0]["t"] for spec in specs]
    # If alignments from spec are default and table was from simple input, writer preserves those? In AST specs contains alignments derived from header positions; simple output should reproduce positions.
    # Determine each column dash width and text positioning:
    # Pandoc simple table output seen: two leading spaces before table, each column separated by a space? Example "  A   B\n  --- ---\n  1   2\n" 
    # Columns widths in that example =3 each (dash length) even though content width1. Why 3? Minimum dash width maybe 3? Header A is left-aligned within 3.
    dash_widths=[max(3,w) for w in widths]
    def format_cell(txt,idx):
        a=aligns[idx] if idx<len(aligns) else "AlignDefault"; w=dash_widths[idx]
        if a=="AlignRight": return txt.rjust(w)
        if a=="AlignCenter":
            # center in width: left pad floor
            total=w-str_width(txt); left=total//2; return " "*left+txt+" "*(total-left)
        return txt.ljust(w)
    def format_row(cells):
        # join by a single space and rstrip
        return ("  "+" ".join(format_cell(cells[i] if i<len(cells) else "",i) for i in range(ncol))).rstrip()
    delim="  "+" ".join("-"*w for w in dash_widths)
    lines=[]
    cap=caption_doc_md(writer,caption,attr)
    # Simple table caption placement in markdown writer: caption is before or after depending normal Pandoc output table caption position? Captions from writer are usually after table with ": Caption" preceded by blank? Observed simple table output from generator might put "Table: caption" after if caption. We'll do after blank with ":"
    if header:
        lines.append(format_row(header)); lines.append(delim)
    else:
        lines.append(delim)
    for r in body: lines.append(format_row(r))
