    # Skylighting LaTeX escaping: commands for specials - see generated: ' -> \textquotesingle{} , etc.
    reps={'\\':r'\textbackslash{}','{':r'\{','}':r'\}','$':r'\$','&':r'\&','%':r'\%','#':r'\#','_':r'\_','^':r'\textasciicircum{}','~':r'\textasciitilde{}','<':r'\textless{}','>':r'\textgreater{}','|':r'\textbar{}',"'":r'\textquotesingle{}','"':r'\textquotedbl{}','`':r'\textasciigrave{}'}
