    if method=="biblatex":
        docs=[]
        for cit in cites:
            mode=cit.get("citationMode",{}).get("t")
            cmd="textcite" if mode=="AuthorInText" else "parencite"
            docs.append(Text(f"\\{cmd}{{{cit.get('citationId','')}}}"))
