def parse_json_doc(text, source_name=""):
    # Aeson decode errors simplified
    stripped=text.strip()
    if stripped=="":
        raise PandocError("JSON parse error: Unexpected end-of-input, expecting JSON value\n",64)
    # json decoder with raw_decode to detect trailing garbage
    dec=json.JSONDecoder()
    try:
        obj,end=dec.raw_decode(text,0)
        # raw_decode doesn't skip leading ws at idx0? It does? Python raw_decode expects value at idx and s[idx] maybe leading spaces returns? Let's handle manually
    except Exception as e:
        # If text starts with whitespace, retry with loads
        try:
            obj=json.loads(text); end=len(text)
            _validate(obj); return {"meta":obj.get("meta",{}),"blocks":obj.get("blocks",[])}
        except PandocError:
            raise
        except Exception:
            # Produce pandoc-like for first token
            preview=text
            # Aeson error shows remainder (?) For 'not json...' it shows whole string escaped
            esc=preview.replace('\\','\\\\').replace('"','\\"').replace('\n','\\n')
            raise PandocError(f'JSON parse error: Unexpected "{esc}", expecting JSON value\n',64)
    # check trailing non-whitespace
    rest=text[end:] if isinstance(end,int) else ""
    if rest.strip()!="":
        raise PandocError("JSON parse error: Trailing garbage\n",64)
    _validate(obj)
    return {"meta":obj.get("meta",{}),"blocks":obj.get("blocks",[])}
def _validate(obj):
    if not isinstance(obj,dict):
