VOID_TAGS={"area","base","br","col","embed","hr","img","input","link","meta","param","source","track","wbr"}
BLOCK_TAGS={"address","article","aside","blockquote","details","div","dl","fieldset","figcaption","figure","footer","form","header","hr","li","main","nav","ol","p","pre","section","summary","table","ul","h1","h2","h3","h4","h5","h6"}
class Node:
    def __init__(self,tag,attrs=None):
        self.tag=tag; self.attrs=attrs or {}; self.children=[]  # Node or str
    def text_content(self):
        out=""
        for c in self.children:
            if isinstance(c,str): out+=c
            else: out+=c.text_content()
        return out
class DomParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root=Node("#root"); self.stack=[self.root]
    def handle_starttag(self,tag,attrs):
        # Implied close for p/li/tr/td etc simple
        if tag in ("p","li","tr","td","th","dt","dd","option"):
            # close same tag if top is same or p inside li etc - simple pop if current tag is p and new is block
            if self.stack[-1].tag==tag: self.stack.pop()
            if tag!="p" and self.stack[-1].tag=="p": self.stack.pop()
        node=Node(tag,dict(attrs)); self.stack[-1].children.append(node)
        if tag not in VOID_TAGS:
            self.stack.append(node)
    def handle_startendtag(self,tag,attrs):
        node=Node(tag,dict(attrs)); self.stack[-1].children.append(node)
    def handle_endtag(self,tag):
        for idx in range(len(self.stack)-1,0,-1):
            if self.stack[idx].tag==tag:
                del self.stack[idx:]; break
    def handle_data(self,data):
        self.stack[-1].children.append(data)
    def handle_comment(self,data):
        node=Node("!comment"); node.children.append(data); self.stack[-1].children.append(node)

class HtmlContext:
    def __init__(self,exts,opts):
        self.exts=exts or {}; self.opts=opts; self.used_ids=set(); self.meta={}; self.footnotes={} 
    def ext(self,n,d=False): return self.exts.get(n,d)

def parse_html(text,opts,exts,fmt="html",source_name="",log=None):
    ctx=HtmlContext(exts,opts)
    parser=DomParser(); parser.feed(text)
    root=parser.root
    # Extract metadata from head/title/meta?
    # Pandoc HTML reader: <title> in head goes to metadata "title"? If standalone full HTML with head title and body, converting to markdown does not include title as H? Metadata title may be set. Probe via expected later; implement title/author/date metas from meta tags.
    body=find_first(root,"body") or root
    head=find_first(root,"head")
    if head is not None:
        extract_head_meta(head,ctx)
    blocks=blocks_from_children(body.children if body is not root else [c for c in root.children if not (isinstance(c,Node) and c.tag in ("head",))],ctx)
    # If root contains html element wrapping, body find handles. If fragment root children includes html node but no body, process html children.
    if body is root:
        htmlnode=find_first(root,"html")
        if htmlnode is not None:
            blocks=blocks_from_children([c for c in htmlnode.children if not (isinstance(c,Node) and c.tag=="head")],ctx)
    # Footnotes sections at end conversion: handled in blocks conversion for links if note refs and section footnotes exists - postprocess simplified: Find sections with class footnotes in DOM and transform notes (TODO later)
    return {"meta":ctx.meta,"blocks":blocks},ctx

def find_first(node,tag):
    if isinstance(node,Node):
        if node.tag==tag: return node
        for c in node.children:
            r=find_first(c,tag)
            if r: return r
    return None

def extract_head_meta(head,ctx):
    for ch in flatten_nodes(head):
        if ch.tag=="title":
            txt=ch.text_content().strip()
            if txt: ctx.meta["title"]={"t":"MetaInlines","c":str_to_inlines(txt)}
        if ch.tag=="meta":
            name=ch.attrs.get("name","").lower(); content=ch.attrs.get("content","")
            if name=="author":
                # append to author list
                author={"t":"MetaInlines","c":str_to_inlines(content)}
                if "author" in ctx.meta:
                    old=ctx.meta["author"]
                    if old.get("t")=="MetaList": old["c"].append(author)
                    else: ctx.meta["author"]={"t":"MetaList","c":[old,author]}
                else: ctx.meta["author"]={"t":"MetaList","c":[author]}
            elif name in ("description",):
                ctx.meta["description"]={"t":"MetaInlines","c":str_to_inlines(content)}
            elif name=="keywords":
                ctx.meta["keywords"]={"t":"MetaList","c":[{"t":"MetaInlines","c":str_to_inlines(x.strip())} for x in content.split(",")]}
            elif name=="dcterms.date":
                ctx.meta["date"]={"t":"MetaInlines","c":str_to_inlines(content)}

def flatten_nodes(node):
    out=[]
    for c in node.children:
        if isinstance(c,Node): out.append(c); out.extend(flatten_nodes(c))
    return out

def str_to_inlines(s):
    # split words/spaces
    out=[]; parts=re.split(r'(\s+)',s)
    for p in parts:
        if not p: continue
        if p.isspace(): out.append(I("Space"))
        else: out.append(I("Str",p))
    while out and out[0]["t"]=="Space": out.pop(0)
    while out and out[-1]["t"]=="Space": out.pop()
    return out

def node_attr(node,ctx):
    ident=node.attrs.get("id",""); classes=node.attrs.get("class","").split() if node.attrs.get("class") else []; kvs=[]
    for k,v in node.attrs.items():
        if k in ("id","class"): continue
        kvs.append([k,v if v is not None else ""])
    return [ident,classes,kvs]

def is_block_node(n):
    return isinstance(n,Node) and n.tag in BLOCK_TAGS or (isinstance(n,Node) and n.tag in ("pre","figure","figcaption","table","thead","tbody","tfoot","tr","td","th","caption","colgroup","dt","dd","hr"))

def blocks_from_children(children,ctx):
    blocks=[]; inline_buf=[]
    def flush_inline():
        nonlocal inline_buf
        if inline_buf:
            inls=[]
            for n in inline_buf: inls.extend(inlines_from_node(n,ctx))
            inls=trim_inlines(inls)
            if inls: blocks.append(B("Para",inls))
            inline_buf=[]
    for child in children:
        if isinstance(child,str):
            if child.strip()=="" and not inline_buf:
                continue
            inline_buf.append(child); continue
        if child.tag in ("script","style","head","meta","link","title"):
            continue
        if child.tag=="!comment":
            continue
        if is_block_node(child):
            flush_inline(); blocks.extend(blocks_from_node(child,ctx))
        else:
            inline_buf.append(child)
    flush_inline()
    # Remove empty paras if ext empty_paragraphs off
    if not ctx.ext("empty_paragraphs",False):
        blocks=[b for b in blocks if not (b.get("t")=="Para" and not b.get("c"))]
    return blocks

def blocks_from_node(node,ctx):
    tag=node.tag
    if tag in ("h1","h2","h3","h4","h5","h6"):
        level=int(tag[1]); inls=inlines_from_children(node.children,ctx); attr=node_attr(node,ctx)
        # Classes etc kvs: HTML attrs other than id/class become kvs (but style/data? Pandoc attr conversion: data- keys lose prefix? For writer generated headings, data-number attr becomes kv ("data-number"?) But in HTML reader, attributes are captured in attr with keys as is except maybe style dropped. Use node_attr.
        if not attr[0] and ctx.ext("auto_identifiers",False):
            attr[0]=auto_identifier(inls,ctx.exts,ctx.used_ids,fallback_section=True)
        else:
            if attr[0]: ctx.used_ids.add(attr[0])
        return [B("Header",[level,attr,trim_inlines(inls)])]
    if tag=="p":
        inls=trim_inlines(inlines_from_children(node.children,ctx))
        # If para contains only an image and figure conversion? HTML reader implicit figures? Figure handled from figure tags. A p with img only remains Para (not Figure) in HTML reader I think.
        return [B("Para",inls)]
    if tag=="pre":
        # code inside maybe <code class=...>
        code_node=find_first(node,"code")
        txt=(code_node.text_content() if code_node is not None else node.text_content())
        # Pandoc sourceCode div structure is handled in div; standalone pre code's text ends without final newline? If txt ends newline strip one.
        if txt.endswith("\n"): txt=txt[:-1]
        attr=empty_attr()
        if code_node is not None:
            classes=code_node.attrs.get("class","").split()
            # In pandoc HTML (sourceCode) the pre/code classes are "sourceCode lang"; reader extracts lang as class other than sourceCode and numberLines etc.
            classes=[c for c in classes if c!="sourceCode"]
            if classes or code_node.attrs.get("id"): attr=[code_node.attrs.get("id",""),classes,[]]
        else:
            classes=node.attrs.get("class","").split(); attr=[node.attrs.get("id",""),classes,[]]
        return [B("CodeBlock",[attr,txt])]
    if tag=="blockquote":
        return [B("BlockQuote",blocks_from_children(node.children,ctx))]
    if tag in ("ul","ol"):
        return [list_from_node(node,ctx)]
    if tag=="dl":
        return [definition_list_from_node(node,ctx)]
    if tag=="hr": return [B0("HorizontalRule")]
    if tag=="table": return [table_from_node(node,ctx)]
    if tag=="figure": return figure_from_node(node,ctx)
    if tag in ("div","section","article","header","footer","main","nav","aside","fieldset","details","summary","form","address"):
        # Pandoc generated sourceCode div
        classes=node.attrs.get("class","").split()
        if "sourceCode" in classes:
            pre=find_first(node,"pre")
            if pre is not None:
                cb=blocks_from_node(pre,ctx)
                # Pandoc div id is code block id
                if cb and node.attrs.get("id"): cb[0]["c"][0][0]=node.attrs.get("id")
                return cb
        if "line-block" in classes and ctx.ext("line_blocks",False):
            lines=[]
            for ch in node.children:
                if isinstance(ch,Node) and ch.tag=="div" and "line" in ch.attrs.get("class","").split():
                    # br only indicates empty line
                    if ch.text_content().strip()=="" and find_first(ch,"br") is not None: lines.append([])
                    else: lines.append(trim_inlines(inlines_from_children(ch.children,ctx)))
            return [B("LineBlock",lines)]
        if tag=="section" and "footnotes" in classes:
            # Convert footnote section to definitions map and return no blocks; links already parsed earlier would need notes. Our order: footnote section appears at end, but inline footnote refs in earlier blocks were converted as links. Postprocess would be needed at doc level. For now extract to ctx.footnotes and return [] (TODO improve via parse_html post walk)
            extract_footnotes_section(node,ctx); return []
        inner=blocks_from_children(node.children,ctx)
        attr=node_attr(node,ctx)
        if ctx.ext("native_divs",False):
            # HTML writer generated section-divs have class section... reader maps div/section to Div if native_divs or if it has attributes? Without attr, still Div? For a plain div with no attr, pandoc returns Div with empty attr ( earlier native got Div). If section has classes section level* from pandoc section-divs, reader reconstructs Header hierarchy instead of Div: inside first child heading etc and section attrs become header attr. Implementing that is complex; keep Div.
            return [B("Div",[attr,inner])]
        return inner
    if tag=="figcaption":
        inls=trim_inlines(inlines_from_children(node.children,ctx)); return [B("Para",inls)]
    # other containers transparent
    return blocks_from_children(node.children,ctx)

def list_from_node(node,ctx):
    items=[]
    for li in node.children:
        if not isinstance(li,Node) or li.tag!="li": continue
        blocks=blocks_from_children(li.children,ctx)
        # Convert Para to Plain if item is a single para and original list was tight? HTML does not encode tightness except p tags: an li content with direct text -> blocks_from_children creates Para for inline text. In pandoc HTML reader, list items without <p> become Plain; our blocks_from_children can't distinguish. Check if li children contain a p node: if no block-level p, convert first/only Para to Plain.
        has_p=any(isinstance(ch,Node) and ch.tag=="p" for ch in li.children)
        if not has_p:
            blocks=[B("Plain",b["c"]) if b.get("t")=="Para" else b for b in blocks]
        items.append(blocks)
    if node.tag=="ul":
        # task list check: ul class task-list or li contains checkbox input
        return B("BulletList",items)
    start=int(node.attrs.get("start",1)) if str(node.attrs.get("start",1)).isdigit() else 1
    typ=node.attrs.get("type","1")
    style={"1":"Decimal","a":"LowerAlpha","A":"UpperAlpha","i":"LowerRoman","I":"UpperRoman"}.get(typ,"Decimal")
    return B("OrderedList",[[start,{"t":style},{"t":"Period"}],items])

def definition_list_from_node(node,ctx):
    items=[]; term=None; defs=[]
    for ch in node.children:
        if not isinstance(ch,Node): continue
        if ch.tag=="dt":
            if term is not None: items.append([term,defs])
            term=trim_inlines(inlines_from_children(ch.children,ctx)); defs=[]
        elif ch.tag=="dd":
            blocks=blocks_from_children(ch.children,ctx)
            # dd without p becomes Plain
            if not any(isinstance(c,Node) and c.tag=="p" for c in ch.children): blocks=[B("Plain",b["c"]) if b.get("t")=="Para" else b for b in blocks]
            defs.append(blocks)
    if term is not None: items.append([term,defs])
    return B("DefinitionList",items)

def figure_from_node(node,ctx):
    attr=node_attr(node,ctx); caption=None; blocks=[]
    for ch in node.children:
        if isinstance(ch,Node) and ch.tag=="figcaption":
            caption=trim_inlines(inlines_from_children(ch.children,ctx))
        elif isinstance(ch,Node):
            if is_block_node(ch): blocks.extend(blocks_from_node(ch,ctx))
            else:
                inls=inlines_from_node(ch,ctx)
                if inls: blocks.append(B("Plain",trim_inlines(inls)))
        elif isinstance(ch,str) and ch.strip():
            blocks.append(B("Plain",str_to_inlines(ch.strip())))
    cap=[None,[B("Plain",caption)] if caption else []]
    return [B("Figure",[attr,cap,blocks])]

def table_from_node(node,ctx):
    attr=node_attr(node,ctx)
    caption=[None,[]]; specs=[]; head_rows=[]; body_rows=[]; foot_rows=[]
    # colgroup widths
    for ch in node.children:
        if not isinstance(ch,Node): continue
        if ch.tag=="caption":
            caption=[None,[B("Plain",trim_inlines(inlines_from_children(ch.children,ctx)))]]
        elif ch.tag=="colgroup":
            for col in ch.children:
                if isinstance(col,Node):
                    style=col.attrs.get("style",""); m=re.search(r'width:\s*(\d+(?:\.\d+)?)%',style)
                    specs.append([{"t":"AlignDefault"},{"t":"ColWidth","c":float(m.group(1))/100} if m else {"t":"ColWidthDefault"}])
        elif ch.tag=="thead": head_rows=[row_from_node(r,ctx) for r in ch.children if isinstance(r,Node) and r.tag=="tr"]
        elif ch.tag=="tbody": body_rows.extend(row_from_node(r,ctx) for r in ch.children if isinstance(r,Node) and r.tag=="tr")
        elif ch.tag=="tfoot": foot_rows=[row_from_node(r,ctx) for r in ch.children if isinstance(r,Node) and r.tag=="tr"]
        elif ch.tag=="tr": body_rows.append(row_from_node(ch,ctx))
    ncol=max((len(r[1]) for r in head_rows+body_rows+foot_rows),default=0)
    while len(specs)<ncol: specs.append([{"t":"AlignDefault"},{"t":"ColWidthDefault"}])
    head=[empty_attr(),head_rows]; bodies=[[empty_attr(),0,[],body_rows]]; foot=[empty_attr(),foot_rows]
    return B("Table",[attr,caption,specs,head,bodies,foot])

def row_from_node(rownode,ctx):
    cells=[]
    for cell in rownode.children:
        if not isinstance(cell,Node) or cell.tag not in ("td","th"): continue
        blocks=blocks_from_children(cell.children,ctx)
        if len(blocks)==1 and blocks[0].get("t")=="Para": blocks=[B("Plain",blocks[0]["c"])]
        align="AlignDefault"
        style=cell.attrs.get("style","")
        if "text-align: left" in style: align="AlignLeft"
        elif "text-align: right" in style: align="AlignRight"
        elif "text-align: center" in style: align="AlignCenter"
        rs=int(cell.attrs.get("rowspan",1)) if str(cell.attrs.get("rowspan",1)).isdigit() else 1
        cs=int(cell.attrs.get("colspan",1)) if str(cell.attrs.get("colspan",1)).isdigit() else 1
        cells.append([node_attr(cell,ctx),{"t":align},rs,cs,blocks])
    return [node_attr(rownode,ctx),cells]

def extract_footnotes_section(node,ctx):
    ol=find_first(node,"ol")
    if ol is None: return
    for li in ol.children:
        if isinstance(li,Node) and li.tag=="li":
            fid=li.attrs.get("id",""); blocks=blocks_from_children(li.children,ctx)
            # Remove footnote backref links at end of last para
            ctx.footnotes[fid]=blocks

def inlines_from_children(children,ctx):
    out=[]
    for ch in children: out.extend(inlines_from_node(ch,ctx))
    return normalize_html_inlines(out)

def inlines_from_node(node,ctx):
    if isinstance(node,str): return text_from_html(node)
    tag=node.tag
    if tag in ("script","style"): return []
    if tag=="!comment": return []
    if tag=="br": return [I("LineBreak")]
    if tag in ("em","i"): return [I("Emph",trim_inlines(inlines_from_children(node.children,ctx),False,False))] if False else [ {"t":"Emph","c":inlines_from_children(node.children,ctx)}]
    if tag in ("strong","b"): return [{"t":"Strong","c":inlines_from_children(node.children,ctx)}]
    if tag in ("del","s","strike"): return [{"t":"Strikeout","c":inlines_from_children(node.children,ctx)}]
    if tag=="u": return [{"t":"Underline","c":inlines_from_children(node.children,ctx)}]
    if tag=="sup": return [{"t":"Superscript","c":inlines_from_children(node.children,ctx)}]
    if tag=="sub": return [{"t":"Subscript","c":inlines_from_children(node.children,ctx)}]
    if tag=="small": return inlines_from_children(node.children,ctx)
    if tag=="q": return [{"t":"Quoted","c":[{"t":"DoubleQuote"},inlines_from_children(node.children,ctx)]}]
    if tag=="code":
        attr=[node.attrs.get("id",""),node.attrs.get("class","").split(),[]]
        return [{"t":"Code","c":[attr,node.text_content()]}]
    if tag=="a":
        href=node.attrs.get("href",""); title=node.attrs.get("title","")
        attr=node_attr(node,ctx)
        # filter kvs: remove href/title from node_attr (it excludes id/class only, so href/title are kept in kvs! Need recalc)
        attr=[node.attrs.get("id",""),node.attrs.get("class","").split() if node.attrs.get("class") else [],[[k,v] for k,v in attr[2] if k not in ("href","title")]]
        # Footnote reference link conversion - if class footnote-ref and footnotes dict later unknown. Return Link for now; postprocessing could swap.
        return [{"t":"Link","c":[attr,inlines_from_children(node.children,ctx),[href,title]]}]
    if tag=="img":
        src=node.attrs.get("src",""); title=node.attrs.get("title",""); alt=node.attrs.get("alt","")
        attr=[node.attrs.get("id",""),node.attrs.get("class","").split() if node.attrs.get("class") else [],[]]
        for k,v in node.attrs.items():
            if k not in ("id","class","src","title","alt"): attr[2].append([k,v])
        return [{"t":"Image","c":[attr,str_to_inlines(alt),[src,title]]}]
    if tag=="span":
        classes=node.attrs.get("class","").split()
        if "math" in classes:
            # Math span with TeX delimiters or content based on website? Pandoc HTML reader recognizes span.math with \( \) / $$ etc and MathML. Simplify: if text starts with \( or \[
            txt=node.text_content()
            if txt.startswith(r"\("): return [{"t":"Math","c":[{"t":"InlineMath"},txt[2:-2] if txt.endswith(r"\)") else txt[2:]]}]
            if txt.startswith(r"\["): return [{"t":"Math","c":[{"t":"DisplayMath"},txt[2:-2] if txt.endswith(r"\]") else txt[2:]]}]
            if "display" in classes: return [{"t":"Math","c":[{"t":"DisplayMath"},txt]}]
            # For KaTeX span plain tex
            return [{"t":"Math","c":[{"t":"InlineMath"},txt]}]
        if "smallcaps" in classes: return [{"t":"SmallCaps","c":inlines_from_children(node.children,ctx)}]
        if "underline" in classes: return [{"t":"Underline","c":inlines_from_children(node.children,ctx)}]
        attr=node_attr(node,ctx)
        if ctx.ext("native_spans",False):
            return [{"t":"Span","c":[attr,inlines_from_children(node.children,ctx)]}]
        return inlines_from_children(node.children,ctx)
    if tag=="math":
        # MathML conversion very simple to TeX unknown - use text content as tex
        return [{"t":"Math","c":[{"t":"InlineMath"},node.text_content()]}]
    if tag in BLOCK_TAGS:
        # Block inside inline context flattened
        return inlines_from_children(node.children,ctx)
    # Unknown inline tags transparent (raw_html if ext enabled? For HTML reader, unknown tags generally ignored content retained, but some struct tags...)
    return inlines_from_children(node.children,ctx)

def text_from_html(s):
    # Preserve spaces as Space nodes, newlines SoftBreak - but HTML source indentation newlines before block should be trimmed later.
    out=[]; i=0
    while i<len(s):
        if s[i].isspace():
            j=i
            has_nl=False
            while j<len(s) and s[j].isspace():
                if s[j]=='\n': has_nl=True
                j+=1
            out.append(I("SoftBreak") if has_nl else I("Space")); i=j
        else:
            j=i
            while j<len(s) and not s[j].isspace(): j+=1
            out.append(I("Str",s[i:j])); i=j
    return out

def normalize_html_inlines(inls):
    # Merge adjacent Str, suppress spaces at around SoftBreak? Trim is performed by caller.
    return normalize_inlines(inls)
def trim_inlines(inls,left=True,right=True):
    inls=list(inls)
    if left:
        while inls and inls[0].get("t") in ("Space","SoftBreak"): inls.pop(0)
    if right:
        while inls and inls[-1].get("t") in ("Space","SoftBreak"): inls.pop()
    return inls
