        return inlines_from_children(node.children,ctx)
    # Unknown inline tags transparent (raw_html if ext enabled? For HTML reader, unknown tags generally ignored content retained, but some struct tags...)
    return inlines_from_children(node.children,ctx)

def text_from_html(s):
    # Preserve spaces as Space nodes, newlines SoftBreak - but HTML source indentation newlines before block should be trimmed later.
    out=[]; i=0
    while i<len(s):
