            while j<len(s) and s[j].isspace():
                if s[j]=='\n': has_nl=True
                j+=1
            out.append(I("SoftBreak") if has_nl else I("Space")); i=j
        else:
            j=i
            while j<len(s) and not s[j].isspace(): j+=1
            out.append(I("Str",s[i:j])); i=j
    return out

def normalize_html_inlines(inls):
    # Merge adjacent Str, suppress spaces at around SoftBreak? Trim is performed by caller.
    return normalize_inlines(inls)
def trim_inlines(inls,left=True,right=True):
    inls=list(inls)
    if left:
