        # original error message format for sample: line1 col6 for $foo( (source name was quoted path)
        # Col provided is position of $; '(' at col+ ? including stripped spaces
        raise TemplateError(f'Error compiling template "{source_name}" (line {line}, column {col+content.find("(")+1}):\nunexpected \'(\'\n')
    # Empty content ($) - error in original showed: $ $ maybe? If content empty, error unexpected "$" in endif tokenization etc. We'll return an empty var causing unknown? For template "$endif$" parsed above. A bare '$$' handled.
    if content=="":
        return ('text','')
    return ('expr',content,line,col)

def normalize_tokens(tokens):
    # Handle control/comment line-end consumption and standalone leading whitespace removal
    toks=list(tokens)
    # We need know if a control token is at end of line: next token text starts with newline (or no next token at EOF) . Consume one newline from that text.
    # Standalone: preceding tokens since last newline: inspect previous text token suffix after last newline only spaces/tabs, and no other non-text token after that newline (i.e. immediate previous token is text (or start) - if previous token is another control/var, then line has something)
    out=[]
    i=0
    while i < len(toks):
        tok=toks[i]
        if tok[0]=='comment':
            # If comment is at start of a line with no leading whitespace: remove following newline.
            # Determine preceding text
            prev_text = out[-1][1] if out and out[-1][0]=='text' else None
            at_line_start=False
            if not out:
                at_line_start=True
            elif prev_text is not None and (prev_text.endswith('\n')):
                at_line_start=True
            if at_line_start:
                # skip comment and consume following newline in next text
                if i+1 < len(toks) and toks[i+1][0]=='text' and toks[i+1][1].startswith('\n'):
                    toks[i+1]=('text',toks[i+1][1][1:])
                i+=1; continue
            else:
                # comment is just removed, newline remains
                i+=1; continue
        if tok[0]=='control':
            # Check at line end
            next_text=toks[i+1] if i+1<len(toks) else None
            at_line_end = (next_text is None) or (next_text[0]=='text' and next_text[1].startswith('\n'))
            # standalone if previous is start or a text token whose tail after last newline is only whitespace. However if there's a previous token on same line: if out's last token isn't text, then there's something.
            standalone=False
            if at_line_end:
                if not out:
                    standalone=True
                elif out[-1][0]=='text':
                    tail=out[-1][1].rsplit('\n',1)[-1]
                    if tail.strip(' \t')=="":
                        standalone=True
                        if tail:
                            out[-1]=('text',out[-1][1][:-len(tail)])
            if at_line_end and next_text is not None:
                # consume exactly one newline (\r\n too)
                if next_text[1].startswith('\r\n'):
                    toks[i+1]=('text',next_text[1][2:])
                elif next_text[1].startswith('\n'):
                    toks[i+1]=('text',next_text[1][1:])
            out.append(tok); i+=1; continue
        out.append(tok); i+=1
    # Remove empty texts
    return [t for t in out if not (t[0]=='text' and t[1]=="")]

# AST nodes
class TNode: pass

def parse_template(text,source_name=""):
    tokens=tokenize_template(text,source_name)
    # Annotate expr tokens for standalone line prefix: Need token positions line/col and template source.
    # We compute line_prefix based on text token? Tokens stream allows us: an expr is standalone if prev token is start/text ending with newline+spaces (or beginning+spaces) and next token is text starting with optional spaces + newline (or EOF). Attach dict? token tuple extended.
    annotated=[]
    for idx,tok in enumerate(tokens):
        if tok[0]=='expr':
            prefix=None
            if idx==0:
                prev_ok=True; prefix=""
            elif tokens[idx-1][0]=='text':
                prev=tokens[idx-1][1]; tail=prev.rsplit('\n',1)[-1] if '\n' in prev else (prev if idx-1==0 else None)
                # If previous token is not first and prev has no newline, there's nontext content prior on line
                if tail is not None and tail.strip(' \t')=="":
                    prev_ok=True; prefix=tail
                else: prev_ok=False
            else: prev_ok=False
            next_ok=False
            if idx+1>=len(tokens): next_ok=True
            elif tokens[idx+1][0]=='text':
                nt=tokens[idx+1][1]
                if re.match(r'^[ \t]*\n',nt): next_ok=True
                elif re.fullmatch(r'[ \t]*',nt) and idx+2>=len(tokens): next_ok=True
            if prev_ok and next_ok:
                annotated.append(('expr',tok[1],tok[2],tok[3],prefix))
            else:
                annotated.append(tok)
        else:
            annotated.append(tok)
    parser=TParser(annotated,source_name)
    nodes,term=parser.parse_until(())
    return nodes

class TParser:
    def __init__(self,toks,source_name): self.toks=toks; self.i=0; self.source_name=source_name
    def parse_until(self,terminators):
        nodes=[]
        while self.i < len(self.toks):
            tok=self.toks[self.i]
            if tok[0]=='control' and tok[1] in terminators:
                return nodes,tok
            if tok[0]=='text':
                nodes.append(('text',tok[1])); self.i+=1; continue
            if tok[0]=='nest':
                nodes.append(('nest',)); self.i+=1; continue
            if tok[0]=='breakable':
                nodes.append(('breakable',)); self.i+=1; continue
            if tok[0]=='expr':
                # tok may have prefix as fifth
                nodes.append(('expr',tok[1],tok[4] if len(tok)>4 else None)); self.i+=1; continue
            if tok[0]=='control':
                name=tok[1]
                if name=='if':
                    self.i+=1
                    branches=[]
                    expr=tok[2]
                    body,term=self.parse_until(('elseif','else','endif'))
                    branches.append((expr,body))
                    while term is not None and term[1]=='elseif':
                        expr2=term[2]; self.i+=1
                        body,term=self.parse_until(('elseif','else','endif')); branches.append((expr2,body))
                    else_body=None
                    if term is not None and term[1]=='else':
                        self.i+=1; else_body,term=self.parse_until(('endif',))
                    if term is None:
                        raise TemplateError(f'Error compiling template "{self.source_name}" (line 1, column 1):\nunexpected end of input\n')
                    self.i+=1 # endif
                    nodes.append(('if',branches,else_body)); continue
                if name=='for':
                    expr=tok[2]; self.i+=1
                    body,term=self.parse_until(('sep','endfor'))
                    sep=None
                    if term is not None and term[1]=='sep':
                        self.i+=1; sep,term=self.parse_until(('endfor',))
                    if term is None:
                        raise TemplateError(f'Error compiling template "{self.source_name}" (line 1, column 1):\nunexpected end of input\n')
                    self.i+=1; nodes.append(('for',expr,body,sep)); continue
                # Unexpected terminator
                line=tok[3] if len(tok)>3 else 1; col=tok[4] if False else 1
                # tok structure control: ('control',name,arg,line,col)
                line=tok[3]; col=tok[4] if len(tok)>4 else tok[3]
                raise TemplateError(f'Error compiling template "{self.source_name}" (line {line}, column {col}):\nunexpected "$"\n')
            self.i+=1
        return nodes,None

# Expression parsing: partial application and pipes
def parse_expr(s):
    # s could be: var[.field][/pipes][[sep]] ; var:partial()[/pipes][[sep]] ; partial()[...][/pipes] ; var[sep]
    # Separator suffix [ ... ] may be after var/partial and before pipes? doctemplates syntax: ${months[, ]}, ${articles:bibentry()[; ]}
    # Pipes follow / - separator in square brackets takes literal characters including commas/spaces and ends ]
    separator=None
    # Locate [ that is not in quoted strings? Find a '[' at after value *not* a field (?) - variable names have no brackets.
    # We'll scan for '['; if found and matching ']' and what precedes looks like var/partial, extract.
    # But pipes arguments have strings that may include [ - pipes come after '/', so separator should be before first '/'
    first_slash=find_unquoted(s,'/')
    head=s if first_slash==-1 else s[:first_slash]
    rest="" if first_slash==-1 else s[first_slash:]
    # Sep in head
    m=re.search(r'\[([^\]]*)\]\s*$',head)
    if m:
        separator=m.group(1); head=head[:m.start()]
    pipes=[]
    if rest:
        pipes=parse_pipes(rest)
    # Partial colon: but variable paths have no colon except maybe partial application before partial name ending ()
    partial=None; apply_var=None
    # Check colon unquoted
    colon=find_unquoted(head,':')
    if colon!=-1 and head[colon+1:].strip().endswith('()'):
        apply_var=head[:colon].strip(); partial=head[colon+1:].strip()[:-2].strip()
    elif head.strip().endswith('()'):
        partial=head.strip()[:-2].strip()
    var=head.strip()
    return {"var":var if partial is None and apply_var is None else None,"partial":partial,"apply_var":apply_var,"pipes":pipes,"separator":separator}

def find_unquoted(s,ch):
    in_q=False; i=0
    while i<len(s):
        if s[i]=='\\': i+=2; continue
        if s[i]=='"': in_q=not in_q
        if s[i]==ch and not in_q: return i
        i+=1
    return -1

def parse_pipes(rest):
    pipes=[]; i=0
    while i<len(rest):
        assert rest[i]=='/'
        i+=1
        while i<len(rest) and rest[i]==' ': i+=1
        m=re.match(r'[A-Za-z]+',rest[i:])
        if not m: break
        name=m.group(0); i+=len(name)
        params=[]
        # Params numbers / quoted strings until next / or end
        while i<len(rest):
            while i<len(rest) and rest[i]==' ': i+=1
            if i>=len(rest) or rest[i]=='/': break
            if rest[i]=='"':
                j=i+1
                val=""
                while j<len(rest):
                    if rest[j]=='\\' and j+1<len(rest): val+=rest[j+1]; j+=2; continue
                    if rest[j]=='"': break
                    val+=rest[j]; j+=1
                params.append(val); i=j+1
            else:
                m2=re.match(r'-?\d+',rest[i:])
                if m2: params.append(int(m2.group(0))); i+=len(m2.group(0))
                else: break
        pipes.append((name,params))
    return pipes

# Value helpers
def is_truthy(v):
    if isinstance(v,dict): return True
    if isinstance(v,list): return any(is_truthy(x) for x in v)
    if isinstance(v,bool): return v
    if isinstance(v,str): return len(v)>0
    if v is None: return False
    return bool(v)

def value_to_string(v):
    if v is None: return ""
    if isinstance(v,bool): return "true" if v else "false"
    if isinstance(v,dict): return "true"
    if isinstance(v,list): return "".join(value_to_string(x) for x in v)
    return str(v)

class Renderer:
    def __init__(self,context,template_loader=None,source_name="",base_dir=None,user_data_dir=None,template_path_for_partials=None,columns=72,wrap="auto",prog="executable"):
        self.frames=[context]  # chain list of dicts innermost last
        self.global_context=context
        self.loader=template_loader
        self.source_name=source_name
        self.base_dir=base_dir
        self.user_data_dir=user_data_dir
        self.template_path=template_path_for_partials
        self.columns=columns; self.wrap=wrap; self.prog=prog
        self.breakable=False
        self.pending_nest_current=False
    def lookup(self,var_expr):
        # var_expr could include pipes - caller parses before
        if var_expr is None or var_expr=="": return None
        parts=var_expr.split('.')
        # Look up by trying longest prefix key in frames? For now first component
        first=parts[0]
        if first=="it":
            # innermost it
            base=None; found=False
            for frame in reversed(self.frames):
                if "it" in frame: base=frame["it"]; found=True; break
            if not found: return None
            return navigate(base,parts[1:])
        for frame in reversed(self.frames):
            if first in frame:
                return navigate(frame[first],parts[1:])
            # if frame is a map from a loop item merged fields (we merge), above captures
        # Try dotted keys exactly in global context
        if var_expr in self.global_context:
            return self.global_context[var_expr]
        return None
    def eval_expr(self,expr_str):
        info=parse_expr(expr_str)
        if info["partial"] is not None:
            raise ValueError("partial in eval_expr")
        val=self.lookup(info["var"])
        val=apply_pipes(val,info["pipes"],self)
        return val
    def render_nodes(self,nodes):
        docs=[]
        for node in nodes:
            d=self.render_node(node)
            if d is not None: docs.append(d)
        return Cat(docs)
    def render_node(self,node):
        kind=node[0]
        if kind=='text':
            return text_to_doc(node[1],self.breakable)
        if kind=='breakable':
            self.breakable=not self.breakable; return Empty()
        if kind=='nest':
            self.pending_nest_current=True; return Empty()
        if kind=='expr':
            info=parse_expr(node[1]); prefix=node[1] if False else (node[2] if len(node)>2 else None)
            # node form ('expr',content,prefix)
            if info["partial"] is not None:
                d=self.render_partial_expr(info)
            else:
                val=self.lookup(info["var"])
                # Sep direct variable ${var[, ]}
                if info["separator"] is not None and isinstance(val,list):
                    # pipes apply per element or whole? Manual separator after variable applies separator between values; pipes maybe after separator could transform resulting? We'll apply pipes to each element then join.
                    parts=[]
                    for item in val:
                        iv=apply_pipes(item,info["pipes"],self)
                        parts.append(self.value_to_doc(iv))
                    d=join_doc_list(parts,Text(info["separator"]))
                else:
                    val=apply_pipes(val,info["pipes"],self)
                    d=self.value_to_doc(val)
            if self.pending_nest_current:
                d=NestCurrent(d); self.pending_nest_current=False
            elif prefix is not None and prefix!="":
                d=Nest(prefix,d)
            return d
        if kind=='if':
            branches,else_body=node[1],node[2]
            for expr,body in branches:
                if is_truthy(self.eval_expr(expr)):
                    return self.render_nodes(body)
            if else_body is not None: return self.render_nodes(else_body)
            return Empty()
        if kind=='for':
            expr,body,sep=node[1],node[2],node[3]
            info=parse_expr(expr)
            if info["partial"] is not None:
                # for over partial? no.
                val=None; varname=info["var"]
            else:
                varname=info["var"]; val=self.lookup(varname); val=apply_pipes(val,info["pipes"],self)
            if val is None:
                return Empty()
            if isinstance(val,list): items=val
            elif isinstance(val,dict): items=[val]
            else: items=[val]
            out_parts=[]
            sep_doc=self.render_nodes(sep) if sep else None
            for idx,item in enumerate(items):
                frame={}
                frame["it"]=item
                # assign var name nested
                assign_varname(frame,varname,item)
                if isinstance(item,dict):
                    for k,vv in item.items():
                        if k not in frame: frame[k]=vv
                self.frames.append(frame)
                try: part=self.render_nodes(body)
                finally: self.frames.pop()
                if idx>0 and sep_doc is not None:
                    out_parts.append(sep_doc)
                out_parts.append(part)
            return Cat(out_parts)
        return Empty()
    def render_partial_expr(self,info):
        partial_name=info["partial"]
        # Determine iteration variable if apply_var
        if info["apply_var"] is not None:
            val=self.lookup(info["apply_var"])
            # Apply pipes to val before iteration? Partial followed by pipes applies pipes to rendered result, separator etc.
            items = val if isinstance(val,list) else [val] if val is not None else []
            parts=[]
            for item in items:
                frame={"it":item}
                if isinstance(item,dict):
                    for k,v in item.items():
                        if k not in frame: frame[k]=v
                self.frames.append(frame)
                try:
                    part_doc=self.load_and_render_partial(partial_name)
                finally: self.frames.pop()
                parts.append(part_doc)
            sep=info["separator"]
            if sep is not None:
                doc=join_doc_list(parts,Text(sep))
            else:
                doc=Cat(parts)
        else:
            doc=self.load_and_render_partial(partial_name)
            if info["separator"] is not None:
                # Partial returns a value that is list? Not typical without apply var
                pass
        # Pipes on partial result: convert doc to string via rendering at huge width (?) Pandoc pipes on docs operate on textual value preserving doc structure for some (uppercase transforms text). Simplify: if pipes, render doc with wrap none / huge cols to string, apply pipes to string then convert to doc preserving lines.
        if info["pipes"]:
            s=render(doc,columns=1000000,wrap="none")
            v=apply_pipes(s,info["pipes"],self)
            doc=self.value_to_doc(v)
        return doc
    def load_and_render_partial(self,partial_name):
        # loader callable supplied by main returns template text and source name / base info or raises TemplateError / PandocError97
        if self.loader is None:
            raise PandocError(f"Could not find data file templates/{partial_name}\n",97)
        text,srcname,base_dir,template_path=self.loader(partial_name,self)
        nodes=parse_template(text,srcname)
        # Partials final newline omitted: by nodes rendering, if last text ends with newline strip one trailing newline from last text node recursively? Simplest: after rendering doc to string in parent? But we return Doc, trailing Cr in partial doc would cause a line break. Partials manual: final newlines are omitted.
        # We can preprocess text: remove exactly one final newline (or all? "Final newlines" plural maybe all trailing newlines are omitted) before parsing.
        # Our loader receives original text; parse_template above used it. Let's strip trailing newline before parse by reparse if needed.
        if text.endswith("\n"):
            # Remove all? Test dzslides partial ends multiple? It likely strips final newline only, but phrase "Final newlines are omitted" could mean chomp of trailing newlines.
            trimmed=text.rstrip("\n")
            # If original had multiple newlines, maybe only one? Trim all may alter a partial whose blank line intentional at end. Use remove exactly one? Manual sentence could mean the final newline (singular concept). We'll remove exactly one from the original text and reparse only if we did one removal, but if there are 2+ final newlines and only one removed, parser might include an empty line. We'll choose one.
            trimmed=text[:-1]
            if trimmed.endswith("\r"): trimmed=trimmed[:-1]
            nodes=parse_template(trimmed,srcname)
        sub=Renderer(self.global_context,self.loader,srcname,base_dir,self.user_data_dir,template_path,columns=self.columns,wrap=self.wrap,prog=self.prog)
        sub.frames=self.frames  # share scope chain
        sub.breakable=self.breakable
        return sub.render_nodes(nodes)
    def value_to_doc(self,val):
        if val is None: return Empty()
        if isinstance(val,tuple): # pretty Doc node passed in context
            return val
        if isinstance(val,BodyText):
            s=str(val)
            doc=string_lines_to_doc(s.rstrip("\n")) if s.strip("\n")!="" or s!="" else Empty()
            if s:
                if val.trailing=='blank': doc=Cat([doc,Blank()])
                elif val.trailing=='optcr': doc=Cat([doc,OptCr()])
                elif val.trailing=='cr': doc=Cat([doc,Cr()])
            return doc
        if isinstance(val,BreakableText):
            return breakable_string_to_doc(str(val))
        if isinstance(val,list):
            return Cat([self.value_to_doc(x) for x in val])
        if isinstance(val,dict):
            return Text("true")
        if isinstance(val,bool):
            return Text("true" if val else "false")
        s=str(val)
        return string_lines_to_doc(s)

def join_doc_list(parts,sepdoc):
    if not parts: return Empty()
    out=parts[0]
    for p in parts[1:]: out=Cat([out,sepdoc,p])
    return out

def assign_varname(frame,varname,item):
    if not varname: return
    parts=varname.split('.')
    if len(parts)==1:
        frame[parts[0]]=item; return
    # build nested dict for first part
    root={}
    cur=root
    for p in parts[1:-1]:
        cur[p]={}; cur=cur[p]
    cur[parts[-1]]=item
    frame[parts[0]]=root

def navigate(base,parts):
    cur=base
    for p in parts:
        if isinstance(cur,dict):
            if p in cur: cur=cur[p]
            else: return None
        elif isinstance(cur,list):
            # field access on list? doctemplates may apply field to each? if list of maps and getting field maybe concatenates? Not.
            return None
        else:
            return None
    return cur

def apply_pipes(val,pipes,renderer):
    for name,params in pipes:
        val=apply_pipe(val,name,params)
    return val
def apply_pipe(val,name,params):
    if name=="pairs":
        if isinstance(val,dict): return [{"key":k,"value":v} for k,v in val.items()]
        if isinstance(val,list): return [{"key":str(i+1),"value":v} for i,v in enumerate(val)]
        return val
    if name=="uppercase": return value_to_string(val).upper() if not isinstance(val,list) else [value_to_string(x).upper() if isinstance(x,str) else x for x in val]
    if name=="lowercase": return value_to_string(val).lower() if not isinstance(val,list) else [value_to_string(x).lower() if isinstance(x,str) else x for x in val]
    if name=="length":
        if isinstance(val,(list,dict)): return str(len(val))
        return str(len(value_to_string(val)))
    if name=="reverse":
        if isinstance(val,list): return list(reversed(val))
        if isinstance(val,str): return val[::-1]
        return val
    if name=="first": return val[0] if isinstance(val,list) and val else val
    if name=="last": return val[-1] if isinstance(val,list) and val else val
    if name=="rest": return val[1:] if isinstance(val,list) and val else val
    if name=="allbutlast": return val[:-1] if isinstance(val,list) and val else val
    if name=="chomp": return value_to_string(val).rstrip("\n") if not isinstance(val,(list,dict)) else val
    if name=="nowrap": return val
    if name=="alpha":
        s=value_to_string(val).strip()
        try:
            n=int(s); return chr(ord('a')+((n-1)%26)) if n>0 else s
        except: return val
    if name=="roman":
        s=value_to_string(val).strip()
        try:
            n=int(s); return to_roman(n)
        except: return val
    if name in ("left","right","center"):
        if not params: return val
        width=params[0] if isinstance(params[0],int) else int(params[0])
        leftb=params[1] if len(params)>1 else ""
        rightb=params[2] if len(params)>2 else ""
        s=value_to_string(val)
        lines=s.split("\n")
        out=[]
        for line in lines:
            if name=="left": core=line.ljust(width)
            elif name=="right": core=line.rjust(width)
            else:
                pad=width-len(line); core=" "*(pad//2)+line+" "*(pad-pad//2) if pad>0 else line
            out.append(leftb+core+rightb)
        return "\n".join(out)
    return val

def to_roman(n):
    vals=[(1000,'m'),(900,'cm'),(500,'d'),(400,'cd'),(100,'c'),(90,'xc'),(50,'l'),(40,'xl'),(10,'x'),(9,'ix'),(5,'v'),(4,'iv'),(1,'i')]; out=""
    for v,s in vals:
        while n>=v: out+=s; n-=v
    return out

def text_to_doc(s,breakable=False):
    if s=="": return Empty()
    if breakable:
        # Newlines and spaces are breakable spaces
        parts=[]
        for token in re.split(r'(\s+)',s):
            if token=="": continue
            if token.isspace(): parts.append(BS())
            else: parts.append(Text(token))
        return Cat(parts)
    lines=s.split("\n")
    docs=[]
    for idx,line in enumerate(lines):
        if idx>0: docs.append(Cr())
        if line: docs.append(Text(line))
    return Cat(docs)

def string_lines_to_doc(s):
    return text_to_doc(s,False)
def breakable_string_to_doc(s):
    # split by spaces outside (? simply all spaces) but newlines are Cr.
    lines=s.split("\n"); docs=[]
    for idx,line in enumerate(lines):
        if idx>0: docs.append(Cr())
        parts=[]
        for token in re.split(r'( )',line):
            if token=="": continue
            if token==" ": parts.append(BS())
            else: parts.append(Text(token))
        docs.append(Cat(parts))
    return Cat(docs)

def render_template(template_text,context,loader=None,source_name="",base_dir=None,user_data_dir=None,template_path=None,columns=72,wrap="auto",prog="executable"):
