import copy, re, unicodedata
from .ast import B

def shift_headings(doc,shift):
    if shift==0: return doc
    meta=doc.get("meta",{})
    blocks=doc.get("blocks",[])
    new_blocks=[]
    title_taken=("title" in meta)
    # Recursive transformation for nested? Pandoc shiftHeadingLevelBy operates on all headers via walk, title promotion only for first top-level heading that becomes level<1? We'll implement top-level special and generic shifting for nested through recursive transform with no promotion.
    def shift_block(b,top=False,state=None):
        t=b.get("t"); c=b.get("c")
        if t=="Header":
            new_level=c[0]+shift
            if new_level<=0:
                # at shift -1, level1 -> 0. At shift -2, level1->-1 and level2->0: test -2: first heading A became Para not title. So promotion only if new_level==0 and it's first such heading and no existing title.
                if top and new_level==0 and not title_taken and state is not None and not state.get("used"):
                    state["used"]=True
                    meta["title"]={"t":"MetaInlines","c":c[2]}
                    return None
                return B("Para",c[2])
            return B("Header",[new_level,c[1],c[2]])
        # Recurse common containers
        if t=="BlockQuote": return B(t,[shift_block(x,False,state) for x in c if shift_block(x,False,state) is not None]) if False else B(t,filter_none([shift_block(x,False,state) for x in c]))
        if t=="Div": return B(t,[c[0],filter_none([shift_block(x,False,state) for x in c[1]])])
        if t=="BulletList": return B(t,[[y for y in (shift_block(x,False,state) for x in item) if y] for item in c])
        if t=="OrderedList": return B(t,[c[0],[[y for y in (shift_block(x,False,state) for x in item) if y] for item in c[1]]])
        return b
    state={"used":False}
    for b in blocks:
        nb=shift_block(b,True,state)
        if nb is not None: new_blocks.append(nb)
    doc={"meta":meta,"blocks":new_blocks}
    return doc

def filter_none(lst): return [x for x in lst if x is not None]

def strip_comments_doc(doc):
    def is_comment_raw(text,fmt):
        t=text.strip()
        if fmt in ("html","html5","html4") and t.startswith("<!--") and t.endswith("-->"): return True
        return False
    def walk(x):
        if isinstance(x,list):
            out=[]
            for item in x:
                r=walk(item)
                if r is not None: out.append(r)
            return out
        if isinstance(x,dict):
            t=x.get("t")
            if t=="RawBlock" and is_comment_raw(x["c"][1],x["c"][0] if isinstance(x["c"][0],str) else ""): return None
            if t=="RawInline" and is_comment_raw(x["c"][1],x["c"][0] if isinstance(x["c"][0],str) else ""): return None
            return {k:walk(v) for k,v in x.items()}
        return x
    new_blocks=[]
    for b in doc.get("blocks",[]):
        nb=walk(b)
        if nb is None: continue
        # remove empty Para/Plain after stripping inlines
        if nb.get("t") in ("Para","Plain") and not nb.get("c"): continue
        new_blocks.append(nb)
    return {"meta":doc.get("meta",{}),"blocks":new_blocks}

def east_asian_remove_softbreaks(inlines):
    def is_wide(ch): return unicodedata.east_asian_width(ch) in ("W","F")
    def last_char(inl):
        if inl.get("t")=="Str": return inl["c"][-1] if inl["c"] else ""
        return ""
    def first_char(inl):
        if inl.get("t")=="Str": return inl["c"][0] if inl["c"] else ""
        return ""
    out=[]
    for idx,inl in enumerate(inlines):
        if inl.get("t")=="SoftBreak" and out and idx+1<len(inlines):
            a=last_char(out[-1]); b=first_char(inlines[idx+1])
            if a and b and is_wide(a) and is_wide(b): continue
        out.append(inl)
    return out

