import json, sys
VERBOSITY_ORDER={"DEBUG":0,"INFO":1,"WARNING":2,"ERROR":3}
class Logger:
    def __init__(self,verbosity="WARNING"):
        self.verbosity=verbosity; self.messages=[]
    def log(self,typ,verbosity,pretty,**fields):
        msg={"type":typ,"verbosity":verbosity}
        # Fields will sorted in json export
        msg.update(fields)
        msg["pretty"]=pretty
        self.messages.append(msg)
    def report(self):
        threshold=VERBOSITY_ORDER.get(self.verbosity,2)
        out=[]
        for m in self.messages:
            if VERBOSITY_ORDER.get(m["verbosity"],2)>=threshold:
                pretty=m["pretty"]
                lines=pretty.split("\n")
                out.append(f"[{m['verbosity']}] {lines[0]}\n")
                for line in lines[1:]: out.append(f"  {line}\n")
        return "".join(out)
    def to_json(self):
        objs=[]
        for m in self.messages:
            keys=sorted(k for k in m.keys() if k not in ("type","verbosity"))
            obj={}
            obj["type"]=m["type"]; obj["verbosity"]=m["verbosity"]
            for k in keys: obj[k]=m[k]
            objs.append(obj)
        return json.dumps(objs,indent=4,ensure_ascii=False)
    def has_warnings(self):
        return any(VERBOSITY_ORDER.get(m["verbosity"],2)>=2 for m in self.messages)
