import os, re, json, datetime
from .ast import stringify
from .template import BodyText, BreakableText
from .yamlparser import parse_yaml
from .util import read_resource

HTML_FORMATS={"html","html5","html4","slidy","slideous","s5","dzslides","revealjs","chunkedhtml","epub","epub2","epub3"}
BLANK_BODY_FORMATS={"markdown","markdown_github","markdown_mmd","markdown_phpextra","markdown_strict","markua","plain","ansi","commonmark","commonmark_x","gfm","rst","org","typst","asciidoc","asciidoc_legacy","asciidoctor","context","djot","mediawiki","dokuwiki","haddock","muse","textile"} # textile was optcr in probe, remove below
BLANK_BODY_FORMATS.discard("textile")

def body_text_for_format(fmt,body_str):
    trailing='blank' if fmt in BLANK_BODY_FORMATS else 'optcr'
    return BodyText(body_str.rstrip("\n"),trailing=trailing)

def meta_stringify(mv):
    if mv is None: return ""
    t=mv.get("t"); c=mv.get("c")
    if t=="MetaString": return c
    if t=="MetaBool": return "true" if c else "false"
    if t in ("MetaInlines","MetaBlocks"): return stringify(c).strip()
    if t=="MetaList": return ", ".join(meta_stringify(x) for x in c)
    return stringify(mv).strip()

def make_meta_renderer(fmt,opts,exts):
    # Returns object with inlines/blocks/string methods returning strings (wrapped marker classes handled by caller)
    if fmt in HTML_FORMATS or fmt in ("docbook","docbook4","docbook5","jats","jats_archiving","jats_articleauthoring","jats_publishing"):
        from .writers.html import HtmlWriter
        from .pretty import render
        w=HtmlWriter(opts,exts,"html5" if fmt in HTML_FORMATS else fmt)
        class R:
            def inlines(self,inls): return render(w.inlines_to_doc(inls),columns=100000,wrap="none")
            def blocks(self,blocks): return render(w.blocks_to_doc(blocks),columns=opts.columns if opts else 72,wrap=opts.wrap if opts else "auto")
            def string(self,s): return w.esc(s)
        return R()
    if fmt in ("latex","beamer"):
        from .writers.latex import LatexWriter
        from .pretty import render
        w=LatexWriter(opts,exts,fmt)
        class R:
            def inlines(self,inls): return render(w.inlines_to_doc(inls),columns=100000,wrap="none")
            def blocks(self,blocks): return render(w.blocks_to_doc(blocks),columns=opts.columns if opts else 72,wrap=opts.wrap if opts else "auto")
            def string(self,s): return w.esc(s)
        return R()
    if fmt in ("markdown","markdown_github","markdown_mmd","markdown_phpextra","markdown_strict","markua","plain","commonmark","commonmark_x","gfm","ansi"):
        from .writers.markdown import MarkdownWriter
        from .pretty import render
        w=MarkdownWriter(opts,exts,fmt)
        class R:
            def inlines(self,inls): return render(w.inlines_to_doc(inls),columns=100000,wrap="none")
            def blocks(self,blocks): return render(w.blocks_to_doc(blocks),columns=opts.columns if opts else 72,wrap=opts.wrap if opts else "auto")
            def string(self,s):
                from .writers.markdown import escape_markdown_str
                return escape_markdown_str(s,w)
        return R()
    # Generic: use writer dispatch later? We'll render inlines as plain text with no formatting for metadata in other formats (may be close for titles).
    class R:
        def inlines(self,inls): return stringify(inls).strip()
        def blocks(self,blocks): return "\n\n".join(stringify(b).strip() for b in blocks)
        def string(self,s): return s
    return R()

def meta_to_context_value(mv,renderer):
    t=mv.get("t"); c=mv.get("c")
    if t=="MetaInlines":
        return BreakableText(renderer.inlines(c))
    if t=="MetaBlocks":
        # Blocks in template are considered a Doc value; represent as string ending without trailing newline (blocks render may end newline)
        return BreakableText(renderer.blocks(c).rstrip("\n"))
    if t=="MetaList":
        return [meta_to_context_value(x,renderer) for x in c]
    if t=="MetaMap":
        return {k:meta_to_context_value(v,renderer) for k,v in c.items()}
    if t=="MetaBool":
        return bool(c)
    if t=="MetaString":
        return renderer.string(c)
    return renderer.string(str(c))

def get_translation(lang, term, logger, data_reader=None):
    if not lang: return term
    # lang tag normalization: translations file names use language tag as provided capitalization e.g pt-BR. Try exact, then progressively drop subtags (last -..)
    candidates=[]
    parts=str(lang).split('-')
    for i in range(len(parts),0,-1): candidates.append('-'.join(parts[:i]))
    data=None; chosen=None
    for cand in candidates:
        # YAML filename case sensitivity: exact lang provided. Pandoc lowercases? For lang EN etc? It uses Lang rendering canonical BCP47 (e.g pt-BR, zh-Hans). Our candidates as supplied.
        if data_reader:
            data=data_reader(f"translations/{cand}.yaml")
        else:
            data=read_resource(f"translations/{cand}.yaml")
        if data is not None:
            chosen=cand; break
    if data is None:
        if logger:
            logger.log("CouldNotLoadTranslations","WARNING",f"Could not load translations for {lang}\ndata file translations/{lang}.yaml not found",lang=str(lang),message=f"data file translations/{lang}.yaml not found")
        if logger:
            logger.log("NoTranslation","WARNING",f"The term {term} has no translation defined.",term=term)
        return term
    try:
        trans=parse_yaml(data.decode())
    except Exception:
        trans={}
    if isinstance(trans,dict) and trans.get(term):
        return str(trans[term])
    if logger:
        logger.log("NoTranslation","WARNING",f"The term {term} has no translation defined.",term=term)
    return term

