    for f in fmts:
        try:
            dt=datetime.datetime.strptime(s,f)
            if f=="%Y%m": return dt.strftime("%Y-%m")
            if f=="%Y": return dt.strftime("%Y")
            return dt.strftime("%Y-%m-%d")
        except Exception: pass
    return None

