    include_contents=include_contents or {}
    meta=doc.get("meta",{})
    renderer=make_meta_renderer(fmt,opts,exts)
    context={}
    # Metadata first
    for k,v in meta.items():
        context[k]=meta_to_context_value(v,renderer)
    # Writer extra vars override meta for same names except defaults (most extra names not in meta)
    for k,v in extra_vars.items():
        context[k]=v
    # Derived meta fields (computed from metadata, only set if not explicitly in meta)
    # lang for translation should be metadata lang string (not rendered)
    lang_raw=meta_stringify(meta.get("lang")) if "lang" in meta else ""
    # pagetitle etc only relevant some formats but set generically if not in context
    # Note context `title` currently from Meta; if -V pagetitle later overrides.
    if "pagetitle" not in meta:
        if "title" in meta:
            context["pagetitle"]=meta_stringify(meta["title"])
        elif fmt in HTML_FORMATS or fmt in ("epub","epub2","epub3","chunkedhtml","revealjs","slidy","slideous","s5","dzslides"):
            # Determine fallback from source filenames
            fallback="-"
            if sources:
                # sources is list of file names as given; if first source is not stdin, use its basename without extension
                for src in sources:
                    if src and src!="-":
                        fallback=os.path.splitext(os.path.basename(src))[0]; break
            if logger:
                logger.log("NoTitleElement","INFO",f"This document format requires a nonempty <title> element.\nDefaulting to '{fallback}' as the title.\nTo specify a title, use --variable pagetitle=\"...\".",fallback=fallback)
            context["pagetitle"]=fallback
