    if "title-meta" not in meta and "title" in meta:
        context["title-meta"]=meta_stringify(meta["title"])
    if "author-meta" not in meta and "author" in meta:
        av=meta["author"]
        if av.get("t")=="MetaList": context["author-meta"]=[meta_stringify(x) for x in av["c"]]
        else: context["author-meta"]=[meta_stringify(av)]
