    if "description-meta" not in meta and "description" in meta:
        context["description-meta"]=meta_stringify(meta["description"])
    # abstract-title localization: Writers.Shared sets this for formats that use it? Observed HTML log warning for yi even without abstract, so set for HTML-based and probably all template writers? Guard by formats whose templates use abstract-title: html templates, epub, latex? Pandoc App/Writers Shared sets abstract-title in metadata context for all writers?? Test markdown standalone with yi gave warnings? Quick reasoning: metadataToContext is used by all writers with templates, and it sets abstract-title using translations. It might apply all.
    if "abstract-title" not in context:
        if fmt not in ("json","xml","native","ipynb"):
            # Determine lang: metadata lang, else en? If no lang, no warning and Abstract in English.
            context["abstract-title"]=get_translation(lang_raw if lang_raw else "en","Abstract",logger if lang_raw else None)
    # If fmt HTML and no lang specified, log NoLangSpecified INFO (observed for self-contained standalone log)
    if fmt in HTML_FORMATS and not lang_raw and not (opts and "lang" in opts.variables):
