        if logger:
            # Only log once? context builder called once.
            logger.log("NoLangSpecified","INFO","No value for 'lang' was specified in the metadata.\nIt is recommended that lang be specified for this format.")
    # Apply variables (override)
    if opts:
        for k in opts.variables_order:
            context[k]=opts.variables[k]
    # Automatic variables (set if not already provided by variable/meta - but body etc are authoritative)
    context["body"]=body_text_for_format(fmt,body_str)
    for key in ("header-includes","include-before","include-after"):
        if include_contents.get(key):
            context[key]=include_contents[key]
    if opts:
        if opts.toc: context.setdefault("toc",True) if fmt!="vimdoc" else context.__setitem__("toc",context.get("toc",True))
        if opts.lof: context["lof"]=True
        if opts.lot: context["lot"]=True
        if opts.number_sections: context["numbersections"]=True
        context.setdefault("toc-depth",str(opts.toc_depth))
        if opts.css: context["css"]=list(opts.css)
        if opts.title_prefix is not None: context["title-prefix"]=opts.title_prefix
        context["idprefix"]=opts.id_prefix
    # source/output
    if sources:
        context["sourcefile"]=sources if len(sources)>1 else (sources[0] if sources else "")
    else:
        context["sourcefile"]=[]
    context["outputfile"]=output_file if output_file else "-"
    context["curdir"]=os.getcwd()
    context["pandoc-version"]="3.9.0.2"
    if opts and (opts.pdf_engine or getattr(opts,"_resolved_pdf_engine",None)):
        context["pdf-engine"]=getattr(opts,"_resolved_pdf_engine",None) or opts.pdf_engine
    # meta-json
    try:
        context["meta-json"]=meta_json(doc,renderer)
    except Exception:
        context["meta-json"]="{}"
    return context

def meta_json(doc,renderer):
    meta=doc.get("meta",{})
    def conv(mv):
        t=mv.get("t"); c=mv.get("c")
        if t=="MetaMap": return {k:conv(v) for k,v in c.items()}
        if t=="MetaList": return [conv(x) for x in c]
        if t=="MetaBool": return bool(c)
        if t=="MetaString": return c
        if t=="MetaInlines": return renderer.inlines(c)
        if t=="MetaBlocks": return renderer.blocks(c)
        return str(c)
    return json.dumps({k:conv(v) for k,v in meta.items()},ensure_ascii=False)
