import os, re, json
from .errors import PandocError
from .yamlparser import parse_yaml
from .options import apply_option
from .util import user_data_dir

ALLOWED=set("""input-file input-files from reader to writer output-file data-dir defaults verbosity fail-if-warnings sandbox log-file shift-heading-level-by indented-code-classes default-image-extension file-scope filters metadata metadata-files metadata-file preserve-tabs tab-stop track-changes extract-media abbreviations trace standalone template variables eol dpi wrap columns table-of-contents toc toc-depth strip-comments syntax-highlighting syntax-definitions syntax-definition include-in-header include-before-body include-after-body resource-path request-headers no-check-certificate self-contained embed-resources link-images html-q-tags ascii reference-links reference-location figure-caption-position table-caption-position markdown-headings list-tables top-level-division number-sections number-offset listings list-of-figures lof list-of-tables lot incremental slide-level section-divs email-obfuscation identifier-prefix title-prefix css reference-doc epub-cover-image epub-title-page epub-metadata epub-fonts split-level chunk-template epub-subdirectory ipynb-output pdf-engine pdf-engine-opts pdf-engine-opt citeproc bibliography csl citation-abbreviations cite-method html-math-method dump-args ignore-args highlight-style epub-chapter-level""".split())
PATH_FIELDS={"data-dir","template","output-file","input-file","input-files","metadata-file","metadata-files","include-in-header","include-before-body","include-after-body","reference-doc","epub-cover-image","epub-metadata","epub-fonts","epub-embed-font","csl","bibliography","citation-abbreviations","extract-media","abbreviations","syntax-definition","syntax-definitions","log-file","css","resource-path","filters","defaults","syntax-highlighting","highlight-style"}

def load_defaults_file(arg,opts,prog):
    # returns (data_dict, resolved_path_for_errors, basedir)
    orig=arg
    # extension add if FILE lacks an extension (splitext basename)
    root,ext=os.path.splitext(arg)
    if ext=="":
        filename=arg+".yaml"
    else:
        filename=arg
    candidates=[]
    candidates.append(filename)
    # defaults subdir of user data (opts.data_dir or default)
    data_dir=opts.data_dir if getattr(opts,'data_dir',None) else user_data_dir()
    candidates.append(os.path.join(data_dir,"defaults",filename))
    chosen=None
    for cand in candidates:
        if os.path.isfile(cand): chosen=cand; break
    if chosen is None:
        # IO error will be handled by main conversion to prog message; use PandocError io flag attribute
        e=PandocError(f"{filename}: withBinaryFile: does not exist (No such file or directory)\n",1); e.is_io=True; raise e
    try:
        with open(chosen,'rb') as f: raw=f.read()
    except FileNotFoundError:
        e=PandocError(f"{filename}: withBinaryFile: does not exist (No such file or directory)\n",1); e.is_io=True; raise e
    try:
        text=raw.decode('utf-8')
    except UnicodeDecodeError as e:
        raise PandocError(f"Error parsing {chosen}:\n{e}\n",64)
    # JSON if .json
    data=None
    if chosen.lower().endswith('.json'):
        try: data=json.loads(text)
        except Exception as e: raise PandocError(f"Error parsing {chosen}:\nAeson exception:\n{e}\n",64)
    else:
        try: data=parse_yaml(text)
        except Exception as e: raise PandocError(f"Error parsing {chosen}:\nYAML parse exception at line 0, column 0:\n{e}\n",64)
    if data is None:
        data={}
    if not isinstance(data,dict):
        raise PandocError(f"Error parsing {chosen}:\nAeson exception:\nError in $: Expected a mapping\n",64)
    basedir=os.path.dirname(os.path.abspath(chosen))
    # Interpolate path fields
    userdata=data_dir
    data=interpolate_paths(data,userdata,basedir)
    # unknown fields
    for k in data.keys():
        if k not in ALLOWED:
            raise PandocError(f'Error parsing {chosen}:\nAeson exception:\nError in $: Unknown option "{k}"\n',64)
    return data,chosen,basedir

def interpolate(s,userdata,basedir):
    def repl(m):
        name=m.group(1)
        if name=="USERDATA": return userdata
        if name==".": return basedir
        return os.environ.get(name,"")
    return re.sub(r'\$\{([^}]+)\}',repl,s)
def interpolate_paths(data,userdata,basedir):
    out={}
    for k,v in data.items():
        if k in PATH_FIELDS:
            out[k]=interp_value(v,userdata,basedir)
        else:
            out[k]=v
    return out
def interp_value(v,userdata,basedir):
    if isinstance(v,str): return interpolate(v,userdata,basedir)
    if isinstance(v,list): return [interp_value(x,userdata,basedir) for x in v]
    if isinstance(v,dict): return {kk:interp_value(vv,userdata,basedir) for kk,vv in v.items()}
    return v

def scalar_str(v):
    if isinstance(v,bool): return "true" if v else "false"
    if v is None: return ""
    return str(v)

def apply_defaults_data(opts,data,path,action_handler,nested_handler,prog):
    # nested defaults first
    if "defaults" in data:
        vals=data["defaults"]
        if vals is not None:
            if not isinstance(vals,list): vals=[vals]
            for item in vals:
                nested_handler(opts,str(item))
    for key,value in data.items():
        if key=="defaults": continue
        apply_defaults_key(opts,key,value,path,action_handler,prog)

def type_name(v):
    if isinstance(v,bool): return "Boolean"
    if isinstance(v,str): return "String"
    if isinstance(v,(int,float)): return "Number"
    if isinstance(v,list): return "Array"
    if isinstance(v,dict): return "Object"
    if v is None: return "Null"
    return "String"
def defaults_type_error(path, expected, value):
    # Aeson phrasing examples: parsing Text failed, expected String, but encountered Array
    if expected=="Text":
        msg=f"parsing Text failed, expected String, but encountered {type_name(value)}"
    elif expected=="Int":
        msg=f"parsing Int failed, expected Number, but encountered {type_name(value)}"
    elif expected=="Bool":
        msg=f"parsing Bool failed, expected Boolean, but encountered {type_name(value)}"
    else: msg=f"expected {expected}, but encountered {type_name(value)}"
    return PandocError(f"Error parsing {path}:\nAeson exception:\nError in $: {msg}\n",64)

def apply_defaults_key(opts,key,value,path,action_handler,prog):
    def apply(canon,val):
        # Convert PandocError code6 into defaults parse error for some enum issues? Keep simple for now, but ipynb special below.
        apply_option(opts,canon,val,prog,action_handler,lambda o,p: None)
    # Aliases & specials
    if key=="input-file":
        vals=[value] if not isinstance(value,list) else value
        opts._defaults_input_files=[str(x) for x in vals]; return
    if key=="input-files":
        if value is None:
            opts._defaults_input_files=None
        else:
            vals=value if isinstance(value,list) else [value]; opts._defaults_input_files=[str(x) for x in vals]
        return
    if key=="output-file":
        if value is None: return
        if not isinstance(value,str): raise defaults_type_error(path,"Text",value)
        apply("output",value); return
    if key=="from" or key=="reader": apply("from",scalar_checked(value,path)); return
    if key=="to" or key=="writer": apply("to",scalar_checked(value,path)); return
    if key=="verbosity":
        if value not in ("INFO","WARNING","ERROR"): raise PandocError(f"Error parsing {path}:\nAeson exception:\nError in $: mzero\n",64)
        opts.verbosity=value; return
    if key=="log-file": apply("log",scalar_checked(value,path)); return
    if key=="variables":
        if not isinstance(value,dict): raise defaults_type_error(path,"Object",value)
        for k,v in value.items():
            # Template variables values are YAML structures: strings as literal, numbers to string (variable-json behavior)
            conv=defaults_context_value(v)
            opts.set_variable(str(k),conv,replace=True)
        return
    if key=="metadata":
        if not isinstance(value,dict): raise defaults_type_error(path,"Object",value)
        for k,v in value.items():
            opts.add_metadata(str(k),yaml_to_meta_literal(v))
        return
    if key=="filters":
        if value is None: return
        vals=value if isinstance(value,list) else [value]
        for item in vals:
            if isinstance(item,str):
                if item=="citeproc": opts.filters.append({"type":"citeproc","path":"citeproc","args":[]}); opts.cite_method="citeproc"
                elif item.endswith(".lua"): opts.filters.append({"type":"lua","path":item,"args":[]})
                else: opts.filters.append({"type":"json","path":item,"args":[]})
            elif isinstance(item,dict):
                typ=str(item.get("type","")).lower(); pth=str(item.get("path",""))
                if typ=="citeproc": opts.filters.append({"type":"citeproc","path":"citeproc","args":[]}); opts.cite_method="citeproc"
                elif typ=="lua": opts.filters.append({"type":"lua","path":pth,"args":[]})
                elif typ=="json": opts.filters.append({"type":"json","path":pth,"args":[]})
        return
    if key=="citeproc":
        if value is True:
            opts.filters.append({"type":"citeproc","path":"citeproc","args":[]}); opts.cite_method="citeproc"
        return
    if key=="cite-method":
        if value not in ("citeproc","natbib","biblatex"): raise PandocError(f'Error parsing {path}:\nAeson exception:\nError in $: Unknown citation method: "{value}"\n',64)
        opts.cite_method=value; return
    if key=="html-math-method":
        method=None; url=None
        if isinstance(value,str): method=value
        elif isinstance(value,dict): method=value.get("method"); url=value.get("url")
        if method=="mathjax": apply("mathjax",url)
        elif method=="katex": apply("katex",url)
        elif method=="webtex": apply("webtex",url)
        elif method=="mathml": apply("mathml",None)
        elif method=="gladtex": apply("gladtex",None)
        elif method in ("plain",None): opts.html_math_method=("plain",None)
        else: raise PandocError(f"Error parsing {path}:\nAeson exception:\nError in $: Unknown HTML math method \"{method}\"\n",64)
        return
    if key=="ipynb-output":
        mapping={"IpynbOutputAll":"all","IpynbOutputNone":"none","IpynbOutputBest":"best"}
        if value not in mapping:
            raise PandocError(f"Error parsing {path}:\nAeson exception:\nError in $: When parsing Text.Pandoc.App.Opt.IpynbOutput expected a String with the tag of a constructor but got {value}.\n",64)
        opts.ipynb_output=mapping[value]; return
    if key=="identifier-prefix": apply("id-prefix",scalar_checked(value,path)); return
    if key=="epub-fonts":
        vals=value if isinstance(value,list) else [value]
        for v in vals: apply("epub-embed-font",scalar_checked(v,path))
        return
    if key in ("metadata-files",):
        vals=value if isinstance(value,list) else [value]
        for v in vals: apply("metadata-file",scalar_checked(v,path))
        return
    if key in ("syntax-definitions",):
        vals=value if isinstance(value,list) else [value]
        for v in vals: apply("syntax-definition",scalar_checked(v,path))
        return
    if key in ("pdf-engine-opts",):
        vals=value if isinstance(value,list) else [value]
        for v in vals: apply("pdf-engine-opt",scalar_checked(v,path))
        return
    if key in ("css","include-in-header","include-before-body","include-after-body","resource-path","request-headers","indented-code-classes","bibliography"):
