    if not docs: return {"meta":{},"blocks":[]}
    meta={}; blocks=[]
    for d in docs:
        meta.update(d.get("meta",{})); blocks.extend(d.get("blocks",[]))
    return {"meta":meta,"blocks":blocks}

def adjust_file_scope_ids(doc,name):
    if not name or name=="-": prefix=""
    else:
        prefix=name.replace(os.sep,"__").replace("/","__")+"__"
    # Replace header/div/etc IDs in Attr everywhere and links target fragments
    def walk(x):
        if isinstance(x,list):
            # Attr pattern detection is hard in generic; use AST-specific in blocks convert below via recursion on typed nodes not generic.
            return [walk(i) for i in x]
        if isinstance(x,dict):
            t=x.get("t"); c=x.get("c")
            new=dict(x)
            if "c" in new: new["c"]=walk(c)
            # Blocks/inlines with Attr at known positions
            # Use a helper postprocess on new node
            return adjust_node(new,prefix)
        return x
    if prefix:
        doc={"meta":doc.get("meta",{}),"blocks":[walk(b) for b in doc.get("blocks",[])]}
    return doc

def adjust_node(node,prefix):
    # This generic second pass may double adjust nested - called after children walked. It checks known forms.
    t=node.get("t"); c=node.get("c")
    try:
        if t=="Header": c[1][0]=prefix+c[1][0] if c[1][0] else c[1][0]
        elif t in ("Div","Figure","Table","CodeBlock"): 
            if isinstance(c[0],list) and c[0][0]: c[0][0]=prefix+c[0][0]
        elif t in ("Link","Image"):
            if c[0][0]: c[0][0]=prefix+c[0][0]
            if c[2][0].startswith("#"): c[2][0]="#"+prefix+c[2][0][1:]
        elif t in ("Code","Span"):
            if c[0][0]: c[0][0]=prefix+c[0][0]
    except Exception: pass
    return node

