def write_document(self,doc,opts,writer_base,writer_exts,writer_custom,pdf_info,input_files):
    # Determine standalone effective
    auto_standalone_formats={"pdf","epub","epub2","epub3","fb2","docx","odt"}
    standalone = bool(opts.standalone or writer_base in auto_standalone_formats or (pdf_info is not None))
    opts._standalone_effective=standalone
    # Includes are fetched even for non-standalone (?) The contents read errors occur and if nonstandalone and no template, title-prefix/includes imply standalone in options application, so standalone may be true. If someone sets -s=false after include option, includes still are read? Original test --include-in-header=missing without -s error because include implies standalone at option application, could be overridden later. We'll fetch them regardless if specified to mirror missing errors.
    include_contents={}
    if opts.include_in_header:
        include_contents["header-includes"]=[fetch_resource_text(self,p) for p in opts.include_in_header]
    if opts.include_before_body:
        include_contents["include-before"]=[fetch_resource_text(self,p) for p in opts.include_before_body]
    if opts.include_after_body:
        include_contents["include-after"]=[fetch_resource_text(self,p) for p in opts.include_after_body]
    if writer_custom:
        from .lua_mode import run_custom_writer
        out=run_custom_writer(writer_base,doc,opts,self,standalone)
        return (out if isinstance(out,bytes) else out.encode()), False
    fmt=writer_base
    # No-template writers
    if fmt=="json":
        from .writers.json_native_xml import write_json
        return write_json(doc,opts,writer_exts,standalone=standalone).encode(),False
    if fmt=="xml":
        from .writers.json_native_xml import write_xml
        return write_xml(doc,opts,writer_exts,standalone=standalone).encode(),False
    if fmt=="native":
        from .writers.json_native_xml import write_native
        return write_native(doc,opts,writer_exts,standalone=standalone).encode(),False
    if fmt=="ipynb":
        from .writers.ipynb import write_ipynb
        return write_ipynb(doc,opts,writer_exts).encode(),False
    if fmt=="csljson":
        from .writers.biblio import write_csljson
        return write_csljson(doc,opts).encode(),False
    if fmt=="fb2":
        from .writers.fb2 import write_fb2
        return write_fb2(doc,opts,writer_exts,self).encode(),False
    if fmt in ("docx","odt","pptx","epub","epub2","epub3","chunkedhtml"):
        from .writers.binary import write_binary_format
        data=write_binary_format(fmt,doc,opts,writer_exts,self,include_contents)
        return data,True
    # Text writers
    body_str,extra_vars=self.render_body(doc,opts,fmt,writer_exts)
    if pdf_info is not None:
        # Need standalone version of intermediate
        text_out=self.apply_template_if_needed(doc,opts,fmt,writer_exts,body_str,extra_vars,include_contents,standalone=True,input_files=input_files)
        return self.make_pdf(text_out,pdf_info,opts),True
    if not standalone:
        # fragment normalization
        out=body_str
        if fmt in ("bibtex","biblatex"):
            # no final newline forced if empty; body if present likely ends newline
            pass
        else:
            if out=="":
                out="\n"
            elif not out.endswith("\n"):
                out+="\n"
        return apply_eol(out,opts).encode(),False
    else:
        out=self.apply_template_if_needed(doc,opts,fmt,writer_exts,body_str,extra_vars,include_contents,standalone=True,input_files=input_files)
        return apply_eol(out,opts).encode(),False

def render_body(self,doc,opts,fmt,writer_exts):
    if fmt in ("html","html5","html4","slidy","slideous","s5","dzslides","revealjs","chunkedhtml"):
        from .writers.html import write_html
        html_fmt=fmt
        if fmt=="chunkedhtml": html_fmt="html5"
        return write_html(doc,opts,writer_exts,html_fmt)
    if fmt in ("markdown","markdown_github","markdown_mmd","markdown_phpextra","markdown_strict","markua","plain","commonmark","commonmark_x","gfm","ansi"):
        if fmt=="ansi":
            from .writers.ansi import write_ansi
            return write_ansi(doc,opts,writer_exts)
        from .writers.markdown import write_markdown
        return write_markdown(doc,opts,writer_exts,fmt)
    if fmt in ("latex","beamer"):
        from .writers.latex import write_latex
        return write_latex(doc,opts,writer_exts,fmt)
    # Other text writers in writers.other
    from .writers.other import write_other
    return write_other(fmt,doc,opts,writer_exts,self)

def apply_template_if_needed(self,doc,opts,fmt,writer_exts,body_str,extra_vars,include_contents,standalone,input_files=None):
    # Get template text and loader location
    template_text,srcname,base_dir,template_path,is_filesystem_file=self.get_template(opts,fmt)
    context=build_context(doc,opts,fmt,writer_exts,body_str,extra_vars,logger=self.logger,sources=input_files,output_file=opts.output_file,include_contents=include_contents)
    def loader(partial_name,renderer):
        return self.load_partial(partial_name,renderer,base_dir,template_path,is_filesystem_file,fmt)
    rendered=render_template(template_text,context,loader=loader,source_name=srcname,base_dir=base_dir,user_data_dir=self.get_user_data_dir(),template_path=template_path,columns=opts.columns,wrap=opts.wrap,prog=self.prog)
    return rendered

def get_template(self,opts,fmt):
    from .main import TEMPLATE_MAP
    mapped=TEMPLATE_MAP.get(fmt,fmt)
    if opts.template is not None:
        t=opts.template
        # Ignore absolute URL fetch for http templates
        if re.match(r'^[A-Za-z][A-Za-z0-9+.-]*://',t):
            data=self.fetch_url(t); return data.decode('utf-8'),t,None,t,False
        if os.path.isfile(t):
            return self.read_file_bytes(t,"withBinaryFile").decode('utf-8'),t,os.path.dirname(os.path.abspath(t)),t,True
        # Search in user data dir templates (and embedded)
        # Candidate filenames: t as given, and if no extension then t + '.' + writer extension (for html => html not html5, for docx=>docx? Manual examples)
        ext_for_template=fmt  # extension corresponding to writer as per error sample html
        candidates=[]
        candidates.append(t)
        root,ext=os.path.splitext(t)
        if ext=="":
            candidates.append(t+"."+ext_for_template)
        # user templates then embedded data templates/<cand>
        for cand in candidates:
            upath=os.path.join(self.get_user_data_dir(),"templates",cand)
            if os.path.isfile(upath):
                return open(upath,encoding='utf-8').read(),upath,os.path.dirname(os.path.abspath(upath)),upath,True
            data=read_resource(f"templates/{cand}")
            if data is not None:
                return data.decode('utf-8'),cand,None,cand,False
        # Error filename is templates/<last candidate> (extension added if none)
        errname=candidates[-1] if candidates else t
        raise PandocError(f"Could not find data file templates/{errname}\n",97)
    # Default template: user override first
    rel=f"templates/default.{mapped}"
    upath=os.path.join(self.get_user_data_dir(),rel)
    if os.path.isfile(upath):
        return open(upath,encoding='utf-8').read(),upath,os.path.dirname(os.path.abspath(upath)),upath,True
    data=read_resource(rel)
    if data is None:
        raise PandocError(f"Could not find data file templates/default.{fmt}\n",97)
    return data.decode('utf-8'),rel,None,rel,False

def load_partial(self,partial_name,renderer,base_dir,template_path,is_filesystem_file,fmt):
    # partial_name may include extension; if basename has no dot, assume same extension as main template
    from .main import TEMPLATE_MAP
    main_ext=""
    if template_path:
        # default.<ext> etc: extension is suffix after last dot
        m=re.search(r'\.([^./]+)$',template_path)
        if m: main_ext=m.group(1)
    if not main_ext:
        main_ext=TEMPLATE_MAP.get(fmt,fmt)
    pname=partial_name
    if '.' not in os.path.basename(pname):
        pname=pname+"."+main_ext
    # 1 directory containing main template if file
    if is_filesystem_file and base_dir:
        cand=os.path.join(base_dir,pname)
        if os.path.isfile(cand):
            return open(cand,encoding='utf-8').read(),cand,os.path.dirname(os.path.abspath(cand)),cand
    # 2 userdata/templates
    upath=os.path.join(self.get_user_data_dir(),"templates",pname)
    if os.path.isfile(upath):
        return open(upath,encoding='utf-8').read(),upath,os.path.dirname(os.path.abspath(upath)),upath
    # 3 embedded
    data=read_resource(f"templates/{pname}")
    if data is not None:
