    if not opts: return text
    if opts.eol=="crlf":
        return text.replace("\r\n","\n").replace("\n","\r\n")
    return text

def fetch_resource_text(self,path):
    data=fetch_resource(self,path)
    try: return data.decode('utf-8')
    except: return data.decode('utf-8',errors='replace')

def fetch_resource(self,path):
    if re.match(r'^[A-Za-z][A-Za-z0-9+.-]*://',path):
        return self.fetch_url(path)
    # data: URI?
    if path.startswith("data:"):
        import base64, urllib.parse
        m=re.match(r'data:([^;,]+)?(;base64)?,(.*)',path,re.DOTALL)
        if m:
            payload=m.group(3)
            return base64.b64decode(payload) if m.group(2) else urllib.parse.unquote_to_bytes(payload)
    if os.path.isabs(path):
        if os.path.isfile(path):
            with open(path,'rb') as f: return f.read()
        raise PandocError(f"File {path} not found in resource path\n",99)
    for base in self.opts.resource_paths:
        cand=os.path.join(base,path)
        if os.path.isfile(cand):
            with open(cand,'rb') as f: return f.read()
    raise PandocError(f"File {path} not found in resource path\n",99)

def make_pdf(self,text_out,pdf_info,opts):
    engine=pdf_info["engine"]
    exe=engine if '/' in engine else shutil.which(engine)
    if '/' in engine:
        exe=engine if os.path.isfile(engine) and os.access(engine,os.X_OK) else None
    if not exe:
        raise PandocError(f"{engine} not found. Please select a different --pdf-engine or install {engine}\n",47)
    # Attempt a minimal engine run
    fmt=pdf_info["writer_base"]
    ext_map={"latex":"tex","beamer":"tex","context":"tex","html":"html","html5":"html","ms":"ms","typst":"typ"}
    ext=ext_map.get(fmt,"tex")
