        infile=os.path.join(td,"input."+ext)
        with open(infile,'w',encoding='utf-8',newline='') as f: f.write(text_out)
        engine_name=os.path.splitext(os.path.basename(engine))[0]
        outpdf=os.path.join(td,"input.pdf")
        if engine_name in ("pdflatex","lualatex","xelatex","pdflatex-dev","lualatex-dev"):
            cmd=[exe,"-interaction=batchmode","-halt-on-error","-output-directory",td,infile]+opts.pdf_engine_opts
            # Run twice for references
            r=None
            for _ in range(2): r=subprocess.run(cmd,cwd=td,capture_output=True)
        elif engine_name=="latexmk":
            cmd=[exe,"-pdf","-output-directory="+td,infile]+opts.pdf_engine_opts; r=subprocess.run(cmd,cwd=td,capture_output=True)
        elif engine_name=="tectonic":
            cmd=[exe,infile,"-o",td]+opts.pdf_engine_opts; r=subprocess.run(cmd,cwd=td,capture_output=True)
        elif engine_name=="context":
            cmd=[exe,"--batchmode","--result=input","--path="+td]+opts.pdf_engine_opts+[infile]; r=subprocess.run(cmd,cwd=td,capture_output=True)
        elif engine_name in ("wkhtmltopdf","weasyprint","prince","pagedjs-cli"):
            if engine_name=="weasyprint": cmd=[exe,infile,outpdf]+opts.pdf_engine_opts
            elif engine_name=="prince": cmd=[exe,infile,"-o",outpdf]+opts.pdf_engine_opts
            elif engine_name=="pagedjs-cli": cmd=[exe,infile,"-o",outpdf]+opts.pdf_engine_opts
            else: cmd=[exe]+opts.pdf_engine_opts+[infile,outpdf]
            r=subprocess.run(cmd,cwd=td,capture_output=True)
        elif engine_name in ("groff","pdfroff"):
            if engine_name=="groff": cmd=[exe,"-ms","-Tpdf"]+opts.pdf_engine_opts+[infile]
            else: cmd=[exe]+opts.pdf_engine_opts+[infile]
            r=subprocess.run(cmd,cwd=td,capture_output=True)
            if r and r.stdout.startswith(b"%PDF"):
                return r.stdout
        elif engine_name=="typst":
            cmd=[exe,"compile"]+opts.pdf_engine_opts+[infile,outpdf]; r=subprocess.run(cmd,cwd=td,capture_output=True)
        else:
            r=subprocess.run([exe]+opts.pdf_engine_opts+[infile],cwd=td,capture_output=True)
        if os.path.isfile(outpdf):
            with open(outpdf,'rb') as f: return f.read()
        log=b""
        logfile=os.path.join(td,"input.log")
        if os.path.isfile(logfile):
            with open(logfile,'rb') as f: log=f.read()
        out=(r.stdout+r.stderr+log).decode(errors='replace') if r else ""
        raise PandocError(out if out.endswith("\n") else out+"\n",43)

