def run_json_filter(self,path,doc,writer_base):
    # locate executable
    exe=None
    # If path has / or is a file relative
    candidates=[]
    if '/' in path or os.path.isfile(path): candidates.append(path)
    candidates.append(os.path.join(self.get_user_data_dir(),"filters",path))
    found=None
    for cand in candidates:
        if os.path.isfile(cand): found=cand; break
    if found is None:
        found=shutil.which(path)
    if found is None:
        raise PandocError(f"Error running filter {path}:\nCould not find executable {path}\n",83)
    # Execution: if file is executable run it; if not executable, pandoc may try interpreting based on shebang? If not executable and extension .py, etc., run with interpreter? We'll attempt direct and if PermissionError use shebang/python.
    from .writers.json_native_xml import write_json
    in_json=write_json(doc,self.opts,standalone=True)
