        r=subprocess.run(cmd,input=in_json.encode(),capture_output=True,env=env)
    except OSError as e:
        raise PandocError(f"Error running filter {path}:\n{e}\n",83)
    if r.returncode!=0:
        err=r.stderr.decode(errors='replace')
        raise PandocError(f"Error running filter {path}:\n{err}" if err.endswith("\n") or err=="" else f"Error running filter {path}:\n{err}\n",83)
    if not r.stdout.strip():
        raise PandocError(f"Error running filter {path}:\nFilter returned empty output\n",83)
    try:
        from .readers.jsonreader import parse_json_doc
        return parse_json_doc(r.stdout.decode())
    except PandocError as e:
        # Some filters output a JSON list in older API - pandoc filters top-level JSON is like pandoc format - treat as error
        raise PandocError(f"Error running filter {path}:\n{e.message}",83)
