def read_document(self,sources,opts,reader_base,reader_exts,reader_custom):
    # Binary formats
    if reader_base in ("docx","odt","epub","pptx","xlsx"):
        from .readers.binary import read_binary_format
        docs=[]
        for name,data in sources:
            if isinstance(data,str): data=data.encode()
            docs.append(read_binary_format(data,reader_base,opts,reader_exts,name,self))
        return merge_docs(docs)
    # Text decode each
    texts=[]
    for name,data in sources:
