            try:
                text=data.decode('utf-8')
            except UnicodeDecodeError as e:
                # Pandoc UTF8 error message format approximate
                raise PandocError(f"Cannot decode byte '\\x{data[e.start]:02x}': Data.Text.Internal.Encoding.decodeUtf8: Invalid UTF-8 stream\n",92)
        else: text=data
        if text.startswith('\ufeff'): text=text[1:]
