    # Concatenate: ensure each ends with newline, join with blank line, append extra newline at very end
    parts=[]
    for name,text in texts:
        if text and not text.endswith("\n"): text+="\n"
        parts.append(text)
    combined="\n".join(parts)
    # Already each has final nl, join adds one blank between and also if multiple, etc. Add final extra newline as pandoc does for text reader input (sources)
    if combined and not combined.endswith("\n\n"): combined+="\n"
    source_name=texts[0][0] if len(texts)==1 and texts[0][0] not in ("","-") else ""
