        else:
            # read shebang
            with open(found,'rb') as f: first=f.readline().decode(errors='ignore')
            if first.startswith("#!"):
                parts=first[2:].strip().split(); cmd=parts+[found,fmt_arg]
            elif found.endswith(".py"):
