    ref={"id":r.get('id',''),"type":typemap.get(r.get('type','misc'),r.get('type','misc'))}
    # author parse: split `and`, parse Last, First
    for key,target in [("title","title"),("journal","container-title"),("publisher","publisher"),("volume","volume"),("number","issue"),("pages","page"),("doi","DOI"),("url","URL"),("isbn","ISBN"),("issn","ISSN")]:
