import re
def parse_bibtex(text,fmt="bibtex"):
    entries=[]; i=0; n=len(text)
    while i<n:
        at=text.find('@',i)
        if at==-1: break
        m=re.match(r'@([A-Za-z]+)\s*([{(])',text[at:])
        if not m: i=at+1; continue
        typ=m.group(1).lower(); opench=m.group(2); closech='}' if opench=='{' else ')'
        start=at+len(m.group(0))
        # string/comment/preamble skipped with balanced
        depth=1; j=start; in_str=False
        while j<n and depth>0:
            c=text[j]
            if c=='\\': j+=2; continue
            if c=='"': in_str=not in_str
            elif not in_str and c==opench: depth+=1
            elif not in_str and c==closech: depth-=1
            j+=1
        content=text[start:j-1] if depth==0 else text[start:]
        if typ in ("string","preamble","comment"):
            i=j; continue
        # first comma at depth0
        parts=split_top(content,',')
        eid=parts[0].strip() if parts else ""
        fields={}
        for part in parts[1:]:
            if '=' in part:
                k,v=part.split('=',1); fields[k.strip().lower()]=strip_bib_value(v.strip())
        entries.append({"type":typ,"id":eid,"fields":fields}); i=j
    return entries
def split_top(s,sep):
    parts=[]; depth=0; in_str=False; cur=""; i=0
    while i<len(s):
        c=s[i]
        if c=='\\' and i+1<len(s): cur+=s[i:i+2];i+=2;continue
        if c=='"': in_str=not in_str; cur+=c;i+=1;continue
        if not in_str and c in '{(':depth+=1
        if not in_str and c in '})':depth-=1
        if c==sep and depth==0 and not in_str: parts.append(cur);cur="";i+=1;continue
        cur+=c;i+=1
    if cur.strip(): parts.append(cur)
    return parts
def strip_bib_value(v):
    v=v.strip()
    # Concatenation with # of strings / macros simplified concatenation
    if '#' in v:
        return "".join(strip_bib_value(x) for x in v.split('#'))
    if len(v)>=2 and v[0]=='"' and v[-1]=='"': return v[1:-1]
    if len(v)>=2 and v[0]=='{' and v[-1]=='}': return v[1:-1]
    return v
