import re
from ..ast import B,I,empty_attr
def parse_typst(text,opts,exts,app):
    # Convert simple Typst to markdown-ish and parse
    lines=[]
    for line in text.splitlines():
        # #set/#let/#show lines drop (except metadata?)
        if re.match(r'^\s*#(set|let|show)\b',line): continue
        m=re.match(r'^(=+)\s+(.*)',line)
        if m: line='#'*len(m.group(1))+' '+m.group(2)
        # Lists - / + 
        # Emph _x_ and strong *x*: translate *...* to **...**
        line=re.sub(r'(?<!\*)\*([^*]+)\*(?!\*)',r'**\1**',line)
        # raw `code` same; links #link("url")[text]
        line=re.sub(r'#link\("([^"]+)"\)\[([^\]]+)\]',r'[\2](\1)',line)
        line=re.sub(r'#(?:emph|strong)\[([^\]]+)\]',lambda m: ('*'+m.group(0).split('[',1)[1][:-1]+'*') if 'emph' in m.group(0) else ('**'+m.group(0).split('[',1)[1][:-1]+'**'),line)
        lines.append(line)
    from .markdown import parse_markdown
    doc,ctx=parse_markdown("\n".join(lines)+"\n",opts,exts,"typst")
    return doc
