        elif t=="Emph":out+=f'<w:r><w:rPr><w:i /></w:rPr><w:t>{esc(stringify(x["c"]))}</w:t></w:r>'
        elif t=="Strong":out+=f'<w:r><w:rPr><w:b /></w:rPr><w:t>{esc(stringify(x["c"]))}</w:t></w:r>'
