                    docs.append(Cr());docs.append(Cat([Text(".FS"),Cr(),self.blocks(nb),Cr(),Text(".FE")]))
            return Cat(docs)
        if t=="Header":
            lvl,attr,inls=c
            text=self.inlines(inls)
            if self.ms:
                if self.opts and self.opts.number_sections:return Cat([Text(f".NH {lvl}"),Cr(),text])
                return Cat([Text(f".SH {lvl}"),Cr(),text])
            cmd=".SH" if lvl==1 else ".SS"
            return Cat([Text(cmd+" "),text])
        if t=="BlockQuote":
            if self.ms:return Cat([Text(".QS"),Cr(),self.blocks(c),Cr(),Text(".QE")])
            return Cat([Text(".RS"),Cr(),self.blocks(c),Cr(),Text(".RE")])
        if t=="CodeBlock":return self.codeblock(c[0],c[1])
        if t=="RawBlock":
            fmt=c[0] if isinstance(c[0],str) else ""
            return Literal(c[1]) if fmt in ("man","ms","groff") else Empty()
        if t=="BulletList":return self.list_doc(c,False)
        if t=="OrderedList":return self.list_doc(c,True)
        if t=="DefinitionList":
            docs=[]
            for term,defs in c:
                for d in defs:
                    if self.ms:
                        docs.append(Cat([Cat([Text('.IP "'),self.inlines(term),Text('" 3')]),Cr(),self.blocks(d),Cr(),Text(".RS 3"),Cr(),Text(".RE")]))
                        # Term should be bold in ms: our inlines render term normally; expected \f[B]Term\f[R] - wrap term in Strong rendering manually later? Use Strong node construction
                    else:
                        docs.append(Cat([Text(".TP"),Cr(),self.inlines(term),Cr(),self.blocks(d)]))
            return join_docs(docs,Cr())
        if t=="LineBlock":return join_docs([self.inlines(x) for x in c],Cr())
        if t=="HorizontalRule":
            if self.ms:return Text(".HLINE")
            return Cat([Text(".PP"),Cr(),Text("   *   *   *   *   *")])
        if t=="Table":return self.table_doc(b)
        if t=="Div":return self.blocks(c[1])
        if t=="Figure":return self.blocks(c[2])
        return Empty()
    def codeblock(self,attr,code):
        if self.ms:
            attrv,classes,kvs=attr if attr else ("",[],[]);lang=classes[0] if classes else ""
            style=self.opts.syntax_highlighting if self.opts else "default"
            lines=[]
            if lang and style not in ("none","idiomatic"):
                from ..highlight import tokenize_code
                toks=tokenize_code(code,lang)
                for line in toks:
                    seg=""
                    for typ,tok in line:
                        cmd=(typ+"Tok") if typ else "NormalTok"
                        seg+=rf'\*[{cmd} "{esc_roff_ms_token(tok)}"]'
                    lines.append(seg)
                content="\n".join(lines)
                return Literal(".IP\n.nf\n\\f[C]\n"+content+"\n\\f[]\n.fi")
            return Literal(".IP\n.nf\n\\f[C]\n"+esc_roff(code)+"\n\\f[]\n.fi")
        return Literal(".IP\n.EX\n"+esc_roff(code)+"\n.EE")
    def list_doc(self,data,ordered):
        if ordered:
            lattr,items=data;start=lattr[0]
            markers=[]
            for idx in range(len(items)):
                n=start+idx
                if self.ms:markers.append(f'"{n}.'.rjust(4)+'"')
                else:markers.append(f'"{n}."')
        else:
            items=data;markers=[r'\(bu']*len(items)
        indent=3 if self.ms else 2
        if ordered and self.ms:indent=4
        if ordered and not self.ms:indent=3
        docs=[]
        old_inlist=self.in_list;self.in_list=True
        for marker,item in zip(markers,items):
            # item blocks joining with Cr; nested list needs .RS indent
            docs_item=[]
            first=True
            for blk in item:
                if blk.get("t") in ("BulletList","OrderedList"):
                    docs_item.append(Cat([Text(f".RS {indent}"),Cr(),self.block(blk),Cr(),Text(".RE")]))
                else:
                    docs_item.append(self.block(blk))
            inner=join_docs(docs_item,Cr())
            docs.append(Cat([Text(f".IP {marker} {indent}"),Cr(),inner]))
        self.in_list=old_inlist
        return join_docs(docs,Cr())
    def table_doc(self,b):
        attr,caption,specs,head,bodies,foot=b["c"]
        aligns=[]
        for a,cw in specs:aligns.append({'AlignLeft':'l','AlignRight':'r','AlignCenter':'c','AlignDefault':'l'}[a["t"]])
        lines=[]
        if self.ms:
            lines.append(".PP");lines.append(".na")
            lines.append(".TS");lines.append("delim(@@) tab(\t);")
        else:
            lines.append(".PP");lines.append(".TS");lines.append("tab(@);")
        lines.append(" ".join(aligns)+".")
        def celltxt(blocks):
            return render(self.blocks(blocks),columns=100000,wrap="none").strip()
        allrows=[]
        if head[1]:allrows.append(('head',head[1][0]))
        for _,_,inter,rows in bodies:
            for r in inter+rows:allrows.append(('body',r))
        for kind,row in allrows:
            cells=[celltxt(c[4]) for c in row[1]]
            if self.ms:
                lines.append("\t".join(f"T{{\n{c}\nT}}" for c in cells))
            else:
                lines.append("@".join(f"T{{\n{c}\nT}}" for c in cells))
            if kind=='head':lines.append("_")
