        if self.ms:lines.append(".ad")
        return Literal("\n".join(lines))
    def notes_section(self):
        docs=[Text(".SH NOTES")]
        for idx,blocks in enumerate(self.footnotes,1):
            docs.append(Cat([Text(f".SS [{idx}]"),Cr(),Text(".PP"),Cr(),self.blocks(blocks)]))
        return join_docs(docs,Cr())
    def inlines(self,inls):return Cat([self.inline(x) for x in inls])
    def inline(self,x):
        t=x.get("t");c=x.get("c")
        if t=="Str":return Text(esc_roff(c))
        if t=="Space":return BS()
        if t=="SoftBreak":return SoftBreak()
        if t=="LineBreak":return Cat([Text(r"\c"),Cr()])
        if t=="Emph":return Cat([Text(r"\f[I]"),self.inlines(c),Text(r"\f[R]")])
        if t=="Strong":return Cat([Text(r"\f[B]"),self.inlines(c),Text(r"\f[R]")])
        if t=="Code":return Cat([Text(r"\f[CR]"),Text(esc_roff(c[1])),Text(r"\f[R]")])
        if t=="Strikeout":
            if self.ms:return Cat([Text(r"\m[strikecolor]"),self.inlines(c),Text(r"\m[]")])
            return Cat([Text("[STRIKEOUT:"),self.inlines(c),Text("]")])
        if t=="Superscript":
            if self.ms:return Cat([Text(r"\*{"),self.inlines(c),Text(r"\*}")])
            return Cat([Text("^"),self.inlines(c),Text("^")])
        if t=="Subscript":
            if self.ms:return Cat([Text(r"\*<"),self.inlines(c),Text(r"\*>")])
            return Cat([Text("~"),self.inlines(c),Text("~")])
        if t in ("Underline","SmallCaps"):return self.inlines(c)
        if t=="Quoted":return Cat([Text("“" if c[0]["t"]=="DoubleQuote" else "‘"),self.inlines(c[1]),Text("”" if c[0]["t"]=="DoubleQuote" else "’")])
        if t=="Math":
            tex=c[1]
            if self.ms:
                return Text("@"+tex_to_eqn(tex)+"@")
            return self.inlines(tex_math_to_inlines(tex))
        if t=="Link":
            attr,inls,target=c;url=target[0]
            if self.ms:return self.inlines(inls)
            if url.startswith('#'):return self.inlines(inls)
            # man UR macro with \c line continuation before and after macro lines
            return Cat([Text("\\c"),Cr(),Text(f".UR {url}"),Cr(),self.inlines(inls),Cr(),Text(".UE \\c"),Cr()])
        if t=="Image":
            alt=stringify(c[1]).strip();src=c[2][0]
            if self.ms:
                core=f"[IMAGE: {alt}]" if alt else "[IMAGE]"
                return Cat([Text(core),BS(),Text(r'\"'),Text(f'"{src}"')])
            return Text(f"[IMAGE: {alt}]" if alt else "[IMAGE]")
        if t=="Note":
            if self.ms:
                if not hasattr(self,"_pending_ms_notes"):self._pending_ms_notes=[]
                self._pending_ms_notes.append(c);return Text(r"\**")
            self.footnotes.append(c);return Text(f"[{len(self.footnotes)}]")
        if t=="RawInline":
            fmt=c[0] if isinstance(c[0],str) else "";return Text(c[1]) if fmt in ("man","ms","groff") else Empty()
        if t=="Span":return self.inlines(c[1])
        if t=="Cite":return self.inlines(c[1])
        return Empty()

def esc_roff_ms_token(s):
    return s.replace('\\','\\e').replace('"',r'\(dq')
def tex_to_eqn(tex):
    # x^2 -> x sup 2, a_i -> a sub i, frac
    s=tex
    s=re.sub(r'\\frac\{([^{}]*)\}\{([^{}]*)\}',r'{\1} over {\2}',s)
    s=re.sub(r'\^\{([^{}]*)\}',r' sup {\1}',s);s=re.sub(r'_\{([^{}]*)\}',r' sub {\1}',s)
    s=re.sub(r'\^(\S)',r' sup \1',s);s=re.sub(r'_(\S)',r' sub \1',s)
    s=re.sub(r'\\([A-Za-z]+)',r'\1',s);return s.replace('{','').replace('}','')
def tex_math_to_inlines(tex):
    # Return simple inlines for man math: variables as Emph single letters, scripts as ^ etc via AST construction in caller? This helper is used in a Doc context where it must return inlines for self.inlines - but our Roff inline Math calls self.inlines(tex_math_to_inlines(tex)) (wrong signature in code?). We'll handle in RoffWriter via returning Text in patch later.
    return []

# Patch roff math handling after class definition by replacing method behavior at runtime in write function wrapper below.
_orig_roff_inline=RoffWriter.inline
def _roff_inline_patched(self,x):
    if x.get("t")=="Math" and not self.ms:
        tex=x["c"][1]
        # simple: each letter italic via \f[I]letter\f[R], ^ and _ as literal
        out=[];i=0
        while i<len(tex):
            ch=tex[i]
            if ch.isalpha():out.append(Text(rf"\f[I]{ch}\f[R]"));i+=1
            elif ch.isspace():out.append(BS());i+=1
            else:out.append(Text(esc_roff(ch)));i+=1
        return Cat(out)
    return _orig_roff_inline(self,x)
RoffWriter.inline=_roff_inline_patched

# ---------- ConTeXt ----------
class ContextWriter:
    def __init__(self,opts,exts):
        self.opts=opts;self.exts=exts or {}
    def write(self,doc):
        # Transform headings into nested sectionlevels
        sections=make_context_sections(doc.get("blocks",[]))
        out=render(self.blocks(sections,section_depth=0),columns=self.opts.columns if self.opts else 72,wrap=self.opts.wrap if self.opts else "auto")
        return out,{}
    def blocks(self,blocks,section_depth=0):return join_docs([self.block(b) for b in blocks],Blank())
    def block(self,b):
        t=b.get("t");c=b.get("c")
        if t=="_Section":
            title,attr,children=b["title"],b["attr"],b["children"]
            title_s=render(self.inlines(title),columns=100000,wrap="none")
            docs=[Text(rf"\startsectionlevel[title={{{title_s}}},reference={{{attr[0]}}}]")]
            if children:docs.append(self.blocks(children))
            docs.append(Text(r"\stopsectionlevel"))
            return join_docs(docs,Blank())
        if t in ("Para","Plain"):return self.inlines(c)
        if t=="Header":return self.inlines(c[2]) # should be in sections
        if t=="BlockQuote":return Cat([Text(r"\startblockquote"),Cr(),self.blocks(c),Cr(),Text(r"\stopblockquote")])
        if t=="CodeBlock":
            attr,code=c;lang=attr[1][0] if attr and attr[1] else ""
            if lang:
                from ..highlight import tokenize_code
                lines=[]
                for line in tokenize_code(code,lang):
                    seg="".join((f"\\{typ+'Tok'}{{{esc_context_highlight(tok)}}}" if typ else f"\\NormalTok{{{esc_context_highlight(tok)}}}" ) for typ,tok in line)
                    lines.append(seg)
                body="\n".join(r"/BTEX"+l+r"/ETEX" if False else l for l in lines)
                # Observed one line code: /BTEX.../ETEX wraps whole highlighted line(s)? It had only one line as /BTEX.../ETEX on one line.
                alltok="/BTEX"+"".join(lines)+"/ETEX" if len(lines)==1 else "\n".join("/BTEX"+l+"/ETEX" for l in lines)
                return Literal("\\starthighlighting\n"+alltok+"\n\\stophighlighting")
            return Literal("\\starttyping\n"+code+"\n\\stoptyping")
        if t=="BulletList":return self.list_doc(c,False)
        if t=="OrderedList":return self.list_doc(c,True)
        if t=="DefinitionList":
            docs=[]
            for term,defs in c:
                for d in defs:
                    term_s=render(self.inlines(term),columns=100000,wrap="none")
                    docs.append(Cat([Text(rf"\startdescription{{{term_s}}}"),Cr(),Nest("  ",self.blocks(d)),Cr(),Text(r"\stopdescription")]))
            return join_docs(docs,Blank())
        if t=="HorizontalRule":return Text(r"\thinrule")
        if t=="LineBlock":return join_docs([self.inlines(x) for x in c],Cr())
        if t=="RawBlock":
            fmt=c[0] if isinstance(c[0],str) else "";return Literal(c[1]) if fmt in ("context","tex") else Empty()
        if t=="Table":return self.table_doc(b)
        if t=="Div":return self.blocks(c[1])
        if t=="Figure":
            # \startplacefigure etc approximate
            return self.blocks(c[2])
        return Empty()
    def list_doc(self,data,ordered):
        if ordered:
            lattr,items=data;style=lattr[1]["t"];sym={"Decimal":"n","LowerAlpha":"a","UpperAlpha":"A","LowerRoman":"r","UpperRoman":"R"}.get(style,"n")
            start=f"\\startenumerate[{sym},packed][stopper=.]";stop=r"\stopenumerate"
        else:
            items=data;start=r"\startitemize[packed]";stop=r"\stopitemize"
        loose=any(any(x.get("t")=="Para" for x in item) for item in items)
        if not loose:
            pass
        else:
            start=start.replace(",packed","").replace("[packed]","")
        docs=[Text(start)]
        for item in items:
            docs.append(Cat([Text(r"\item"),Cr(),Nest("  ",self.blocks(item))]))
        docs.append(Text(stop));return join_docs(docs,Cr())
    def table_doc(self,b):
        attr,caption,specs,head,bodies,foot=b["c"]
        lines=[]
        cap_txt=""
        if caption[1]:cap_txt=stringify(caption[1]).strip()
        if cap_txt:lines.append(rf"\startplacetable[title={{{cap_txt}}}]")
        else:lines.append(r"\startplacetable[location=none]")
        lines.append(r"\startxtable")
        alignmap={"AlignRight":"left","AlignLeft":"right","AlignCenter":"middle","AlignDefault":"right"}
        def rows_of(rowlist):
            out=[]
            for row in rowlist:
                out.append(r"\startxrow")
                for idx,cell in enumerate(row[1]):
                    align=alignmap[specs[idx][0]["t"]]
                    txt=cell_text_context(self,cell[4])
                    out.append(rf"\startxcell[align={align}] {txt} \stopxcell")
                out.append(r"\stopxrow")
            return out
        if head[1]:
            lines.append(r"\startxtablehead[head]");lines.append(r"\startxrowgroup[lastrow]");lines.extend(rows_of(head[1]));lines.append(r"\stopxrowgroup");lines.append(r"\stopxtablehead")
        for battr,rhc,inter,rows in bodies:
            lines.append(r"\startxtablebody[body]");lines.append(r"\startxrowgroup[lastrow]");lines.extend(rows_of(inter+rows));lines.append(r"\stopxrowgroup");lines.append(r"\stopxtablebody")
        lines.append(r"\startxtablefoot[foot]")
        if foot[1]:lines.extend(rows_of(foot[1]))
        lines.append(r"\stopxtablefoot");lines.append(r"\stopxtable");lines.append(r"\stopplacetable")
        return Literal("\n".join(lines))
    def inlines(self,inls):return Cat([self.inline(x) for x in inls])
    def inline(self,x):
        t=x.get("t");c=x.get("c")
        if t=="Str":return Text(esc_context(c))
        if t=="Space":return BS()
        if t=="SoftBreak":return SoftBreak()
        if t=="LineBreak":return Cat([Text(r"\\"),Cr()])
        if t=="Emph":return Cat([Text(r"{\em "),self.inlines(c),Text("}")])
        if t=="Strong":return Cat([Text(r"{\bf "),self.inlines(c),Text("}")])
        if t=="Code":return Text(r"\type{"+c[1]+"}")
        if t=="Strikeout":return Cat([Text(r"\overstrikes{"),self.inlines(c),Text("}")])
        if t=="Superscript":return Cat([Text(r"\high{"),self.inlines(c),Text("}")])
        if t=="Subscript":return Cat([Text(r"\low{"),self.inlines(c),Text("}")])
        if t=="SmallCaps":return Cat([Text(r"{\sc "),self.inlines(c),Text("}")])
        if t=="Underline":return Cat([Text(r"\underbar{"),self.inlines(c),Text("}")])
        if t=="Quoted":return Cat([Text("“" if c[0]["t"]=="DoubleQuote" else "‘"),self.inlines(c[1]),Text("”" if c[0]["t"]=="DoubleQuote" else "’")])
        if t=="Math":return Text(f"${c[1]}$")
        if t=="Link":
            attr,inls,target=c
            if target[0].startswith('#'):return Cat([Text(r"\goto{"),self.inlines(inls),Text(f"}}[{target[0][1:]}]")])
            return Cat([Text(r"\goto{"),self.inlines(inls),Text(f"}}[url({target[0]})]")])
        if t=="Image":return Text(r"{\externalfigure["+c[2][0]+"]}")
        if t=="Note":return Cat([Text(r"\footnote{"),self.blocks(c),Text("}")])
        if t=="RawInline":
            fmt=c[0] if isinstance(c[0],str) else "";return Text(c[1]) if fmt in ("context","tex") else Empty()
        if t=="Span":return self.inlines(c[1])
        if t=="Cite":return self.inlines(c[1])
        return Empty()
def make_context_sections(blocks):
    root=[];stack=[(0,root)]
    for b in blocks:
        if b.get("t")=="Header":
            lvl=b["c"][0]
            while len(stack)>1 and stack[-1][0]>=lvl:stack.pop()
            sec={"t":"_Section","title":b["c"][2],"attr":b["c"][1],"children":[]}
            stack[-1][1].append(sec);stack.append((lvl,sec["children"]))
        else:stack[-1][1].append(b)
    return root
def esc_context(s):
    reps={'\\':'\\textbackslash{}','{':'\\{','}':'\\}','$':'\\$','&':'\\&','%':'\\%','#':'\\#','_':'\\_','^':'\\textasciicircum{}','~':'\\textasciitilde{}'}
    return ''.join(reps.get(ch,ch) for ch in s)
def esc_context_highlight(s):return esc_context(s)
def cell_text_context(writer,blocks):
    if len(blocks)==1 and blocks[0].get("t") in ("Plain","Para"):return render(writer.inlines(blocks[0]["c"]),columns=100000,wrap="none")
    return stringify(blocks).strip()

# ---------- Texinfo ----------
class TexinfoWriter:
    def __init__(self,opts,exts):
        self.opts=opts;self.exts=exts or {};self.node_names=[]
    def write(self,doc):
        meta=doc.get("meta",{})
        title=stringify(meta.get("title",{}).get("c",[])).strip() if "title" in meta else "Top"
        if not title:title="Top"
        blocks=doc.get("blocks",[])
        # Build section tree for menus/nodes
        sections=make_texinfo_sections(blocks)
        docs=[Cat([Text("@node Top"),Cr(),Text(f"@top {esc_texinfo(title)}")])]
        top_children=[s for s in sections if s.get("t")=="_Section"]
        if top_children:
            menu=[Text("@menu")]
            for s in top_children:menu.append(Text(f"* {node_name(s)}::"))
            menu.append(Text("@end menu"));docs.append(join_docs(menu,Cr()))
        for item in sections:
            docs.append(self.block(item))
        out=render(join_docs(docs,Blank()),columns=self.opts.columns if self.opts else 72,wrap=self.opts.wrap if self.opts else "auto")
        extra={}
        if any_strike(doc):extra["strikeout"]=True
        return out,extra
    def blocks(self,blocks):return join_docs([self.block(b) for b in blocks],Blank())
    def block(self,b):
        t=b.get("t");c=b.get("c")
        if t=="_Section":
            title=b["title"];lvl=b["level"];name=node_name(b);cmd={1:"chapter",2:"section",3:"subsection",4:"subsubsection"}.get(lvl,"subsubsection")
            docs=[Cat([Text(f"@node {esc_texinfo(name)}"),Cr(),Cat([Text(f"@{cmd} "),self.inlines(title)])])]
            children=b["children"]
            subsections=[x for x in children if x.get("t")=="_Section"]
            if subsections:
                # Menu appears after content before subsections according to texinfo writer: it inserts menu right after chapter heading before first content? In std, menu is after chapter heading and paragraph before subheading, actually menu comes after the intro para. It is generated before subsections at point of first subsection.
                # We'll render children sequentially and insert menu before first subsection.
                rendered=[]
                inserted=False
                for child in children:
                    if child.get("t")=="_Section" and not inserted:
                        menu=[Text("@menu")]+[Text(f"* {node_name(s)}::") for s in subsections]+[Text("@end menu")]
                        rendered.append(join_docs(menu,Cr()));inserted=True
                    rendered.append(self.block(child))
                docs.extend(rendered)
            else:
                docs.append(self.blocks(children))
            return join_docs(docs,Blank())
        if t in ("Para","Plain"):return self.inlines(c)
        if t=="BlockQuote":return Cat([Text("@quotation"),Cr(),self.blocks(c),Cr(),Text("@end quotation")])
        if t=="CodeBlock":return Literal("@verbatim\n"+c[1]+"\n@end verbatim")
        if t=="BulletList":return self.list_doc(c,False)
        if t=="OrderedList":return self.list_doc(c,True)
        if t=="DefinitionList":
            docs=[Text("@table @asis")]
            for term,defs in c:
                for d in defs:
                    docs.append(Cat([Cat([Text("@item "),self.inlines(term)]),Blank(),self.blocks(d)]))
            docs.append(Text("@end table"));return join_docs(docs,Cr())
        if t=="HorizontalRule":return Literal("@iftex\n@bigskip@hrule@bigskip\n@end iftex\n@ifnottex\n"+"-"*(self.opts.columns if self.opts else 72)+"\n@end ifnottex")
        if t=="RawBlock":
            fmt=c[0] if isinstance(c[0],str) else "";return Literal(c[1]) if fmt=="texinfo" else Empty()
        if t=="Table":return self.table_doc(b)
        if t=="LineBlock":return join_docs([self.inlines(x) for x in c],Cr())
        if t=="Div":return self.blocks(c[1])
        if t=="Figure":return self.blocks(c[2])
        return Empty()
    def list_doc(self,data,ordered):
        if ordered:
            lattr,items=data;docs=[Text("@enumerate ")]
        else:items=data;docs=[Text("@itemize")]
        for item in items:
            docs.append(Cat([Text("@item"),Cr(),self.blocks(item)]))
        docs.append(Text("@end enumerate" if ordered else "@end itemize"))
        # Texinfo nested lists: nested list appears inside item before @end, our blocks() joins with Blank resulting blank line before nested list then blank after nested before end - original has blank lines around.
        return join_docs(docs,Cr())
    def table_doc(self,b):
        attr,caption,specs,head,bodies,foot=b["c"]
        header=[]
        if head[1]:header=[cell_text_texinfo(self,c[4]) for c in head[1][0][1]]
        rows=[]
        for _,_,inter,rr in bodies:
            for r in inter+rr:rows.append([cell_text_texinfo(self,c[4]) for c in r[1]])
        templates=" ".join("{"+h+"}" for h in header) if header else ""
        lines=[f"@multitable {templates} "]
        if header:
            lines.append("@headitem "); 
            for idx,h in enumerate(header):lines.append(("" if idx==0 else " @tab ")+h)
        for r in rows:
            lines.append("@item ")
            for idx,cell in enumerate(r):lines.append(("" if idx==0 else " @tab ")+cell)
        lines.append("@end multitable")
        return Literal("\n".join(lines))
