def esc_roff(s):
    # Escapes in groff text
    out=""
    for ch in s:
        if ch=='\\': out+=r'\e'
        elif ch=='-': out+=r'\-'
        elif ch=='"': out+=r'\(dq'
        elif ch=="'": out+=r'\(aq'
        else: out+=ch
    return out
