def math_plain_docbook(writer,tex):
    # simple letters italic etc using writer inline methods by converting TeX into inlines through our HTML tex helper logic simplified
    docs=[];i=0
    while i<len(tex):
        ch=tex[i]
        if ch.isalpha():docs.append(xml_elem("emphasis",[],Text(ch),block=False));i+=1
        elif ch in '^_':
            tag="superscript" if ch=='^' else "subscript";i+=1
            arg=tex[i] if i<len(tex) else "";i+=1;docs.append(xml_elem(tag,[],Text(arg),block=False))
        elif ch.isspace():docs.append(BS());i+=1
        else:docs.append(Text(esc_xml(ch)));i+=1
    return Cat(docs)

