    def block(self,b):
        t=b.get("t");c=b.get("c")
        if t=="_Section":
            attrs=[("type",f"level{b['level']}")]
            if b["attr"] and b["attr"][0]:attrs.append(("xml:id",b["attr"][0]))
            docs=[xml_elem("head",[],self.inlines(b["title"]),block=False)]
            if b["children"]:docs.append(self.blocks(b["children"]))
            return xml_elem("div",attrs,join_docs(docs,Cr()),block=True)
        if t in ("Para","Plain"):return xml_elem("p",[],self.inlines(c),block=False)
        if t=="BlockQuote":
            # TEI quote element contains blocks but in fragment output earlier block quote was just a paragraph with style? Std TEI snippet needed
            return xml_elem("quote",[],self.blocks(c),block=True)
        if t=="CodeBlock":
