        if t=="HorizontalRule":return xml_open("milestone",[("unit","undefined"),("type","separator"),("rendition","line")],self_close=True)
        if t=="Table":
            attr,caption,specs,head,bodies,foot=b["c"];rows=[]
            if head[1]:
                for row in head[1]:rows.append(xml_elem("row",[("role","label")],join_docs([xml_elem("cell",[],xml_elem("p",[],self.inlines(cell[4][0]["c"]) if cell[4] else Empty(),block=False),block=False) for cell in row[1]],Cr()),block=True))
            for _,_,inter,bodyrows in bodies:
                for row in inter+bodyrows:rows.append(xml_elem("row",[],join_docs([xml_elem("cell",[],xml_elem("p",[],self.inlines(cell[4][0]["c"]) if cell[4] else Empty(),block=False),block=False) for cell in row[1]],Cr()),block=True))
            return xml_elem("table",[],join_docs(rows,Cr()),block=True)
        if t=="Div":return self.blocks(c[1])
        if t=="Figure":return self.blocks(c[2])
        if t=="LineBlock":return xml_elem("lg",[],join_docs([xml_elem("l",[],self.inlines(x),block=False) for x in c],Cr()),block=True)
        if t=="RawBlock":
            fmt=c[0] if isinstance(c[0],str) else "";return Literal(c[1]) if fmt in ("tei","xml") else Empty()
        return Empty()
    def inlines(self,inls):return Cat([self.inline(x) for x in inls])
    def inline(self,x):
        t=x.get("t");c=x.get("c")
        if t=="Str":return Text(esc_xml(c))
        if t=="Space":return BS()
        if t=="SoftBreak":return SoftBreak()
