# ---------- XML helpers ----------
def xml_open(name,attrs=None,self_close=False):
    attrs=attrs or []
    parts=[Text(f"<{name}")]
    for k,v in attrs:
        if v is None: continue
        parts.append(BS());parts.append(Text(f'{k}="{esc_xml_attr(str(v))}"'))
    if self_close:parts.append(Text(" />"))
    else:parts.append(Text(">"))
    return Cat(parts)
def xml_elem(name,attrs,inner,block=True):
    if block:
        return Cat([xml_open(name,attrs),Cr(),Nest("  ",inner),Cr(),Text(f"</{name}>")])
    return Cat([xml_open(name,attrs),inner,Text(f"</{name}>")])
def esc_xml(s):return s.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')
def esc_xml_attr(s):return esc_xml(s).replace('"','&quot;')
def make_sections_generic(blocks):
    root=[];stack=[(0,root)]
    for b in blocks:
        if b.get("t")=="Header":
            lvl=b["c"][0]
            while len(stack)>1 and stack[-1][0]>=lvl:stack.pop()
            sec={"t":"_Section","level":lvl,"title":b["c"][2],"attr":b["c"][1],"children":[]}
            stack[-1][1].append(sec);stack.append((lvl,sec["children"]))
        else:stack[-1][1].append(b)
    return root

