        blocks=make_sections_generic(doc.get("blocks",[]))
        out=render(self.blocks(blocks),columns=self.opts.columns if self.opts else 72,wrap=self.opts.wrap if self.opts else "auto")
        return out,{}
    def blocks(self,blocks):return join_docs([self.block(b) for b in blocks],Cr())
    def block(self,b):
        t=b.get("t");c=b.get("c")
        if t=="_Section":
            attrs=[]
            if b["attr"] and b["attr"][0]:attrs.append(("id",b["attr"][0]))
            docs=[xml_elem("title",[],self.inlines(b["title"]),block=False)]
            if b["children"]:docs.append(self.blocks(b["children"]))
            return xml_elem("sec",attrs,join_docs(docs,Cr()),block=True)
        if t in ("Para","Plain"):return xml_elem("p",[],self.inlines(c),block=False)
        if t=="BlockQuote":return xml_elem("disp-quote",[],self.blocks(c),block=True)
        if t=="CodeBlock":
            attr,code=c;attrs=[]
            if attr and attr[1]:attrs.append(("language",attr[1][0]))
            return Cat([xml_open("code",attrs),Text(esc_xml(code)),Text("</code>")])
        if t in ("BulletList","OrderedList"):
            ordered=t=="OrderedList";items=c[1] if ordered else c
            lis=[]
            for item in items:
                inner=join_docs([self.block(x if x.get("t")!="Plain" else {"t":"Para","c":x["c"]}) for x in item],Cr())
                lis.append(xml_elem("list-item",[],inner,block=True))
