            return xml_elem("def-list",[],join_docs(items,Cr()),block=True)
        if t=="HorizontalRule":return Empty()
        if t=="RawBlock":
            fmt=c[0] if isinstance(c[0],str) else "";return Literal(c[1]) if fmt in ("jats","xml") else Empty()
        if t=="Table":return self.table_doc(b)
        if t=="Div":return self.blocks(c[1])
        if t=="Figure":
            attr,caption,blocks=c
            docs=[]
            if caption[1]:docs.append(xml_elem("caption",[],self.blocks(caption[1]),block=True))
            docs.append(self.blocks(blocks));return xml_elem("fig",[("id",attr[0])] if attr and attr[0] else [],join_docs(docs,Cr()),block=True)
        if t=="LineBlock":return xml_elem("preformat",[],Literal("\n".join(stringify(x) for x in c)),block=False)
        return Empty()
    def table_doc(self,b):
        attr,caption,specs,head,bodies,foot=b["c"]
        def rowdoc(row,header=False):
            cells=[]
            for idx,cell in enumerate(row[1]):
                tag="th" if header else "td";align={"AlignLeft":"left","AlignRight":"right","AlignCenter":"center"}.get(specs[idx][0]["t"])
                attrs=[("align",align)] if align else []
                blocks=cell[4];inner=self.inlines(blocks[0]["c"]) if len(blocks)==1 and blocks[0].get("t") in ("Plain","Para") else self.blocks(blocks)
                cells.append(xml_elem(tag,attrs,inner,block=False))
            return xml_elem("tr",[],join_docs(cells,Cr()),block=True)
        inner=[]
        if head[1]:inner.append(xml_elem("thead",[],join_docs([rowdoc(r,True) for r in head[1]],Cr()),block=True))
        bodyrows=[]
