        if t=="Space":return BS()
        if t=="SoftBreak":return SoftBreak()
        if t=="Emph":return xml_elem("italic",[],self.inlines(c),block=False)
        if t=="Strong":return xml_elem("bold",[],self.inlines(c),block=False)
        if t=="Code":return xml_elem("monospace",[],Text(esc_xml(c[1])),block=False)
        if t=="Strikeout":return xml_elem("strike",[],self.inlines(c),block=False)
        if t=="Superscript":return xml_elem("sup",[],self.inlines(c),block=False)
        if t=="Subscript":return xml_elem("sub",[],self.inlines(c),block=False)
        if t=="Underline":return xml_elem("underline",[],self.inlines(c),block=False)
        if t=="SmallCaps":return xml_elem("sc",[],self.inlines(c),block=False)
        if t=="Quoted":return Cat([Text("“" if c[0]["t"]=="DoubleQuote" else "‘"),self.inlines(c[1]),Text("”" if c[0]["t"]=="DoubleQuote" else "’")])
        if t=="Link":
            attr,inls,target=c
            attrs=[("ext-link-type","uri"),("xlink:href",target[0])]
