        if t=="Image":
            attr,alt,target=c;src=target[0];sub=src.rsplit('.',1)[-1].lower() if '.' in src else ""
            inner=Cat([Cr(),Nest("  ",xml_elem("alt-text",[],Text(esc_xml(stringify(alt))),block=False)),Cr()])
            return Cat([xml_open("inline-graphic",[("mimetype","image"),("mime-subtype",sub),("xlink:href",src)]),inner,Text("</inline-graphic>")])
        if t=="Math":
            from .html import tex_to_mathml
            mm=tex_to_mathml(c[1],c[0]["t"]=="DisplayMath").replace("<math ",'<mml:math ').replace("</math>","</mml:math>")
            # Our tex_to_mathml tags are unprefixed mi etc; JATS expects mml: prefix on all MathML elements. Convert simple tags.
            mm=re.sub(r'<(mi|mn|mo|msup|msub|mfrac|semantics|annotation)([ >])',r'<mml:\1\2',mm);mm=re.sub(r'</(mi|mn|mo|msup|msub|mfrac|semantics|annotation)>',r'</mml:\1>',mm)
            return Cat([Text("<inline-formula><alternatives>"),Cr(),Text(f"<tex-math><![CDATA[{c[1]}]]></tex-math>"),Cr(),Text(mm+"</alternatives></inline-formula>")])
        if t=="Note":
            self.fn_num+=1;return Text(f'<xref ref-type="fn" rid="fn{self.fn_num}">{self.fn_num}</xref>')
        if t=="Span":return self.inlines(c[1])
        if t=="Cite":
