            return self.inlines(c[1])
        if t=="RawInline":
            fmt=c[0] if isinstance(c[0],str) else "";return Text(c[1]) if fmt in ("jats","xml") else Empty()
        if t=="LineBreak":return Text("<break />")
        return Empty()

