class TeiWriter:
    def __init__(self,opts,exts):
        self.opts=opts;self.exts=exts or {}
    def write(self,doc):
        blocks=make_sections_generic(doc.get("blocks",[]))
        out=render(self.blocks(blocks),columns=self.opts.columns if self.opts else 72,wrap=self.opts.wrap if self.opts else "auto")
        return out,{}
    def blocks(self,blocks):return join_docs([self.block(b) for b in blocks],Cr())
    def block(self,b):
        t=b.get("t");c=b.get("c")
        if t=="_Section":
            attrs=[("type",f"level{b['level']}")]
            if b["attr"] and b["attr"][0]:attrs.append(("xml:id",b["attr"][0]))
            docs=[xml_elem("head",[],self.inlines(b["title"]),block=False)]
            if b["children"]:docs.append(self.blocks(b["children"]))
            return xml_elem("div",attrs,join_docs(docs,Cr()),block=True)
        if t in ("Para","Plain"):return xml_elem("p",[],self.inlines(c),block=False)
        if t=="BlockQuote":
            # TEI quote element contains blocks but in fragment output earlier block quote was just a paragraph with style? Std TEI snippet needed
            return xml_elem("quote",[],self.blocks(c),block=True)
        if t=="CodeBlock":
            lang=c[0][1][0] if c[0] and c[0][1] else ""
            typ=f"codeblock {lang}".strip()
            return Cat([xml_open("ab",[("type",typ)]),Cr(),Literal(esc_xml(c[1])),Cr(),Text("</ab>")])
        if t in ("BulletList","OrderedList"):
            items=c[1] if t=="OrderedList" else c
            lis=[]
            for item in items:lis.append(xml_elem("item",[],self.blocks(item),block=True))
            typ="numbered" if t=="OrderedList" else "bulleted"
            return xml_elem("list",[("type",typ)],join_docs(lis,Cr()),block=True)
        if t=="DefinitionList":
            docs=[]
            # TEI uses list type definition with label/item pairs (not wrapped per pair)
            for term,defs in c:
                for d in defs:
                    docs.append(xml_elem("label",[],self.inlines(term),block=True));docs.append(xml_elem("item",[],self.blocks(d),block=True))
            return xml_elem("list",[("type","definition")],join_docs(docs,Cr()),block=True)
        if t=="HorizontalRule":return xml_open("milestone",[("unit","undefined"),("type","separator"),("rendition","line")],self_close=True)
        if t=="Table":
            attr,caption,specs,head,bodies,foot=b["c"];rows=[]
            if head[1]:
                for row in head[1]:rows.append(xml_elem("row",[("role","label")],join_docs([xml_elem("cell",[],xml_elem("p",[],self.inlines(cell[4][0]["c"]) if cell[4] else Empty(),block=False),block=False) for cell in row[1]],Cr()),block=True))
            for _,_,inter,bodyrows in bodies:
                for row in inter+bodyrows:rows.append(xml_elem("row",[],join_docs([xml_elem("cell",[],xml_elem("p",[],self.inlines(cell[4][0]["c"]) if cell[4] else Empty(),block=False),block=False) for cell in row[1]],Cr()),block=True))
            return xml_elem("table",[],join_docs(rows,Cr()),block=True)
        if t=="Div":return self.blocks(c[1])
        if t=="Figure":return self.blocks(c[2])
        if t=="LineBlock":return xml_elem("lg",[],join_docs([xml_elem("l",[],self.inlines(x),block=False) for x in c],Cr()),block=True)
        if t=="RawBlock":
            fmt=c[0] if isinstance(c[0],str) else "";return Literal(c[1]) if fmt in ("tei","xml") else Empty()
        return Empty()
    def inlines(self,inls):return Cat([self.inline(x) for x in inls])
    def inline(self,x):
        t=x.get("t");c=x.get("c")
        if t=="Str":return Text(esc_xml(c))
        if t=="Space":return BS()
        if t=="SoftBreak":return SoftBreak()
        if t=="Emph":return xml_elem("hi",[("rendition","simple:italic")],self.inlines(c),block=False)
        if t=="Strong":return xml_elem("hi",[("rendition","simple:bold")],self.inlines(c),block=False)
        if t=="Strikeout":return xml_elem("hi",[("rendition","simple:strikethrough")],self.inlines(c),block=False)
        if t=="Superscript":return xml_elem("hi",[("rendition","simple:superscript")],self.inlines(c),block=False)
        if t=="Subscript":return xml_elem("hi",[("rendition","simple:subscript")],self.inlines(c),block=False)
        if t=="Code":return xml_elem("seg",[("type","code")],Text(esc_xml(c[1])),block=False)
        if t=="Link":return xml_elem("ref",[("target",c[2][0])],self.inlines(c[1]),block=False)
        if t=="Image":
            # TEI figure/graphic
            return Cat([xml_open("figure",[]),Cr(),Text(f'<graphic url="{esc_xml_attr(c[2][0])}" />'),Cr(),Text("</figure>")])
        if t=="Math":return xml_elem("formula",[("notation","TeX")],Text(esc_xml(c[1])),block=False)
        if t=="Note":return xml_elem("note",[],self.blocks(c),block=True)
        if t=="Quoted":return Cat([Text("“" if c[0]["t"]=="DoubleQuote" else "‘"),self.inlines(c[1]),Text("”" if c[0]["t"]=="DoubleQuote" else "’")])
        if t=="Span":return self.inlines(c[1])
        if t=="Cite":return self.inlines(c[1])
        if t=="RawInline":
            fmt=c[0] if isinstance(c[0],str) else "";return Text(c[1]) if fmt in ("tei","xml") else Empty()
        if t=="LineBreak":return Text("<lb />")
        return Empty()

