        body=self.blocks(doc.get("blocks",[]))
        out=render(body,columns=self.opts.columns if self.opts else 72,wrap=self.opts.wrap if self.opts else "auto")
        extra={"automatic-styles":self.automatic_styles()}
        return out,extra
    def automatic_styles(self):
        parts=[]
        # List styles are already rendered strings with internal lines indented relative style start; template variable is alone with indent 4 in template, subsequent lines get nest by template engine (our variable is a string, template variable alone line indentation will nest). Definitions here should start at col0 relative.
        for name,defn in self.list_styles:parts.append(defn)
        for name,props in self.text_styles:
            parts.append(f'<style:style style:name="{name}" style:family="text"><style:text-properties {props} /></style:style>')
        parts.append('<style:style style:name="fr2" style:family="graphic" style:parent-style-name="Formula"><style:graphic-properties style:vertical-pos="middle" style:vertical-rel="text" style:horizontal-pos="center" style:horizontal-rel="paragraph-content" style:wrap="none" /></style:style>')
        parts.append('<style:style style:name="fr1" style:family="graphic" style:parent-style-name="Formula"><style:graphic-properties style:vertical-pos="middle" style:vertical-rel="text" /></style:style>')
        for name,parent,extra_attrs,props in self.para_styles:
            attrs=f' style:list-style-name="{extra_attrs}"' if extra_attrs else ''
            if props:
                parts.append(f'<style:style style:name="{name}" style:family="paragraph" style:parent-style-name="{parent}"{attrs}>\n  <style:paragraph-properties {props} />\n</style:style>')
            else:
                parts.append(f'<style:style style:name="{name}" style:family="paragraph" style:parent-style-name="{parent}"{attrs}>\n</style:style>')
        for defn in self.table_styles:parts.append(defn)
        return "\n".join(parts)
    def char_style(self,props_tuple):
        if props_tuple in self.text_style_map:return self.text_style_map[props_tuple]
        name=f"T{len(self.text_styles)+1}";self.text_style_map[props_tuple]=name
        props=props_tuple
