    # convert letters to italic spans individually and scripts to styled spans
    docs=[];i=0
    while i<len(tex):
        ch=tex[i]
        if ch.isalpha():docs.append(writer.styled_span('fo:font-style="italic" style:font-style-asian="italic" style:font-style-complex="italic"',[{"t":"Str","c":ch}]));i+=1
