class IcmlWriter:
    def __init__(self,opts,exts):
        self.opts=opts;self.exts=exts or {};self.char_styles=[];self.par_styles=[];self.hyperlinks=[];self.hyperlink_num=0
    def write(self,doc):
        body=self.blocks(doc.get("blocks",[]))
        s=render(body,columns=self.opts.columns if self.opts else 100000,wrap="none")
        extra={}
        # Templates variables in ICML template are $charStyles$, $parStyles$, $hyperlinks$, $objectStyles$
        extra["charStyles"]="\n".join(self.char_styles)
        extra["parStyles"]="\n".join(self.par_styles)
        if self.hyperlinks:extra["hyperlinks"]="\n".join(self.hyperlinks)
        return s,extra
    def ensure_char_style(self,name,xml_def):
        if any(f'CharacterStyle/{name}"' in d for d in self.char_styles):return name
        self.char_styles.append(xml_def);return name
    def para_style_range(self,style,inner,add_br=True):
        # Register par style definition if custom (template templates may replace default definitions in parStyles for Heading etc with BasedOn)
        self.ensure_par_style(style)
        doc=Cat([Text(f'<ParagraphStyleRange AppliedParagraphStyle="ParagraphStyle/{style}">'),Cr(),Nest("  ",inner),Cr(),Text("</ParagraphStyleRange>")])
        if add_br:doc=Cat([doc,Cr(),Text("<Br />")])
        return doc
    def ensure_par_style(self,name):
        if any(f'ParagraphStyle/{name}"' in d for d in self.par_styles):return
        # Minimal definition based on Normal for custom names, specific defaults for known styles will be refined based standalone comparisons
        self.par_styles.append(f'<ParagraphStyle Self="ParagraphStyle/{name}" Name="{name}">\n  <Properties>\n    <BasedOn type="object">$ID/NormalParagraphStyle</BasedOn>\n  </Properties>\n</ParagraphStyle>')
    def char_range(self,style,content_doc):
        # style could be NormalCharacterStyle special $ID
        self_name=f"CharacterStyle/{style}" if style!="NormalCharacterStyle" else "$ID/NormalCharacterStyle"
        if style!="NormalCharacterStyle":self.ensure_named_char_style(style)
        return Cat([Text(f'<CharacterStyleRange AppliedCharacterStyle="{self_name}">'),Cr(),Nest("  ",content_doc),Cr(),Text("</CharacterStyleRange>")])
    def ensure_named_char_style(self,name):
        defs={
        "Italic":'<CharacterStyle Self="CharacterStyle/Italic" Name="Italic" FontStyle="Italic">\n  <Properties>\n    <BasedOn type="object">$ID/NormalCharacterStyle</BasedOn>\n  </Properties>\n</CharacterStyle>',
        "Bold":'<CharacterStyle Self="CharacterStyle/Bold" Name="Bold" FontStyle="Bold">\n  <Properties>\n    <BasedOn type="object">$ID/NormalCharacterStyle</BasedOn>\n  </Properties>\n</CharacterStyle>',
        }
        if name in defs:self.ensure_char_style(name,defs[name])
    def blocks(self,blocks):return join_docs([self.block(b) for b in blocks],Cr())
    def block(self,b):
        t=b.get("t");c=b.get("c")
        if t=="Header":
            style=f"Heading{c[0]}";return self.para_style_range(style,self.char_range("NormalCharacterStyle",self.content_inlines(c[2])))
        if t in ("Para","Plain"):
            return self.para_style_range("Paragraph",self.char_range("NormalCharacterStyle",self.content_inlines(c)))
        if t=="BlockQuote":
            # Each para in quote gets Blockquote style
            docs=[]
            for blk in c:
                if blk.get("t") in ("Para","Plain"):docs.append(self.para_style_range("Blockquote",self.char_range("NormalCharacterStyle",self.content_inlines(blk["c"]))))
                else:docs.append(self.block(blk))
            return join_docs(docs,Cr())
        if t=="BulletList":
            docs=[]
            for item in c:
                for blk in item:
                    if blk.get("t") in ("Plain","Para"):docs.append(self.para_style_range("BulletList",self.char_range("NormalCharacterStyle",self.content_inlines(blk["c"]))))
                    else:docs.append(self.block(blk))
            return join_docs(docs,Cr())
        if t=="OrderedList":
            docs=[]
            for item in c[1]:
                for blk in item:
                    if blk.get("t") in ("Plain","Para"):docs.append(self.para_style_range("NumList",self.char_range("NormalCharacterStyle",self.content_inlines(blk["c"]))))
                    else:docs.append(self.block(blk))
