    def table_doc(self,b):
        attr,caption,specs,head,bodies,foot=b["c"]
        header_rows=head[1];body_rows=[]
        for _,_,inter,rows in bodies:body_rows.extend(inter+rows)
        ncols=len(specs)
        docs=[Text(f'<Table AppliedTableStyle="TableStyle/Table" HeaderRowCount="{len(header_rows)}" BodyRowCount="{len(body_rows)}" ColumnCount="{ncols}">')]
        for idx in range(ncols):docs.append(Text(f'<Column Name="{idx}" />'))
        allrows=[(True,r) for r in header_rows]+[(False,r) for r in body_rows]
        for ridx,(is_head,row) in enumerate(allrows):
            for cidx,cell in enumerate(row[1]):
                align=specs[cidx][0]["t"];align_name={"AlignRight":"RightAlign","AlignCenter":"CenterAlign","AlignLeft":"LeftAlign","AlignDefault":""}.get(align,"")
                kind="TableHeader" if is_head else "TablePar"
                style=f"TablePar &gt; {kind} &gt; {align_name}" if False else f"TablePar > {'TableHeader' if is_head else 'TablePar'} > {align_name}"
                # Original uses AppliedParagraphStyle strings with &gt; in XML output (escaped >) and a par style named "TablePar > TableHeader > RightAlign" etc.
                content=self.content_inlines(cell[4][0]["c"]) if cell[4] else Empty()
                cellinner=self.para_style_range(style,self.char_range("NormalCharacterStyle",content),add_br=False)
                docs.append(Cat([Text(f'<Cell Name="{cidx}:{ridx}" AppliedCellStyle="CellStyle/Cell">'),Cr(),Nest("  ",cellinner),Cr(),Text("</Cell>")]))
        docs.append(Text("</Table>"))
        return join_docs(docs,Cr())
    def content_inlines(self,inls):
        # Returns a sequence of CharacterStyleRange docs? ICML structure: a ParagraphStyleRange contains one or more CharacterStyleRanges, each with <Content>...</Content> and <Br /> for line breaks.
        # Our char_range wraps this whole content for normal style surrounding; for styled inlines (em etc.), ICML splits CharacterStyleRange per segment. This helper returns a Doc of CharacterStyleRanges, so callers should not wrap it again.
        return self.inline_ranges(inls)
    def inline_ranges(self,inls,current_style="NormalCharacterStyle"):
        # Group consecutive plain text
        ranges=[];buf=""
        def flush():
            nonlocal buf
            if buf:
                ranges.append(self.raw_char_range(current_style,buf));buf=""
        for x in inls:
            t=x.get("t")
            if t=="Str":buf+=x["c"];continue
            if t=="Space":buf+=" ";continue
            if t=="SoftBreak":buf+=" ";continue
            if t=="Emph":flush();ranges.append(self.raw_char_range("Italic",stringify(x["c"])));continue
            if t=="Strong":flush();ranges.append(self.raw_char_range("Bold",stringify(x["c"])));continue
            if t=="Code":flush();ranges.append(self.raw_char_range(current_style,x["c"][1]));continue
            if t=="Link":
                flush();self.hyperlink_num+=1;hid=f"hyperlink{self.hyperlink_num}"
                # Hyperlink definitions at document end uses Hyperlink element; inline becomes HyperlinkTextSource inside a character range - approximate: run link text as normal range and register hyperlink def
                self.hyperlinks.append(f'<Hyperlink Self="{hid}" Name="{esc_xml_attr(stringify(x["c"][1]))}" DestinationURL="{esc_xml_attr(x["c"][2][0])}" Hidden="false" />')
                ranges.append(self.raw_char_range(current_style,stringify(x["c"][1])));continue
            if t=="Image":buf+=f"[IMAGE: {stringify(x['c'][1])}]";continue
            buf+=stringify(x)
        flush()
        return join_docs(ranges,Cr()) if ranges else self.raw_char_range(current_style,"")
    def raw_char_range(self,style,text):
        if style!="NormalCharacterStyle":self.ensure_named_char_style(style)
        self_name=f"CharacterStyle/{style}" if style!="NormalCharacterStyle" else "$ID/NormalCharacterStyle"
        return Cat([Text(f'<CharacterStyleRange AppliedCharacterStyle="{self_name}">'),Cr(),Nest("  ",Text(f"<Content>{esc_xml(text)}</Content>")),Cr(),Text("</CharacterStyleRange>")])

