# ---------- Wiki family ----------
class WikiWriter:
    def __init__(self,opts,exts,fmt):
        self.opts=opts;self.exts=exts or {};self.fmt=fmt;self.footnotes=[]
    def write(self,doc):
        docs=[self.blocks(doc.get("blocks",[]))]
        if self.footnotes and self.fmt in ("mediawiki","textile","jira","muse","haddock"):
            docs.append(self.footnote_defs())
        out=render(join_docs(docs,Blank()),columns=self.opts.columns if self.opts else 72,wrap=self.opts.wrap if self.opts else "auto")
        return out,{}
    def blocks(self,blocks):
        # Jira headings don't blank separate following para; handle custom join in jira
        if self.fmt=="jira":
            if not blocks:return Empty()
            docs=[self.block(b) for b in blocks];out=docs[0]
            for idx in range(1,len(docs)):
                sep=Cr() if blocks[idx-1].get("t") in ("Header","HorizontalRule") else Blank()
                out=Cat([out,sep,docs[idx]])
            return out
        return join_docs([self.block(b) for b in blocks],Blank())
    def block(self,b):
        t=b.get("t");c=b.get("c");fmt=self.fmt
        if t in ("Para","Plain"):return self.inlines(c)
        if t=="Header":
            lvl,attr,inls=c;txt=self.inlines(inls);hid=attr[0] if attr else ""
            if fmt=="mediawiki":
                docs=[]
                if hid:docs.append(Text(f'<span id="{hid}"></span>'));docs.append(Cr())
                docs.append(Cat([Text("="*lvl+" "),txt,Text(" "+"="*lvl)]));return Cat(docs)
            if fmt=="dokuwiki":return Cat([Text("="*(7-lvl)+" "),txt,Text(" "+"="*(7-lvl))])
            if fmt=="textile":return Cat([Text(f"h{lvl}"+(f"(#{hid})" if hid else "")+". "),txt])
            if fmt=="jira":return Cat([Text(f"h{lvl}. "+"{anchor:"+hid+"}" if hid else f"h{lvl}. "),txt]) if hid else Cat([Text(f"h{lvl}. "),txt])
            if fmt=="muse":return Cat([Text("*"*lvl+" "),txt])
            if fmt=="haddock":
                docs=[Cat([Text("="*lvl+" "),txt])]
                if hid:docs.append(Cr());docs.append(Text(f"#{hid}#"))
                return Cat(docs)
            if fmt=="xwiki":return Cat([Text("="*lvl+" "),txt,Text(" {{id name=\""+hid+"\" /}}"+"="*lvl if hid else "="*lvl)])
            if fmt=="zimwiki":return Cat([Text("="*(7-lvl)+" "),txt,Text(" "+"="*(7-lvl))])
        if t=="BlockQuote":
            inner=self.blocks(c)
            if fmt=="mediawiki":return Cat([Text("<blockquote>"),inner,Cr(),Text("</blockquote>")])
            if fmt=="dokuwiki":
                s=render(inner,columns=(self.opts.columns-2 if self.opts else 70),wrap=self.opts.wrap if self.opts else "auto").rstrip("\n");return Literal("\n".join("> "+l if l else ">" for l in s.split("\n")))
            if fmt=="textile":return Cat([Text("bq. "),inner])
            if fmt=="jira":
                # one para quote as bq.
                if len(c)==1 and c[0].get("t") in ("Para","Plain"):return Cat([Text("bq. "),self.inlines(c[0]["c"])])
                return Cat([Text("{quote}"),Cr(),inner,Cr(),Text("{quote}")])
            if fmt=="muse":return Cat([Text("<quote>"),Cr(),inner,Cr(),Text("</quote>")])
            if fmt=="haddock":return inner
            if fmt=="xwiki":
                s=render(inner,columns=(self.opts.columns-2 if self.opts else 70),wrap=self.opts.wrap if self.opts else "auto").rstrip("\n");return Literal("\n".join(">"+l if l else ">" for l in s.split("\n")))
            if fmt=="zimwiki":
                s=render(inner,columns=(self.opts.columns-2 if self.opts else 70),wrap=self.opts.wrap if self.opts else "auto").rstrip("\n");return Literal("\n".join("> "+l if l else ">" for l in s.split("\n")))
            return inner
        if t=="CodeBlock":
            attr,code=c;lang=attr[1][0] if attr and attr[1] else ""
            if fmt=="mediawiki":return Literal(f'<syntaxhighlight lang="{lang}">{code}</syntaxhighlight>' if lang else "\n".join(" "+l for l in code.split("\n")))
            if fmt=="dokuwiki":return Literal(f"<code{(' '+lang) if lang else ''}>\n{code}\n</code>")
