            if fmt=="textile":return Cat([Text('"'),self.inlines(inls),Text(f'":{url}')])
            if fmt=="jira":return Cat([Text("["),self.inlines(inls),Text(f"|{url}]")])
            if fmt=="muse":return Cat([Text(f"[[{url}]["),self.inlines(inls),Text("]]")])
            if fmt=="haddock":return Cat([Text(f"<{url} "),self.inlines(inls),Text(">")])
            if fmt=="xwiki":return Cat([Text("[["),self.inlines(inls),Text(f">>{url}]]")])
            if fmt=="zimwiki":return Cat([Text(f"[[{url}|"),self.inlines(inls),Text("]]")])
            return self.inlines(inls)
