def jira_math(tex):
    out="";i=0
    while i<len(tex):
        if tex[i].isalpha():out+=f"_{tex[i]}_";i+=1
        elif tex[i]=='^':out+="^"+tex[i+1]+"^";i+=2
        elif tex[i]=='_':out+="{~}"+tex[i+1]+"{~}";i+=2
        else:out+=tex[i];i+=1
    return out
def muse_math(tex):
    out="";i=0
    while i<len(tex):
        if tex[i].isalpha():out+=f"*{tex[i]}*";i+=1
        elif tex[i]=='^':out+=f"<sup>{tex[i+1]}</sup>";i+=2
        elif tex[i]=='_':out+=f"<sub>{tex[i+1]}</sub>";i+=2
        else:out+=tex[i];i+=1
    return out

def wiki_table(writer,b):
    fmt=writer.fmt;attr,caption,specs,head,bodies,foot=b["c"]
    def cell_text(blocks):
        if len(blocks)==1 and blocks[0].get("t") in ("Plain","Para"):return render(writer.inlines(blocks[0]["c"]),columns=100000,wrap="none")
        return stringify(blocks).strip().replace("\n"," ")
    header=[cell_text(c[4]) for c in head[1][0][1]] if head[1] else []
    rows=[]
    for _,_,inter,rr in bodies:
        for r in inter+rr:rows.append([cell_text(c[4]) for c in r[1]])
    if fmt=="mediawiki":
        lines=['{| class="wikitable"']
        if header:
            lines.append("|-")
            for idx,h in enumerate(header):
                align=specs[idx][0]["t"];style={"AlignRight":'style="text-align: right;"',"AlignLeft":'style="text-align: left;"',"AlignCenter":'style="text-align: center;"'}.get(align,"")
                lines.append(f"! {style}| {h}" if style else f"! {h}")
        for r in rows:
            lines.append("|-")
            for idx,cell in enumerate(r):
                align=specs[idx][0]["t"];style={"AlignRight":'style="text-align: right;"',"AlignLeft":'style="text-align: left;"',"AlignCenter":'style="text-align: center;"'}.get(align,"")
                lines.append(f"| {style}| {cell}" if style else f"| {cell}")
        lines.append("|}");return Literal("\n".join(lines))
    if fmt=="dokuwiki":
        ncol=len(specs);widths=[]
        for idx in range(ncol):
            vals=([header[idx]] if header else [])+[r[idx] for r in rows];widths.append(max(str_width(v) for v in vals))
        def fmtrow(cells,sep):
            parts=[]
            for idx,txt in enumerate(cells):
                align=specs[idx][0]["t"]
                if align=="AlignRight":parts.append(" "+txt.rjust(widths[idx]+1))
                elif align=="AlignCenter":parts.append(" "+txt.center(widths[idx]+1))
                else:parts.append(txt.ljust(widths[idx]+2))
            return sep+sep.join(parts)+sep
        lines=[]
        if header:lines.append(fmtrow(header,'^'))
        for r in rows:lines.append(fmtrow(r,'|'))
        return Literal("\n".join(lines))
    if fmt=="textile":
        lines=[]
        if header:lines.append("|"+"|".join(f"_. {h}" for h in header)+"|")
        for r in rows:
            cells=[]
            for idx,cell in enumerate(r):
                a=specs[idx][0]["t"];pre={ "AlignRight":">.","AlignLeft":"<.","AlignCenter":"=.","AlignDefault":""}.get(a,"")
                cells.append(pre+" "+cell if pre else cell)
            lines.append("|"+"|".join(cells)+"|")
        return Literal("\n".join(lines))
    if fmt=="jira":
        lines=[]
        if header:lines.append("|| "+" || ".join(header)+" ||")
        for r in rows:lines.append("| "+" | ".join(r)+" |")
        return Literal("\n".join(lines))
    if fmt=="muse":
        # header is first row with double pipes between cells and no outer pipes
        lines=[]
        if header:lines.append(" "+" || ".join(header))
        for r in rows:lines.append(" "+" |  ".join(r) if False else " "+" | ".join(r))
        return Literal("\n".join(lines))
    if fmt=="haddock":
        # Grid table format
        ncol=len(specs);widths=[]
        for idx in range(ncol):
            vals=([header[idx]] if header else [])+[r[idx] for r in rows];widths.append(max(str_width(v) for v in vals)+2)
        def sep(ch='-'):
            parts=[]
            for idx,w in enumerate(widths):
                seg=ch*w
                if ch=='=':
                    a=specs[idx][0]["t"]
                    if a=="AlignRight":seg=seg[:-1]+':'
                    elif a=="AlignLeft":seg=':'+seg[1:]
                    elif a=="AlignCenter":seg=':'+seg[1:-1]+':'
                parts.append(seg)
            return "+"+"+".join(parts)+"+"
        def row(cells):
            return "|"+"|".join(" "+cells[i].ljust(widths[i]-1) for i in range(ncol))+"|"
        lines=[sep('-')]
        if header:lines.append(row(header));lines.append(sep('='))
        for r in rows:lines.append(row(r))
        lines.append(sep('-'));return Literal("\n".join(lines))
    if fmt=="xwiki":
        lines=[]
        if header:lines.append("|="+" |=".join(header))
        for r in rows:lines.append("|"+" |".join(r))
        return Literal("\n".join(lines))
    if fmt=="zimwiki":
        lines=[]
        ncol=len(specs);widths=[]
        for idx in range(ncol):
            vals=([header[idx]] if header else [])+[r[idx] for r in rows];widths.append(max(3,max(str_width(v) for v in vals)))
        if header:
            lines.append("|"+"|".join(header)+"|")
            delim=[]
            for idx in range(ncol):
                a=specs[idx][0]["t"];w=widths[idx]
                delim.append((":"+"-"*(w-1)) if a=="AlignLeft" else ("-"*(w-1)+":") if a=="AlignRight" else (":"+"-"*(w-2)+":") if a=="AlignCenter" else "-"*w)
            lines.append("|"+"|".join(delim)+"|")
        for r in rows:
            cells=[]
            for idx,txt in enumerate(r):
                a=specs[idx][0]["t"];cells.append(txt.rjust(widths[idx]) if a=="AlignRight" else txt.center(widths[idx]) if a=="AlignCenter" else txt.ljust(widths[idx]))
            lines.append("|"+"|".join(cells)+"|")
        return Literal("\n".join(lines))
    return Literal("")

# ---------- RTF ----------
class RtfWriter:
    def __init__(self,opts,exts):
        self.opts=opts;self.exts=exts or {};self.prev_para=False
    def write(self,doc):
        docs=[]
        for b in doc.get("blocks",[]):docs.append(self.block(b,0))
        out="\n".join(docs)
        if out and not out.endswith("\n"):out+="\n"
        return out,{}
    def blocks(self,blocks,indent=0):
        return "\n".join(self.block(b,indent) for b in blocks if self.block(b,indent)!="")
    # Note re-calling block above would duplicate side effects; implement properly below by overriding blocks method after class via helper? We'll actually implement blocks as straightforward:
    def block(self,b,indent=0):
        t=b.get("t");c=b.get("c")
        if t=="Header":
            lvl=c[0];size={1:36,2:32,3:28,4:24,5:20,6:18}.get(lvl,18)
            return rtf_para(self.inlines(c[2]),align="ql",sa=180,li=indent,extra=rf"\outlinelevel{lvl-1} \b \fs{size} ")
        if t in ("Para","Plain"):
            return rtf_para(self.inlines(c),align="ql",sa=180,li=indent)
        if t=="BlockQuote":
            # paragraphs inside get li720
            inner=[]
            for blk in c:inner.append(self.block(blk,720))
            return "\n".join(inner)
        if t=="CodeBlock":
            # each line a para with \f1
            lines=c[1].split("\n")
            return "\n".join(rtf_para(esc_rtf(line),sa=180,li=indent,extra=r"\f1 ") for line in lines)
        if t=="BulletList":return self.list_doc(c,False,indent)
        if t=="OrderedList":return self.list_doc(c,True,indent)
        if t=="DefinitionList":
            paras=[]
            for term,defs in c:
                paras.append(rtf_para(self.inlines(term),sa=0,li=indent))
                for d in defs:
                    for blk in d:
                        if blk.get("t") in ("Plain","Para"):paras.append(rtf_para(self.inlines(blk["c"]),sa=0,li=indent+360))
                        else:paras.append(self.block(blk,indent+360))
                    # last definition para gets \sa180 inside its para text before \par as per original (handled by rtf para ending) - pattern in std: Definition line itself is {.. \sa0 ... Definition of term\sa180\par}. Our helper doesn't.
            return "\n".join(paras)
        if t=="HorizontalRule":return rtf_para(r"\emdash\emdash\emdash\emdash\emdash",align="qc",sa=180,li=indent)
        if t=="LineBlock":
            return "\n".join(rtf_para(self.inlines(x),sa=0,li=indent) for x in c)
        if t=="Table":return rtf_table(self,b)
        if t=="Div":return "\n".join(self.block(x,indent) for x in c[1])
        if t=="Figure":return "\n".join(self.block(x,indent) for x in c[2])
        if t=="RawBlock":
            fmt=c[0] if isinstance(c[0],str) else "";return c[1] if fmt=="rtf" else ""
        return ""
    def list_doc(self,data,ordered,indent=0):
        if ordered:lattr,items=data;start=lattr[0]
        else:items=data;start=1
        paras=[]
        # List item indent increases 360 per level starting at 360
        li_indent=indent+360
        for idx,item in enumerate(items):
            marker=(f"{start+idx}." if ordered else r"\bullet")
            # First block is item para: make a para with marker+tab
            first=True
            for blk in item:
                if first and blk.get("t") in ("Plain","Para"):
                    content=marker+r"\tx360\tab "+self.inlines(blk["c"])
                    is_last=(idx==len(items)-1)
                    # In original, last item of a list that is followed by something (?) has \sa180 attached at end of its text before \par and spacing \sa0 in para props; if list is last in section, still.
                    paras.append(rtf_para_raw(content,sa=0,li=li_indent,fi=-360,trailing_sa=is_last))
                    first=False
                elif blk.get("t") in ("BulletList","OrderedList"):
                    paras.append(self.list_doc(blk["c"] if blk.get("t")=="BulletList" else blk["c"],blk.get("t")=="OrderedList",li_indent))
                else:
                    paras.append(self.block(blk,li_indent));first=False
        return "\n".join(paras)
    def inlines(self,inls):return "".join(self.inline(x) for x in inls)
    def inline(self,x):
        t=x.get("t");c=x.get("c")
        if t=="Str":return esc_rtf(c)
        if t=="Space":return " "
        if t=="SoftBreak":return " "
        if t=="Emph":return r"{\i "+self.inlines(c)+"}"
        if t=="Strong":return r"{\b "+self.inlines(c)+"}"
        if t=="Code":return r"{\f1 "+esc_rtf(c[1])+"}"
        if t=="Strikeout":return r"{\strike "+self.inlines(c)+"}"
        if t=="Superscript":return r"{\super "+self.inlines(c)+"}"
        if t=="Subscript":return r"{\sub "+self.inlines(c)+"}"
        if t=="Underline":return r"{\ul "+self.inlines(c)+"}"
        if t=="SmallCaps":return r"{\scaps "+self.inlines(c)+"}"
        if t=="Quoted":return ("“" if c[0]["t"]=="DoubleQuote" else "‘")+self.inlines(c[1])+("”" if c[0]["t"]=="DoubleQuote" else "’")
        if t=="Math":return rtf_math(self,c[1])
        if t=="Link":
            url=c[2][0]
            return r'{\field{\*\fldinst{HYPERLINK "'+url+r'"}}{\fldrslt{\ul'+'\n'+self.inlines(c[1])+'\n}}}'
        if t=="Image":
            # If image can be fetched/embedded, original would embed pict; missing resource warning is generated in grab main stage? We'll attempt app-less: just placeholder colored - app logger not available here.
            src=c[2][0];return r"{\cf1 [image: "+src+r"]\cf0}"
        if t=="Note":
            inner="\n".join(self.block(b) for b in c)
            return r"{\super\chftn}{\*\footnote\chftn\~\plain\pard "+inner.rstrip()+"\n}"
        if t=="RawInline":
            fmt=c[0] if isinstance(c[0],str) else "";return c[1] if fmt=="rtf" else ""
        if t=="Span":return self.inlines(c[1])
        if t=="Cite":return self.inlines(c[1])
        if t=="LineBreak":return r"\\"
        return ""
# Fix RtfWriter.blocks implementation (avoid double calling above note)
def _rtf_blocks(self,blocks,indent=0):
    return "\n".join(x for x in (self.block(b,indent) for b in blocks) if x!="")
RtfWriter.blocks=_rtf_blocks

def rtf_para(content,align="ql",sa=180,li=0,fi=0,extra=""):
    return rtf_para_raw(content,align,sa,li,fi,extra,False)
def rtf_para_raw(content,align="ql",sa=180,li=0,fi=0,extra="",trailing_sa=False):
    trail=r"\sa180" if trailing_sa else ""
    return "{"+rf"\pard \{align} \f0 \sa{sa} \li{li} \fi{fi} "+extra+content+trail+r"\par}"
def esc_rtf(s):
    out=""
    for ch in s:
        if ch=='\\':out+=r'\\'
        elif ch=='{':out+=r'\{'
        elif ch=='}':out+=r'\}'
        elif ord(ch)>127:
            out+=f"\\u{ord(ch)}?"
        else:out+=ch
    return out
def rtf_math(writer,tex):
    out="";i=0
    while i<len(tex):
        ch=tex[i]
        if ch.isalpha():out+=r"{\i "+ch+"}";i+=1
        elif ch in '^_':
            kind=r"\super" if ch=='^' else r"\sub";i+=1;arg=tex[i] if i<len(tex) else "";i+=1;out+="{"+kind+" "+arg+"}"
        elif ch.isspace():out+=" ";i+=1
        else:out+=esc_rtf(ch);i+=1
    return out
def rtf_table(writer,b):
    attr,caption,specs,head,bodies,foot=b["c"];ncol=len(specs)
    total=8640;each=total//max(ncol,1);widths=[each*(i+1) for i in range(ncol)]
    def align_code(a):return {"AlignRight":"qr","AlignCenter":"qc","AlignLeft":"ql","AlignDefault":"ql"}[a]
    rows=[]
    if head[1]:rows.append((True,head[1][0]))
    for _,_,inter,rr in bodies:
        for r in inter+rr:rows.append((False,r))
    parts=[]
    for is_head,row in rows:
        parts.append("{")
        parts.append(r"\trowd \trgaph120")
        if is_head:parts.append("".join(rf"\clbrdrb\brdrs\cellx{w}" for w in widths))
        else:parts.append("".join(rf"\cellx{w}" for w in widths))
        parts.append(r"\trkeep\intbl")
        parts.append("{")
        for idx,cell in enumerate(row[1]):
            inner=writer.inlines(cell[4][0]["c"]) if cell[4] and cell[4][0].get("t") in ("Plain","Para") else ""
            para="{"+rf"\pard\intbl \{align_code(specs[idx][0]['t'])} \f0 \sa0 \li0 \fi0 "+inner+r"\par}"
            parts.append(para);parts.append(r"\cell}")
        parts.append("}");parts.append(r"\intbl\row}")
