    parts.append(rtf_para("",sa=180,li=0))
    return "\n".join(parts)

# ---------- OPML ----------
class OpmlWriter:
    def __init__(self,opts,exts):self.opts=opts;self.exts=exts or {}
    def write(self,doc):
        from .markdown import write_markdown
        # OPML body is handled in template: $body$ is outlines; if not standalone and doc has no headings, body returns "\n" in fragment just from headings traversal
        outlines=make_sections_generic(doc.get("blocks",[]))
        lines=[]
        def render_sections(sections,indent):
            for sec in sections:
                if sec.get("t")!="_Section":continue
                title=stringify(sec["title"]).strip()
                # Note attribute is markdown of section's non-heading direct blocks (before subsections)
                direct=[b for b in sec["children"] if b.get("t")!="_Section"]
                note=""
                if direct:
                    s,_=write_markdown({"meta":{},"blocks":direct},self.opts,self.exts,"markdown");note=s.strip()
                child_lines=render_sections(sec["children"],indent+1)
                attrs=f'text="{esc_xml_attr(title)}"' + (f' _note="{esc_xml_attr(note)}"' if note else "")
                if child_lines:
                    lines.append("  "*indent+f"<outline {attrs}>")
                    lines.extend(child_lines);lines.append("  "*indent+"</outline>")
                else:
                    lines.append("  "*indent+f"<outline {attrs} />")
            return lines
        render_sections(outlines,0)
        body="\n".join(lines)
        return body,{}

# ---------- BBCode ----------
class BBCodeWriter:
    def __init__(self,opts,exts,fmt):
        self.opts=opts;self.exts=exts or {};self.fmt=fmt;self.footnotes=[]
    def write(self,doc):
        body=self.blocks(doc.get("blocks",[]));docs=[body]
        if self.footnotes:
            docs.append(Text("* * *"));docs.append(self.footnote_defs())
        return render(join_docs(docs,Blank()),columns=self.opts.columns if self.opts else 72,wrap=self.opts.wrap if self.opts else "auto"),{}
    def blocks(self,blocks):return join_docs([self.block(b) for b in blocks],Blank())
    def block(self,b):
        t=b.get("t");c=b.get("c")
        if t in ("Para","Plain"):return self.inlines(c)
        if t=="Header":
            lvl=c[0]
            if lvl==1:return Cat([Text("[u][b]"),self.inlines(c[2]),Text("[/b][/u]")])
            return Cat([Text("[b]"),self.inlines(c[2]),Text("[/b]")])
        if t=="BlockQuote":return Cat([Text("[quote]"),Cr(),self.blocks(c),Cr(),Text("[/quote]")])
        if t=="CodeBlock":
            lang=c[0][1][0] if c[0] and c[0][1] else ""
            return Literal(f"[code={lang}]"+c[1]+"\n[/code]" if lang else f"[code]{c[1]}\n[/code]")
        if t=="BulletList":return self.list_doc(c,False)
        if t=="OrderedList":return self.list_doc(c,True)
        if t=="DefinitionList":
            docs=[]
            for term,defs in c:
                docs.append(self.inlines(term))
                inner_docs=[]
                for d in defs:inner_docs.append(Cat([Text("[*]"),self.blocks(d)]))
                docs.append(Cat([Text("[list]"),Cr(),join_docs(inner_docs,Cr()),Cr(),Text("[/list]")]))
            return join_docs(docs,Cr())
        if t=="HorizontalRule":return Text("* * *")
        if t=="Table":
            lines=["[table]"]
            attr,caption,specs,head,bodies,foot=c
            def row(r,header=False):
                tag="th" if header else "td";return "[tr]"+"".join(f"[{tag}]"+render(self.inlines(cell[4][0]["c"]) if cell[4] else Empty(),columns=100000,wrap="none")+f"[/{tag}]" for cell in r[1])+"[/tr]"
            if head[1]:lines.append(row(head[1][0],True))
            for _,_,inter,rows in bodies:
                for r in inter+rows:lines.append(row(r))
            lines.append("[/table]");return Literal("\n".join(lines))
        if t=="Div":return self.blocks(c[1])
        if t=="Figure":return self.blocks(c[2])
        if t=="LineBlock":return join_docs([self.inlines(x) for x in c],Cr())
        if t=="RawBlock":return Literal(c[1]) if (c[0] if isinstance(c[0],str) else "")=="bbcode" else Empty()
        return Empty()
    def list_doc(self,data,ordered):
        items=data[1] if ordered else data
        open_tag="[list=1]" if ordered else "[list]"
        docs=[Text(open_tag)]
        for item in items:
            # If item has nested list, the nested list is included after plain with a blank line in original.
            inner_docs=[]
            for blk in item:
                if blk.get("t") in ("Plain","Para"):inner_docs.append(Cat([Text("[*]"),self.inlines(blk["c"])]))
                else:inner_docs.append(self.block(blk))
            docs.append(join_docs(inner_docs,Blank()))
        docs.append(Text("[/list]"));return join_docs(docs,Cr())
    def footnote_defs(self):
        docs=[]
        for idx,blocks in enumerate(self.footnotes,1):docs.append(Cat([Text(f"({idx}) "),self.blocks(blocks)]))
        return join_docs(docs,Blank())
    def inlines(self,inls):return Cat([self.inline(x) for x in inls])
    def inline(self,x):
        t=x.get("t");c=x.get("c")
        if t=="Str":return Text(c)
        if t=="Space":return BS()
        if t=="SoftBreak":return SoftBreak()
        if t=="Emph":return Cat([Text("[i]"),self.inlines(c),Text("[/i]")])
        if t=="Strong":return Cat([Text("[b]"),self.inlines(c),Text("[/b]")])
        if t=="Underline":return Cat([Text("[u]"),self.inlines(c),Text("[/u]")])
        if t=="Strikeout":return Cat([Text("[s]"),self.inlines(c),Text("[/s]")])
        if t=="Code":return Text(c[1])
        if t=="Link":return Cat([Text(f"[url={c[2][0]}]"),self.inlines(c[1]),Text("[/url]")])
        if t=="Image":
            alt_txt=stringify(c[1]);return Text(f'[img alt="{alt_txt}"]{c[2][0]}[/img]')
        if t=="Note":self.footnotes.append(c);return Text(f"({len(self.footnotes)})")
        if t=="Math":return Text(f"${c[1]}$")
        if t=="Quoted":return Cat([Text("“" if c[0]["t"]=="DoubleQuote" else "‘"),self.inlines(c[1]),Text("”" if c[0]["t"]=="DoubleQuote" else "’")])
        if t=="Superscript":return Cat([Text("[sup]"),self.inlines(c),Text("[/sup]")])
        if t=="Subscript":return Cat([Text("[sub]"),self.inlines(c),Text("[/sub]")])
        if t=="Span":return self.inlines(c[1])
        if t=="Cite":return self.inlines(c[1])
        if t=="LineBreak":return Cr()
        return Empty()

# ---------- Vimdoc ----------
class VimdocWriter:
    def __init__(self,opts,exts):self.opts=opts;self.exts=exts or {};self.footnotes=[]
    def write(self,doc):
        docs=[]
        for b in doc.get("blocks",[]):docs.append(self.block(b))
        out=render(join_docs(docs,Blank()),columns=self.opts.columns if self.opts else 72,wrap=self.opts.wrap if self.opts else "auto")
        extra={}
        # vimdoc template vars: filename/combined-title/toc-reminder/toc/modeline are generated by Vimdoc writer from metadata/options. Simplified:
        extra["toc-reminder"]="Table of contents: use `gO` in Helpgrep"
        extra["modeline"]="vim:tw=78:ts=8:noet:ft=help:norl:"
        return out,extra
    def block(self,b):
        t=b.get("t");c=b.get("c")
        cols=self.opts.columns if self.opts else 72
        if t=="Header":
            lvl,attr,inls=c;title=stringify(inls).strip();tag=f"*{attr[0]}*" if attr and attr[0] else ""
            if lvl==1:
                sep="="*cols
                line=title+" "*(max(1,cols-len(title)-len(tag)))+tag if tag else title
                return Cat([Text(sep),Cr(),Text(line)])
            sep="-"*cols;line=title+" "*(max(1,cols-len(title)-len(tag)))+tag if tag else title
            return Cat([Text(sep),Cr(),Text(line)])
        if t in ("Para","Plain"):return self.inlines(c)
        if t=="BlockQuote":return Nest("  ",self.blocks(c))
        if t=="BulletList":
            docs=[]
            for item in c:docs.append(Cat([Text("- "),Nest("  ",self.blocks(item))]))
            return join_docs(docs,Cr())
        if t=="OrderedList":
            docs=[]
            for idx,item in enumerate(c[1],c[0][0]):docs.append(Cat([Text(f"{idx}. "),Nest("  ",self.blocks(item))]))
            return join_docs(docs,Cr())
        if t=="DefinitionList":
            docs=[]
            for term,defs in c:
                for d in defs:docs.append(join_docs([self.inlines(term),Nest("    ",self.blocks(d))],Cr()))
            return join_docs(docs,Blank())
        if t=="CodeBlock":
            lang=c[0][1][0] if c[0] and c[0][1] else ""
            indented="\n".join("    "+l for l in c[1].split("\n"))
            return Literal(f">{lang}\n{indented}\n<")
        if t=="HorizontalRule":
            cols=self.opts.columns if self.opts else 72
            pat=" * * *"
            return Text((pat*((cols//len(pat))+1))[:cols].rstrip())
        if t=="Table":
            # Vimdoc tables are plain text aligned with spaces and a header line ending ~
            attr,caption,specs,head,bodies,foot=c
            rows=[];header=[]
            if head[1]:header=[stringify(cell[4]).strip() for cell in head[1][0][1]]
            for _,_,inter,rr in bodies:
                for r in inter+rr:rows.append([stringify(cell[4]).strip() for cell in r[1]])
            ncol=len(specs);widths=[]
            for idx in range(ncol):
                vals=([header[idx]] if header else [])+[r[idx] for r in rows];widths.append(max(str_width(v) for v in vals))
            def fmt(cells,header=False):
                line=" ".join(cells[i].ljust(widths[i]) for i in range(ncol)).rstrip()
                # indent tables by (cols - table width)/2? In std table was centered with 6 spaces. Total width sum+spaces. Center within columns.
                total=sum(widths)+ncol-1;indent=max(0,(cols-total)//2)
                return " "*indent+line+(" ~" if header else "")
            lines=[]
            if header:lines.append(fmt(header,True))
            for r in rows:lines.append(fmt(r))
            return Literal("\n".join(lines))
        if t=="Div":return self.blocks(c[1])
        if t=="Figure":return self.blocks(c[2])
        if t=="LineBlock":return join_docs([self.inlines(x) for x in c],Cr())
        if t=="RawBlock":return Literal(c[1]) if (c[0] if isinstance(c[0],str) else "")=="vimdoc" else Empty()
        return Empty()
    def blocks(self,blocks):return join_docs([self.block(b) for b in blocks],Blank())
    def inlines(self,inls):return Cat([self.inline(x) for x in inls])
    def inline(self,x):
        t=x.get("t");c=x.get("c")
        if t=="Str":return Text(c)
        if t=="Space":return BS()
        if t=="SoftBreak":return SoftBreak()
        if t in ("Emph","Strong","Underline","Strikeout","SmallCaps","Superscript","Subscript","Span"):
            return self.inlines(c[1] if t=="Span" else c)
        if t=="Code":return Text("`"+c[1]+"`")
        if t=="Link":
            txt=stringify(c[1])
            if c[2][0]==txt or txt=="":return Text(c[2][0])
            return Cat([self.inlines(c[1]),BS(),Text(c[2][0])])
        if t=="Image":
            return Text("") if False else Cat([self.inlines(c[1]),Text("")]) if False else Text("")
        if t=="Note":
            self.footnotes.append(c);idx=len(self.footnotes);return Text(f"|footnote{idx}|")
        if t=="Math":return Text("`$"+c[1]+"$`")
        if t=="Quoted":return Cat([Text("“" if c[0]["t"]=="DoubleQuote" else "‘"),self.inlines(c[1]),Text("”" if c[0]["t"]=="DoubleQuote" else "’")])
        if t=="Cite":return self.inlines(c[1])
        if t=="LineBreak":return Cr()
        return Empty()
    # Footnotes in vimdoc are handled as separate sections at end with a separator line and *footnoteN* tag. Our write() currently doesn't append them; patch later if needed.

def write_wiki(doc,opts,exts,fmt,app):return WikiWriter(opts,exts,fmt).write(doc)
def write_rtf(doc,opts,exts,fmt,app):return RtfWriter(opts,exts).write(doc)
def write_opml(doc,opts,exts,fmt,app):return OpmlWriter(opts,exts).write(doc)
def write_bbcode(doc,opts,exts,fmt,app):return BBCodeWriter(opts,exts,fmt).write(doc)
def write_vimdoc(doc,opts,exts,fmt,app):
    w=VimdocWriter(opts,exts);out,extra=w.write(doc)
    if w.footnotes:
        docs=[]
        cols=opts.columns if opts else 72
        docs.append(Text((" *"*((cols//2))).rstrip()))
        for idx,blocks in enumerate(w.footnotes,1):
            tag=f"*footnote{idx}*";docs.append(Text(" "*(cols-len(tag))+tag));docs.append(w.blocks(blocks))
        out=render(join_docs([w.blocks(doc.get("blocks",[]))]+docs,Blank()),columns=cols,wrap=opts.wrap if opts else "auto")
    return out,extra
