    def list_doc(self,data,ordered,level):
        items=data[1] if ordered else data
        start=data[0][0] if ordered else 1
        docs=[]
        for idx,item in enumerate(items):
            if self.fmt=="dokuwiki":
                indent="  "*(level+1);marker=("-" if ordered else "*")
                docs.append(Cat([Text(indent+marker+" "),Nest(indent+"  ",self.item_blocks(item,level))]))
            elif self.fmt=="mediawiki":
                marker=("#" if ordered else "*")*(level+1);docs.append(Cat([Text(marker+" "),self.item_blocks(item,level)]))
            elif self.fmt=="muse":
                indent=" "*(level+1) if level==0 else " "*(level+2)
                marker=f"{start+idx}." if ordered else "-";docs.append(Cat([Text(indent+marker+" "),Nest(" "*(len(indent)+len(marker)+1),self.item_blocks(item,level))]))
            elif self.fmt=="haddock":
                indent="    "*level;marker=(f"{start+idx}. " if ordered else "-   ")
                docs.append(Cat([Text(indent+marker),Nest(" "*(len(indent)+len(marker)),self.item_blocks(item,level))]))
            elif self.fmt=="zimwiki" and level>0:
                indent="\t"*level;marker=(f"{start+idx}." if ordered else "*");docs.append(Cat([Text(indent+marker+" "),Nest(indent+"  ",self.item_blocks(item,level))]))
            elif self.fmt=="xwiki":
                marker=("1." if ordered else "*.");docs.append(Cat([Text(marker+" "),Nest("  ",self.item_blocks(item,level))]))
            else:
                if self.fmt=="textile":marker=("#" if ordered else "*")*(level+1)
                elif self.fmt=="jira":marker=("#" if ordered else "*")*(level+1)
                else:marker=(f"{start+idx}." if ordered else "*")
                indentstr="  "*level if self.fmt not in ("textile","jira") else ""
                docs.append(Cat([Text(indentstr+marker+" "),Nest(" "*(len(indentstr)+len(marker)+1),self.item_blocks(item,level))]))
        loose=any(any(x.get("t")=="Para" for x in item) for item in items)
        return join_docs(docs,Blank() if loose else Cr())
    def item_blocks(self,blocks,level):
        docs=[]
        for b in blocks:
            if b.get("t")=="BulletList":docs.append(self.list_doc(b["c"],False,level+1))
            elif b.get("t")=="OrderedList":docs.append(self.list_doc(b["c"],True,level+1))
            else:docs.append(self.block(b))
        # For most wikis, a sublist follows item text on next line (Cr); mediawiki sublists are represented by marker repetition and are separate top-level lines, but our item structure joins nested list with Cr too. If multiple paras, Blank.
