def jira_math(tex):
    out="";i=0
    while i<len(tex):
        if tex[i].isalpha():out+=f"_{tex[i]}_";i+=1
        elif tex[i]=='^':out+="^"+tex[i+1]+"^";i+=2
        elif tex[i]=='_':out+="{~}"+tex[i+1]+"{~}";i+=2
        else:out+=tex[i];i+=1
    return out
def muse_math(tex):
    out="";i=0
    while i<len(tex):
        if tex[i].isalpha():out+=f"*{tex[i]}*";i+=1
        elif tex[i]=='^':out+=f"<sup>{tex[i+1]}</sup>";i+=2
        elif tex[i]=='_':out+=f"<sub>{tex[i+1]}</sub>";i+=2
        else:out+=tex[i];i+=1
    return out

