            lines.append("|-")
            for idx,cell in enumerate(r):
                align=specs[idx][0]["t"];style={"AlignRight":'style="text-align: right;"',"AlignLeft":'style="text-align: left;"',"AlignCenter":'style="text-align: center;"'}.get(align,"")
