    if typ=='frac':return expr_to_typst(node[1])+" / "+expr_to_typst(node[2])
    if typ=='sqrt':return f"sqrt({expr_to_typst(node[2])})"
    if typ=='text':return f'upright("{node[1]}")'
    if typ=='styled':
        inner=expr_to_typst(node[2])
        if node[1]=='bold':return f"bold({inner})"
        if node[1]=='roman':return f"upright({inner})"
        if node[1]=='bb':return f"upright(bold({inner}))" if False else inner
        return inner
    if typ=='command':
