        return node[1]
    return ""
def script_typst(node):
    s=expr_to_typst(node)
    # Parenthesize if contains spaces/operators or length >1 and not a single token/group
    if re.search(r'[\s=+\-]',s):return f"({s})"
    return s

def log_could_not_convert(logger,tex,msg=""):
    if logger:
        logger.log("CouldNotConvertTeXMath","WARNING",f"Could not convert TeX math {tex}, rendering as TeX",contents=tex,message=msg)
